Vec* vec_new(void) { Vec* v = xcalloc(1, sizeof(Vec)); return v; }
void vec_free(Vec* v) { if (!v) return; free(v->items); free(v); }
static void vec_grow(Vec* v) {
   if (v->size >= v->cap) { v->cap = v->cap ? v->cap * 2 : 16; v->items = xrealloc(v->items, sizeof(void*) * v->cap); }
}
void vec_push(Vec* v, void* p) { vec_grow(v); v->items[v->size++] = p; }
void vec_insert(Vec* v, int idx, void* p) {
   if (idx < 0) idx = 0;
   if (idx > v->size) idx = v->size;
   vec_grow(v);
   memmove(v->items + idx + 1, v->items + idx, sizeof(void*) * (v->size - idx));
   v->items[idx] = p; v->size++;
}
void* vec_remove(Vec* v, int idx) {
   if (idx < 0 || idx >= v->size) return NULL;
   void* p = v->items[idx];
   memmove(v->items + idx, v->items + idx + 1, sizeof(void*) * (v->size - idx - 1));
   v->size--;
   return p;
}
void vec_clear(Vec* v) { v->size = 0; }
void vec_swap(Vec* v, int a, int b) { void* t = v->items[a]; v->items[a] = v->items[b]; v->items[b] = t; }
static int (*g_cmp)(const void*, const void*);
static int qcmp(const void* a, const void* b) { return g_cmp(*(void* const*)a, *(void* const*)b); }
void vec_sort(Vec* v, int (*cmp)(const void*, const void*)) {
   /* stable merge sort to keep deterministic behavior */
   if (v->size < 2) return;
   void** tmp = xmalloc(sizeof(void*) * v->size);
   for (int width = 1; width < v->size; width *= 2) {
      for (int i = 0; i < v->size; i += 2 * width) {
         int lo = i, mid = MINI(i + width, v->size), hi = MINI(i + 2 * width, v->size);
         int a = lo, b = mid, k = lo;
         while (a < mid && b < hi) {
            if (cmp(v->items[b], v->items[a]) < 0) tmp[k++] = v->items[b++];
            else tmp[k++] = v->items[a++];
         }
         while (a < mid) tmp[k++] = v->items[a++];
         while (b < hi) tmp[k++] = v->items[b++];
      }
      memcpy(v->items, tmp, sizeof(void*) * v->size);
   }
   free(tmp);
   (void)qcmp; (void)g_cmp;
}
void vec_isort(Vec* v, int (*cmp)(const void*, const void*)) {
   for (int i = 1; i < v->size; i++) {
      void* t = v->items[i];
      int j = i - 1;
      while (j >= 0 && cmp(v->items[j], t) > 0) { v->items[j+1] = v->items[j]; j--; }
      v->items[j+1] = t;
   }
}
int vec_indexOf(const Vec* v, const void* p) {
   for (int i = 0; i < v->size; i++) if (v->items[i] == p) return i;
   return -1;
}
