#include "rstr.h"
#include <stdarg.h>

void rs_init(RStr* s) { s->ch = NULL; s->len = 0; s->cap = 0; s->highlightAttr = 0; }
void rs_free(RStr* s) { free(s->ch); s->ch = NULL; s->len = s->cap = 0; }
void rs_reset(RStr* s) { s->len = 0; s->highlightAttr = 0; if (s->ch) s->ch[0] = 0; }
static void rs_ensure(RStr* s, int n) {
   if (n + 1 > s->cap) {
      int nc = s->cap ? s->cap : 64;
      while (nc < n + 1) nc *= 2;
      s->ch = xrealloc(s->ch, sizeof(chtype) * nc);
      s->cap = nc;
   }
}
static inline chtype mapc(unsigned char c) { return c >= 32 ? c : '?'; }
void rs_appendn(RStr* s, int attr, const char* str, int n) {
   rs_ensure(s, s->len + n);
   for (int i = 0; i < n; i++) s->ch[s->len + i] = mapc((unsigned char)str[i]) | attr;
   s->len += n;
   s->ch[s->len] = 0;
}
