      }
   } else {
      for (int j = 0; j < this->size; j++) {
         this->keys[j] = xstrdup(FunctionBar_FKeys[j]);
         this->events[j] = FunctionBar_FEvents[j];
      }
   }
   return this;
}
void FunctionBar_delete(FunctionBar* this) {
   if (!this) return;
   for (int i = 0; i < this->size; i++) { free(this->functions[i]); free(this->keys[i]); }
   free(this->functions); free(this->keys); free(this->events); free(this);
}
void FunctionBar_setLabel(FunctionBar* this, int event, const char* text) {
   for (int i = 0; i < this->size; i++) {
      if (this->events[i] == event) {
         free(this->functions[i]);
         this->functions[i] = xstrdup(text);
         break;
      }
   }
}
void FunctionBar_draw(const FunctionBar* this) { FunctionBar_drawExtra(this, NULL, -1, false); }
void FunctionBar_drawExtra(const FunctionBar* this, const char* buffer, int attr, bool setCursor) {
   attrset(CRT_colors[FUNCTION_BAR]);
   mvhline(LINES - 1, 0, ' ', COLS);
   int x = 0;
   for (int i = 0; i < this->size; i++) {
      attrset(CRT_colors[FUNCTION_KEY]);
      mvaddstr(LINES - 1, x, this->keys[i]);
      x += strlen(this->keys[i]);
      attrset(CRT_colors[FUNCTION_BAR]);
      mvaddstr(LINES - 1, x, this->functions[i]);
      x += strlen(this->functions[i]);
   }
   if (buffer) {
      if (attr == -1) attrset(CRT_colors[FUNCTION_BAR]);
      else attrset(attr);
      mvaddstr(LINES - 1, x, buffer);
      x += strlen(buffer);
   }
   attrset(CRT_colors[RESET_COLOR]);
   if (setCursor) {
      CRT_cursorX = x;
      curs_set(1);
   } else {
      curs_set(0);
   }
   currentLen = x;
}
void FunctionBar_append(const char* buffer, int attr) {
   if (attr == -1) attrset(CRT_colors[FUNCTION_BAR]);
   else attrset(attr);
   mvaddstr(LINES - 1, currentLen + 1, buffer);
   attrset(CRT_colors[RESET_COLOR]);
   currentLen += strlen(buffer) + 1;
}
int FunctionBar_synthesizeEvent(const FunctionBar* this, int pos) {
   int x = 0;
   for (int i = 0; i < this->size; i++) {
      x += strlen(this->keys[i]);
      x += strlen(this->functions[i]);
      if (pos < x) return this->events[i];
   }
   return ERR;
}

/* ---------- Panel ---------- */
Panel* Panel_new(int x, int y, int w, int h, bool owner, FunctionBar* fuBar) {
   Panel* this = xcalloc(1, sizeof(Panel));
   Panel_init(this, x, y, w, h, owner, fuBar);
   return this;
}
void Panel_init(Panel* this, int x, int y, int w, int h, bool owner, FunctionBar* fuBar) {
   this->x = x; this->y = y; this->w = w; this->h = h;
   this->cursorX = 0; this->cursorY = 0;
   this->eventHandlerState = NULL;
   this->items = vec_new();
   this->ownsItems = owner;
   this->scrollV = 0; this->scrollH = 0;
   this->selected = 0; this->oldSelected = 0; this->selectedLen = 0;
   this->needsRedraw = true;
   this->cursorOn = false;
   this->wasFocus = false;
   rs_init(&this->header);
   this->defaultBar = fuBar;
   this->currentBar = fuBar;
   this->selectionColorId = PANEL_SELECTION_FOCUS;
}
void Panel_done(Panel* this) {
   free(this->eventHandlerState);
   Panel_prune(this);
   vec_free(this->items);
   FunctionBar_delete(this->defaultBar);
   rs_free(&this->header);
}
void Panel_delete(Panel* this) {
   if (!this) return;
   if (this->destroy) { this->destroy(this); return; }
   Panel_done(this);
   free(this);
}
void Panel_setSelectionColor(Panel* this, int colorId) { this->selectionColorId = colorId; }
void Panel_setHeader(Panel* this, const char* header) {
   rs_reset(&this->header);
   rs_append(&this->header, CRT_colors[PANEL_HEADER_FOCUS], header);
   this->needsRedraw = true;
}
void Panel_move(Panel* this, int x, int y) { this->x = x; this->y = y; this->needsRedraw = true; }
void Panel_resize(Panel* this, int w, int h) { this->w = w; this->h = h; this->needsRedraw = true; }
void Panel_prune(Panel* this) {
   if (this->ownsItems) {
      for (int i = 0; i < this->items->size; i++) {
         Item* it = this->items->items[i];
         if (it && it->cls->destroy) it->cls->destroy(it);
      }
   }
   vec_clear(this->items);
   this->scrollV = 0;
   this->selected = 0;
   this->oldSelected = 0;
   this->needsRedraw = true;
}
void Panel_add(Panel* this, Item* o) { vec_push(this->items, o); this->needsRedraw = true; }
void Panel_insert(Panel* this, int i, Item* o) { vec_insert(this->items, i, o); this->needsRedraw = true; }
void Panel_set(Panel* this, int i, Item* o) {
   if (i < this->items->size) {
      Item* old = this->items->items[i];
      if (this->ownsItems && old && old != o && old->cls->destroy) old->cls->destroy(old);
      this->items->items[i] = o;
   } else {
      vec_push(this->items, o);
   }
}
Item* Panel_get(Panel* this, int i) { if (i < 0 || i >= this->items->size) return NULL; return this->items->items[i]; }
Item* Panel_remove(Panel* this, int i) {
   this->needsRedraw = true;
   Item* removed = vec_remove(this->items, i);
   if (this->selected > 0 && this->selected >= this->items->size) this->selected--;
   if (this->ownsItems && removed) { if (removed->cls->destroy) removed->cls->destroy(removed); return NULL; }
   return removed;
}
Item* Panel_getSelected(Panel* this) {
   if (this->items->size > 0) return this->items->items[this->selected];
   return NULL;
}
void Panel_moveSelectedUp(Panel* this) {
   if (this->selected > 0) {
      vec_swap(this->items, this->selected, this->selected - 1);
      this->selected--;
   }
}
void Panel_moveSelectedDown(Panel* this) {
   if (this->selected + 1 < this->items->size) {
      vec_swap(this->items, this->selected, this->selected + 1);
      this->selected++;
   }
}
int Panel_getSelectedIndex(const Panel* this) { return this->selected; }
int Panel_size(const Panel* this) { return this->items->size; }
void Panel_setSelected(Panel* this, int selected) {
   int size = this->items->size;
   if (selected >= size) selected = size - 1;
   if (selected < 0) selected = 0;
   this->selected = selected;
   if (this->eventHandler) this->eventHandler(this, EVENT_SET_SELECTED);
}
void Panel_splice(Panel* this, Vec* from) {
   for (int i = 0; i < from->size; i++) vec_push(this->items, from->items[i]);
   this->needsRedraw = true;
}

void Panel_draw(Panel* this, bool force_redraw, bool focus, bool highlightSelected, bool hideFunctionBar) {
   int size = this->items->size;
   int scrollH = this->scrollH;
   int y = this->y;
   int x = this->x;
   int h = this->h;
   if (hideFunctionBar) h++;

   int header_attr = focus ? CRT_colors[PANEL_HEADER_FOCUS] : CRT_colors[PANEL_HEADER_UNFOCUS];
   if (force_redraw) {
      if (this->printHeader) this->printHeader(this);
      else rs_setAttr(&this->header, header_attr);
   }
   int headerLen = this->header.len;
   if (headerLen > 0) {
      attrset(header_attr);
      mvhline(y, x, ' ', this->w);
      if (scrollH < headerLen) {
         rs_print(&this->header, y, x, scrollH, MINI(headerLen - scrollH, this->w));
      }
      attrset(CRT_colors[RESET_COLOR]);
      y++;
      h--;
   }

   if (this->scrollV < 0) {
      this->scrollV = 0;
      this->needsRedraw = true;
   } else if (this->scrollV > size - h) {
      this->scrollV = MAXI(size - h, 0);
      this->needsRedraw = true;
   }
   if (this->selected < this->scrollV) {
      this->scrollV = this->selected;
      this->needsRedraw = true;
   } else if (this->selected >= this->scrollV + h) {
      this->scrollV = this->selected - h + 1;
      this->needsRedraw = true;
   }

   int first = this->scrollV;
   int upTo = MINI(first + h, size);
   int selectionColor = focus ? CRT_colors[this->selectionColorId] : CRT_colors[PANEL_SELECTION_UNFOCUS];

   if (this->needsRedraw || force_redraw) {
      int line = 0;
      for (int i = first; line < h && i < upTo; i++) {
         Item* itemObj = this->items->items[i];
         RStr item; rs_init(&item);
         itemObj->cls->display(itemObj, &item);
         int itemLen = item.len;
         int amt = MINI(itemLen - scrollH, this->w);
         if (highlightSelected && i == this->selected) {
            item.highlightAttr = selectionColor;
         }
         if (item.highlightAttr) {
            attrset(item.highlightAttr);
            rs_setAttr(&item, item.highlightAttr);
            this->selectedLen = itemLen;
         }
         mvhline(y + line, x, ' ', this->w);
         if (amt > 0) rs_print(&item, y + line, x, scrollH, amt);
         if (item.highlightAttr) attrset(CRT_colors[RESET_COLOR]);
         rs_free(&item);
         line++;
      }
      while (line < h) {
         mvhline(y + line, x, ' ', this->w);
         line++;
      }
   } else {
      Item* oldObj = Panel_get(this, this->oldSelected);
      Item* newObj = Panel_get(this, this->selected);
      RStr o; rs_init(&o);
      RStr n; rs_init(&n);
      if (oldObj) oldObj->cls->display(oldObj, &o);
      if (newObj) newObj->cls->display(newObj, &n);
      int oldLen = o.len;
      int newLen = n.len;
      this->selectedLen = newLen;
      mvhline(y + this->oldSelected - first, x + 0, ' ', this->w);
      if (scrollH < oldLen && oldObj && this->oldSelected >= first && this->oldSelected < upTo)
         rs_print(&o, y + this->oldSelected - first, x, scrollH, MINI(oldLen - scrollH, this->w));
      if (this->oldSelected < first || this->oldSelected >= upTo) { /* nothing */ }
      attrset(selectionColor);
      mvhline(y + this->selected - first, x + 0, ' ', this->w);
      rs_setAttr(&n, selectionColor);
      if (scrollH < newLen && newObj)
         rs_print(&n, y + this->selected - first, x, scrollH, MINI(newLen - scrollH, this->w));
      attrset(CRT_colors[RESET_COLOR]);
      rs_free(&o); rs_free(&n);
   }

   if (focus && (this->needsRedraw || force_redraw || !this->wasFocus)) {
      if (this->drawFunctionBar) this->drawFunctionBar(this, hideFunctionBar);
      else if (!hideFunctionBar && this->currentBar) FunctionBar_draw(this->currentBar);
   }

   this->oldSelected = this->selected;
   this->wasFocus = focus;
   this->needsRedraw = false;
}

bool Panel_onKey(Panel* this, int key) {
   int size = this->items->size;
#define PANEL_SCROLL(amount) do { \
      this->selected += (amount); \
      this->scrollV = CLAMPI(this->scrollV + (amount), 0, MAXI(0, (size - this->h - Panel_headerHeight(this)))); \
      this->needsRedraw = true; } while (0)

   switch (key) {
   case KEY_DOWN:
   case KEY_CTRL('N'):
      this->selected++;
      break;
   case KEY_UP:
   case KEY_CTRL('P'):
      this->selected--;
      break;
   case KEY_LEFT:
   case KEY_CTRL('B'):
      if (this->scrollH > 0) {
         this->scrollH -= MAXI(CRT_scrollHAmount, 0);
         if (this->scrollH < 0) this->scrollH = 0;
         this->needsRedraw = true;
      }
      break;
   case KEY_RIGHT:
   case KEY_CTRL('F'):
      this->scrollH += CRT_scrollHAmount;
      this->needsRedraw = true;
      break;
   case KEY_PPAGE:
      PANEL_SCROLL(-(this->h - Panel_headerHeight(this)));
      break;
   case KEY_NPAGE:
      PANEL_SCROLL(+(this->h - Panel_headerHeight(this)));
      break;
   case KEY_WHEELUP:
      PANEL_SCROLL(-CRT_scrollWheelVAmount);
      break;
   case KEY_WHEELDOWN:
      PANEL_SCROLL(+CRT_scrollWheelVAmount);
      break;
   case KEY_HOME:
      this->selected = 0;
      break;
   case KEY_END:
      this->selected = size - 1;
      break;
   case KEY_CTRL('A'):
   case '^':
      this->scrollH = 0;
      this->needsRedraw = true;
      break;
   case KEY_CTRL('E'):
   case '$':
      this->scrollH = MAXI(this->selectedLen - this->w, 0);
      this->needsRedraw = true;
      break;
   default:
      return false;
   }
   if (this->selected < 0 || size == 0) {
      this->selected = 0;
      this->needsRedraw = true;
   } else if (this->selected >= size) {
      this->selected = size - 1;
      this->needsRedraw = true;
   }
#undef PANEL_SCROLL
   return true;
}

HandlerResult Panel_selectByTyping(Panel* this, int ch) {
   int size = Panel_size(this);
   if (!this->eventHandlerState) this->eventHandlerState = xcalloc(100, sizeof(char));
   char* buffer = this->eventHandlerState;
   if (0 < ch && ch < 255 && isgraph((unsigned char)ch)) {
      int len = strlen(buffer);
      if (!len) {
         if ('/' == ch) {
            ch = '\001';
         } else if ('q' == ch) {
            return BREAK_LOOP;
         }
      } else if (1 == len && '\001' == buffer[0]) {
         len--;
      }
      if (len < 99) {
         buffer[len] = (char)ch;
         buffer[len + 1] = '\0';
      }
      for (int try = 0; try < 2; try++) {
         len = strlen(buffer);
         for (int i = 0; i < size; i++) {
            const char* cur = ((ListItem*)Panel_get(this, i))->value;
            while (*cur == ' ') cur++;
            if (strncasecmp(cur, buffer, len) == 0) {
               Panel_setSelected(this, i);
               return HANDLED;
            }
         }
         buffer[0] = (char)ch;
         buffer[1] = '\0';
      }
      return HANDLED;
   } else if (ch != ERR) {
      buffer[0] = '\0';
   }
   if (ch == 13) return BREAK_LOOP;
   return IGNORED;
}
