static void readMeters(Settings* this, const char* line, int column) {
   char* trim = str_trim(line);
   char** ids = str_split(trim, ' ', NULL);
   free(trim);
   column = MINI(column, HeaderLayouts[this->hLayout].columns - 1);
   if (column < 0) { str_freeArray(ids); return; }
   str_freeArray(this->hColumns[column].names);
   this->hColumns[column].names = ids;
}

static void readMeterModes(Settings* this, const char* line, int column) {
   char* trim = str_trim(line);
   int len = 0;
   char** ids = str_split(trim, ' ', &len);
   free(trim);
   column = MINI(column, HeaderLayouts[this->hLayout].columns - 1);
   if (column < 0) { str_freeArray(ids); return; }
   this->hColumns[column].len = len;
   free(this->hColumns[column].modes);
   int* modes = len ? xcalloc(len, sizeof(int)) : NULL;
   for (int i = 0; i < len; i++) modes[i] = atoi(ids[i]);
   str_freeArray(ids);
   this->hColumns[column].modes = modes;
}

static bool validateMeters(Settings* this) {
   int colCount = HeaderLayouts[this->hLayout].columns;
   bool anyMeter = false;
   for (int column = 0; column < colCount; column++) {
      char** names = this->hColumns[column].names;
      const int* modes = this->hColumns[column].modes;
      int len = this->hColumns[column].len;
      if (!len) continue;
      if (!names || !modes) return false;
      anyMeter = true;
      int nn = 0;
      while (names[nn]) nn++;
      if (nn < len) return false;
   }
   return anyMeter;
}

void ScreenSettings_setFields(ScreenSettings* ss, const int* fields, int n) {
