int HeaderLayout_fromName(const char* name) {
   for (int i = 0; i < LAST_HEADER_LAYOUT; i++)
      if (str_eq(HeaderLayouts[i].name, name)) return i;
   return LAST_HEADER_LAYOUT;
}

static void freeColumns(MeterColumnSetting* cols, int n) {
   if (!cols) return;
   for (int i = 0; i < n; i++) {
      str_freeArray(cols[i].names);
      free(cols[i].modes);
   }
   free(cols);
}

void Settings_setHeaderLayout(Settings* this, HeaderLayout hLayout) {
   int oldColumns = HeaderLayouts[this->hLayout].columns;
   int newColumns = HeaderLayouts[hLayout].columns;
   if (newColumns > oldColumns) {
      this->hColumns = xrealloc(this->hColumns, newColumns * sizeof(MeterColumnSetting));
      memset(this->hColumns + oldColumns, 0, (newColumns - oldColumns) * sizeof(MeterColumnSetting));
   } else if (newColumns < oldColumns) {
      for (int i = newColumns; i < oldColumns; i++) {
         str_freeArray(this->hColumns[i].names);
         free(this->hColumns[i].modes);
      }
      this->hColumns = xrealloc(this->hColumns, newColumns * sizeof(MeterColumnSetting));
   }
   this->hLayout = hLayout;
   this->changed = true;
}

static void setColumn(Settings* this, int col, const char* const* names, const int* modes, int n) {
   MeterColumnSetting* c = &this->hColumns[col];
   str_freeArray(c->names);
   free(c->modes);
   c->names = xcalloc(n + 1, sizeof(char*));
   c->modes = xcalloc(n + 1, sizeof(int));
   for (int i = 0; i < n; i++) { c->names[i] = xstrdup(names[i]); c->modes[i] = modes[i]; }
   c->len = n;
}

void Settings_setDefaultMeters(Settings* this, int cpus) {
   int sizes[] = { 3, 3 };
   (void)sizes;
   int cols = HeaderLayouts[this->hLayout].columns;
   for (int i = 0; i < cols; i++) {
      str_freeArray(this->hColumns[i].names);
      free(this->hColumns[i].modes);
      this->hColumns[i].names = NULL; this->hColumns[i].modes = NULL; this->hColumns[i].len = 0;
   }
   free(this->hColumns);
   this->hLayout = HF_TWO_50_50;
   this->hColumns = xcalloc(2, sizeof(MeterColumnSetting));
   const char* left[4]; int lmodes[4]; int ln = 0;
   const char* right[5]; int rmodes[5]; int rn = 0;
   if (cpus > 128) {
      left[ln] = "CPU"; lmodes[ln++] = 1;
   } else if (cpus > 32) {
      left[ln] = "LeftCPUs8"; lmodes[ln++] = 1;
      right[rn] = "RightCPUs8"; rmodes[rn++] = 1;
   } else if (cpus > 16) {
      left[ln] = "LeftCPUs4"; lmodes[ln++] = 1;
      right[rn] = "RightCPUs4"; rmodes[rn++] = 1;
   } else if (cpus > 8) {
      left[ln] = "LeftCPUs2"; lmodes[ln++] = 1;
      right[rn] = "RightCPUs2"; rmodes[rn++] = 1;
   } else if (cpus > 4) {
      left[ln] = "LeftCPUs"; lmodes[ln++] = 1;
      right[rn] = "RightCPUs"; rmodes[rn++] = 1;
   } else {
      left[ln] = "AllCPUs"; lmodes[ln++] = 1;
   }
   left[ln] = "Memory"; lmodes[ln++] = 1;
   left[ln] = "Swap"; lmodes[ln++] = 1;
   right[rn] = "Tasks"; rmodes[rn++] = 2;
   right[rn] = "LoadAverage"; rmodes[rn++] = 2;
   right[rn] = "Uptime"; rmodes[rn++] = 2;
   setColumn(this, 0, left, lmodes, ln);
   setColumn(this, 1, right, rmodes, rn);
}

static void readMeters(Settings* this, const char* line, int column) {
   char* trim = str_trim(line);
   char** ids = str_split(trim, ' ', NULL);
   free(trim);
   column = MINI(column, HeaderLayouts[this->hLayout].columns - 1);
   if (column < 0) { str_freeArray(ids); return; }
   str_freeArray(this->hColumns[column].names);
   this->hColumns[column].names = ids;
}

static void readMeterModes(Settings* this, const char* line, int column) {
   char* trim = str_trim(line);
   int len = 0;
   char** ids = str_split(trim, ' ', &len);
   free(trim);
   column = MINI(column, HeaderLayouts[this->hLayout].columns - 1);
   if (column < 0) { str_freeArray(ids); return; }
   this->hColumns[column].len = len;
   free(this->hColumns[column].modes);
   int* modes = len ? xcalloc(len, sizeof(int)) : NULL;
   for (int i = 0; i < len; i++) modes[i] = atoi(ids[i]);
   str_freeArray(ids);
   this->hColumns[column].modes = modes;
}

static bool validateMeters(Settings* this) {
   int colCount = HeaderLayouts[this->hLayout].columns;
   bool anyMeter = false;
   for (int column = 0; column < colCount; column++) {
      char** names = this->hColumns[column].names;
      const int* modes = this->hColumns[column].modes;
      int len = this->hColumns[column].len;
      if (!len) continue;
      if (!names || !modes) return false;
      anyMeter = true;
      int nn = 0;
      while (names[nn]) nn++;
      if (nn < len) return false;
   }
   return anyMeter;
}

void ScreenSettings_setFields(ScreenSettings* ss, const int* fields, int n) {
   free(ss->fields);
   ss->fields = xcalloc(n + 1, sizeof(int));
   ss->flags = 0;
   for (int i = 0; i < n; i++) { ss->fields[i] = fields[i]; ss->flags |= Fields[fields[i]].flags; }
   ss->nFields = n;
}

static void readFields(ScreenSettings* ss, const char* line) {
   char* trim = str_trim(line);
   char** ids = str_split(trim, ' ', NULL);
   free(trim);
   int cap = LAST_PROCESSFIELD;
   int* fields = xcalloc(cap + 1, sizeof(int));
   int n = 0;
   for (int i = 0; ids[i] && n < cap; i++) {
      const char* id = ids[i];
      if (isdigit((unsigned char)id[0])) {
         int f = atoi(id) + 1;
         if (f > 0 && f < LAST_PROCESSFIELD && Fields[f].name) fields[n++] = f;
      } else {
         int f = Field_byName(id);
         if (f > 0) fields[n++] = f;
      }
   }
   str_freeArray(ids);
   ScreenSettings_setFields(ss, fields, n);
   free(fields);
}

ScreenSettings* Settings_newScreen(Settings* this, const char* name, const char* columns, const char* sortKeyName) {
   int sortKey = sortKeyName ? Field_byName(sortKeyName) : PID;
   if (sortKey < 0) sortKey = PID;
   bool sortDesc = Fields[sortKey].defaultSortDesc;
   ScreenSettings* ss = xcalloc(1, sizeof(ScreenSettings));
   ss->heading = xstrdup(name);
   ss->direction = sortDesc ? -1 : 1;
   ss->treeDirection = 1;
   ss->sortKey = sortKey;
   ss->treeSortKey = PID;
   readFields(ss, columns);
   this->screens = xrealloc(this->screens, sizeof(ScreenSettings*) * (this->nScreens + 2));
   this->screens[this->nScreens++] = ss;
   this->screens[this->nScreens] = NULL;
   return ss;
}

void ScreenSettings_delete(ScreenSettings* ss) {
   free(ss->heading);
   free(ss->fields);
   free(ss);
}

static ScreenSettings* defaultScreens(Settings* this) {
   if (this->nScreens) return this->screens[0];
   Settings_newScreen(this, "Main", "PID USER PRIORITY NICE M_VIRT M_RESIDENT M_SHARE STATE PERCENT_CPU PERCENT_MEM TIME Command", "PERCENT_CPU");
   Settings_newScreen(this, "I/O", "PID USER IO_PRIORITY IO_RATE IO_READ_RATE IO_WRITE_RATE Command", "IO_RATE");
   return this->screens[0];
}

static char* readLine(FILE* fp) {
   size_t cap = 256, len = 0;
   char* buf = xmalloc(cap);
   int c;
   bool any = false;
   while ((c = fgetc(fp)) != EOF) {
      any = true;
      if (c == '\n') break;
      if (len + 2 > cap) { cap *= 2; buf = xrealloc(buf, cap); }
      buf[len++] = (char)c;
   }
   if (!any) { free(buf); return NULL; }
   buf[len] = 0;
   return buf;
}

static bool readFile(Settings* this, const char* fileName, int cpus, bool checkWritability) {
   FILE* fp = NULL;
   if (checkWritability) {
      int fd;
      do { fd = open(fileName, O_RDWR | O_NOCTTY | O_NOFOLLOW); } while (fd < 0 && errno == EINTR);
      if (fd < 0) {
         this->writeConfig = (errno == ENOENT);
         if (errno != EACCES && errno != EPERM && errno != EROFS) return false;
      } else {
         this->writeConfig = true;
         fp = fdopen(fd, "r+");
      }
   }
   if (!fp) {
      fp = fopen(fileName, "r");
      if (!fp) return false;
   }
   ScreenSettings* screen = NULL;
   bool didReadMeters = false;
   bool didReadAny = false;
   for (;;) {
      char* line = readLine(fp);
      if (!line) break;
      didReadAny = true;
      int nOptions = 0;
      char** option = str_split(line, '=', &nOptions);
      free(line);
      if (nOptions < 2) { str_freeArray(option); continue; }
      const char* k = option[0];
      const char* v = option[1];
      if (str_eq(k, "config_reader_min_version")) {
         this->config_version = atoi(v);
         if (this->config_version > CONFIG_READER_MIN_VERSION) {
            fprintf(stderr, "WARNING: %s specifies configuration format\n", fileName);
            fprintf(stderr, "         version v%d, but this %s binary only supports up to version v%d.\n", this->config_version, "htop", CONFIG_READER_MIN_VERSION);
            fprintf(stderr, "         The configuration file will be downgraded to v%d when %s exits.\n", CONFIG_READER_MIN_VERSION, "htop");
            str_freeArray(option);
            fclose(fp);
            return false;
         }
      } else if (str_eq(k, "fields") && this->config_version <= 2) {
         screen = defaultScreens(this);
         readFields(screen, v);
      } else if (str_eq(k, "sort_key") && this->config_version <= 2) {
         screen = defaultScreens(this);
         screen->sortKey = atoi(v) + 1;
      } else if (str_eq(k, "tree_sort_key") && this->config_version <= 2) {
         screen = defaultScreens(this);
         screen->treeSortKey = atoi(v) + 1;
      } else if (str_eq(k, "sort_direction") && this->config_version <= 2) {
         screen = defaultScreens(this);
         screen->direction = atoi(v);
      } else if (str_eq(k, "tree_sort_direction") && this->config_version <= 2) {
         screen = defaultScreens(this);
         screen->treeDirection = atoi(v);
      } else if (str_eq(k, "tree_view") && this->config_version <= 2) {
         screen = defaultScreens(this);
         screen->treeView = atoi(v);
      } else if (str_eq(k, "tree_view_always_by_pid") && this->config_version <= 2) {
         screen = defaultScreens(this);
         screen->treeViewAlwaysByPID = atoi(v);
      } else if (str_eq(k, "all_branches_collapsed") && this->config_version <= 2) {
         screen = defaultScreens(this);
         screen->allBranchesCollapsed = atoi(v);
      } else if (str_eq(k, "hide_kernel_threads")) {
         this->hideKernelThreads = atoi(v);
      } else if (str_eq(k, "hide_userland_threads")) {
         this->hideUserlandThreads = atoi(v);
      } else if (str_eq(k, "hide_running_in_container")) {
         this->hideRunningInContainer = atoi(v);
      } else if (str_eq(k, "shadow_other_users")) {
         this->shadowOtherUsers = atoi(v);
      } else if (str_eq(k, "show_thread_names")) {
         this->showThreadNames = atoi(v);
      } else if (str_eq(k, "show_program_path")) {
         this->showProgramPath = atoi(v);
      } else if (str_eq(k, "highlight_base_name")) {
         this->highlightBaseName = atoi(v);
      } else if (str_eq(k, "highlight_deleted_exe")) {
         this->highlightDeletedExe = atoi(v);
      } else if (str_eq(k, "shadow_distribution_path_prefix")) {
         this->shadowDistPathPrefix = atoi(v);
      } else if (str_eq(k, "highlight_megabytes")) {
         this->highlightMegabytes = atoi(v);
      } else if (str_eq(k, "highlight_threads")) {
         this->highlightThreads = atoi(v);
      } else if (str_eq(k, "highlight_changes")) {
         this->highlightChanges = atoi(v);
      } else if (str_eq(k, "highlight_changes_delay_secs")) {
         this->highlightDelaySecs = CLAMPI(atoi(v), 1, 24 * 60 * 60);
      } else if (str_eq(k, "find_comm_in_cmdline")) {
         this->findCommInCmdline = atoi(v);
      } else if (str_eq(k, "strip_exe_from_cmdline")) {
         this->stripExeFromCmdline = atoi(v);
      } else if (str_eq(k, "show_merged_command")) {
         this->showMergedCommand = atoi(v);
      } else if (str_eq(k, "header_margin")) {
         this->headerMargin = atoi(v);
      } else if (str_eq(k, "screen_tabs")) {
         this->screenTabs = atoi(v);
      } else if (str_eq(k, "expand_system_time")) {
         this->detailedCPUTime = atoi(v);
      } else if (str_eq(k, "detailed_cpu_time")) {
         this->detailedCPUTime = atoi(v);
      } else if (str_eq(k, "cpu_count_from_one")) {
         this->countCPUsFromOne = atoi(v);
      } else if (str_eq(k, "cpu_count_from_zero")) {
         this->countCPUsFromOne = !atoi(v);
      } else if (str_eq(k, "show_cpu_usage")) {
         this->showCPUUsage = atoi(v);
      } else if (str_eq(k, "show_cpu_frequency")) {
         this->showCPUFrequency = atoi(v);
      } else if (str_eq(k, "show_cached_memory")) {
         this->showCachedMemory = atoi(v);
      } else if (str_eq(k, "update_process_names")) {
         this->updateProcessNames = atoi(v);
      } else if (str_eq(k, "account_guest_in_cpu_meter")) {
         this->accountGuestInCPUMeter = atoi(v);
      } else if (str_eq(k, "delay")) {
         this->delay = CLAMPI(atoi(v), 1, 255);
      } else if (str_eq(k, "color_scheme")) {
         this->colorScheme = atoi(v);
         if (this->colorScheme < 0 || this->colorScheme >= 8) this->colorScheme = 0;
      } else if (str_eq(k, "enable_mouse")) {
         this->enableMouse = atoi(v);
      } else if (str_eq(k, "header_layout")) {
         int hl = isdigit((unsigned char)v[0]) ? atoi(v) : HeaderLayout_fromName(v);
         if (hl < 0 || hl >= LAST_HEADER_LAYOUT) hl = HF_TWO_50_50;
         freeColumns(this->hColumns, HeaderLayouts[this->hLayout].columns);
         this->hLayout = hl;
         this->hColumns = xcalloc(HeaderLayouts[hl].columns, sizeof(MeterColumnSetting));
      } else if (str_eq(k, "left_meters")) {
         readMeters(this, v, 0); didReadMeters = true;
      } else if (str_eq(k, "right_meters")) {
         readMeters(this, v, 1); didReadMeters = true;
      } else if (str_eq(k, "left_meter_modes")) {
         readMeterModes(this, v, 0); didReadMeters = true;
      } else if (str_eq(k, "right_meter_modes")) {
         readMeterModes(this, v, 1); didReadMeters = true;
      } else if (str_starts(k, "column_meters_")) {
         readMeters(this, v, atoi(k + strlen("column_meters_"))); didReadMeters = true;
      } else if (str_starts(k, "column_meter_modes_")) {
         readMeterModes(this, v, atoi(k + strlen("column_meter_modes_"))); didReadMeters = true;
      } else if (str_eq(k, "hide_function_bar")) {
         this->hideFunctionBar = atoi(v);
      } else if (strncmp(k, "screen:", 7) == 0) {
         screen = Settings_newScreen(this, k + 7, v, NULL);
      } else if (str_eq(k, ".sort_key")) {
         if (screen) { int key = Field_byName(v); screen->sortKey = key > 0 ? key : PID; }
      } else if (str_eq(k, ".tree_sort_key")) {
         if (screen) { int key = Field_byName(v); screen->treeSortKey = key > 0 ? key : PID; }
      } else if (str_eq(k, ".sort_direction")) {
         if (screen) screen->direction = atoi(v);
      } else if (str_eq(k, ".tree_sort_direction")) {
         if (screen) screen->treeDirection = atoi(v);
      } else if (str_eq(k, ".tree_view")) {
         if (screen) screen->treeView = atoi(v);
      } else if (str_eq(k, ".tree_view_always_by_pid")) {
         if (screen) screen->treeViewAlwaysByPID = atoi(v);
      } else if (str_eq(k, ".all_branches_collapsed")) {
         if (screen) screen->allBranchesCollapsed = atoi(v);
      }
      str_freeArray(option);
   }
   fclose(fp);
   if (!didReadMeters || !validateMeters(this)) Settings_setDefaultMeters(this, cpus);
   if (!this->nScreens) defaultScreens(this);
   return didReadAny;
}

Settings* Settings_new(int cpus) {
   Settings* this = xcalloc(1, sizeof(Settings));
   this->writeConfig = true;
   this->hLayout = HF_TWO_50_50;
   this->hColumns = xcalloc(HeaderLayouts[this->hLayout].columns, sizeof(MeterColumnSetting));
   this->shadowOtherUsers = false;
   this->showThreadNames = false;
   this->hideKernelThreads = true;
   this->hideUserlandThreads = false;
   this->hideRunningInContainer = false;
   this->highlightBaseName = false;
   this->highlightDeletedExe = true;
   this->shadowDistPathPrefix = false;
   this->highlightMegabytes = true;
   this->detailedCPUTime = false;
   this->countCPUsFromOne = false;
   this->showCPUUsage = true;
   this->showCPUFrequency = false;
   this->updateProcessNames = false;
   this->showProgramPath = true;
   this->highlightThreads = true;
   this->highlightChanges = false;
   this->highlightDelaySecs = 5;
   this->findCommInCmdline = true;
   this->stripExeFromCmdline = true;
   this->showMergedCommand = false;
   this->hideFunctionBar = 0;
   this->headerMargin = true;
   this->screenTabs = false;
   this->showCachedMemory = true;
   this->enableMouse = true;
   this->changed = false;
   this->delay = 15;
   this->colorScheme = 0;

   char* legacyDotfile = NULL;
   const char* rcfile = getenv("HTOPRC");
   if (rcfile) {
      this->filename = xstrdup(rcfile);
   } else {
      const char* home = getenv("HOME");
      if (!home) home = "";
      const char* xdg = getenv("XDG_CONFIG_HOME");
      char* configDir; char* htopDir;
      if (xdg) {
         this->filename = str_cat(xdg, "/htop/htoprc");
         configDir = xstrdup(xdg);
         htopDir = str_cat(xdg, "/htop");
      } else {
         this->filename = str_cat(home, "/.config/htop/htoprc");
         configDir = str_cat(home, "/.config");
         htopDir = str_cat(home, "/.config/htop");
      }
      legacyDotfile = str_cat(home, "/.htoprc");
      (void)mkdir(configDir, 0700);
      (void)mkdir(htopDir, 0700);
      free(htopDir); free(configDir);
      struct stat st;
      int err = lstat(legacyDotfile, &st);
      if (err || S_ISLNK(st.st_mode)) { free(legacyDotfile); legacyDotfile = NULL; }
   }
   bool ok = readFile(this, this->filename, cpus, true);
   if (!ok && legacyDotfile) {
      ok = readFile(this, legacyDotfile, cpus, this->writeConfig);
      if (ok && this->writeConfig) {
         if (Settings_write(this, false) == 0) unlink(legacyDotfile);
      }
   }
   if (!ok) {
      this->screenTabs = true;
      this->changed = true;
      ok = readFile(this, "/etc/htoprc", cpus, false);
   }
   if (!ok) {
      Settings_setDefaultMeters(this, cpus);
      defaultScreens(this);
   }
   free(legacyDotfile);
   this->ssIndex = 0;
   this->ss = this->screens[0];
   this->lastUpdate = 1;
   return this;
}

static void writeFields(FILE* fd, const int* fields, bool byName, char separator) {
   const char* sep = "";
   for (int i = 0; fields[i]; i++) {
      if (byName) fprintf(fd, "%s%s", sep, Fields[fields[i]].name);
      else fprintf(fd, "%s%d", sep, fields[i] - 1);
      sep = " ";
   }
   fputc(separator, fd);
}

int Settings_write(const Settings* this, bool onCrash) {
   FILE* fd;
   char separator;
   char* tmpFilename = NULL;
   if (onCrash) {
      fd = stderr;
      separator = ';';
   } else {
      if (!this->writeConfig) return 0;
      mode_t cur_umask = umask(S_IXUSR | S_IRWXG | S_IRWXO);
      tmpFilename = xasprintf("%s.tmp.XXXXXX", this->filename);
      int fdtmp = mkstemp(tmpFilename);
      umask(cur_umask);
      if (fdtmp == -1) { int e = errno; free(tmpFilename); return -e; }
      fd = fdopen(fdtmp, "w");
      if (!fd) { int e = errno; close(fdtmp); unlink(tmpFilename); free(tmpFilename); return -e; }
      separator = '\n';
   }
#define PI(s_, v_) fprintf(fd, s_ "=%d%c", (int)(v_), separator)
#define PS(s_, v_) fprintf(fd, s_ "=%s%c", (v_), separator)
   if (!onCrash) {
      fprintf(fd, "# Beware! This file is rewritten by htop when settings are changed in the interface.\n");
      fprintf(fd, "# The parser is also very primitive, and not human-friendly.\n");
   }
   PS("htop_version", VERSION_STR);
   PI("config_reader_min_version", CONFIG_READER_MIN_VERSION);
   fprintf(fd, "fields=");
   writeFields(fd, this->screens[0]->fields, false, separator);
   PI("hide_kernel_threads", this->hideKernelThreads);
   PI("hide_userland_threads", this->hideUserlandThreads);
   PI("hide_running_in_container", this->hideRunningInContainer);
   PI("shadow_other_users", this->shadowOtherUsers);
   PI("show_thread_names", this->showThreadNames);
   PI("show_program_path", this->showProgramPath);
   PI("highlight_base_name", this->highlightBaseName);
   PI("highlight_deleted_exe", this->highlightDeletedExe);
   PI("shadow_distribution_path_prefix", this->shadowDistPathPrefix);
   PI("highlight_megabytes", this->highlightMegabytes);
   PI("highlight_threads", this->highlightThreads);
   PI("highlight_changes", this->highlightChanges);
   PI("highlight_changes_delay_secs", this->highlightDelaySecs);
   PI("find_comm_in_cmdline", this->findCommInCmdline);
   PI("strip_exe_from_cmdline", this->stripExeFromCmdline);
   PI("show_merged_command", this->showMergedCommand);
   PI("header_margin", this->headerMargin);
   PI("screen_tabs", this->screenTabs);
   PI("detailed_cpu_time", this->detailedCPUTime);
