#include "machine.h"
#include <dirent.h>
#include <fcntl.h>
#include <math.h>
#include <pwd.h>
#include <unistd.h>
#include <time.h>
#include <limits.h>
#include <sys/stat.h>
#include <sys/sysmacros.h>
#include <sys/syscall.h>
#include <sched.h>
#include <sys/resource.h>
#include <errno.h>

int Row_pidDigits = 5;
int Row_uidDigits = 5;
int Row_fieldWidths[LAST_PROCESSFIELD];

typedef struct { char* path; unsigned int major, minorFrom, minorTo; } TtyDriver;

static void initTtyDrivers(Machine* this) {
   char* buf = readFileStr("/proc/tty/drivers", 0);
   if (!buf) return;
   int cap = 16, n = 0;
   TtyDriver* d = xcalloc(cap + 1, sizeof(TtyDriver));
   char* save = NULL;
   for (char* line = strtok_r(buf, "\n", &save); line; line = strtok_r(NULL, "\n", &save)) {
      char name[256], path[256], range[64];
      unsigned int maj;
      if (sscanf(line, "%255s %255s %u %63s", name, path, &maj, range) != 4) continue;
      unsigned int a, b;
      if (strchr(range, '-')) { if (sscanf(range, "%u-%u", &a, &b) != 2) continue; }
      else { if (sscanf(range, "%u", &a) != 1) continue; b = a; }
      if (n >= cap) { cap *= 2; d = xrealloc(d, sizeof(TtyDriver) * (cap + 1)); }
      d[n].path = xstrdup(path); d[n].major = maj; d[n].minorFrom = a; d[n].minorTo = b;
      n++;
   }
   free(buf);
   /* sort by major then minorFrom */
   for (int i = 1; i < n; i++) {
      TtyDriver t = d[i]; int j = i - 1;
      while (j >= 0 && (d[j].major > t.major || (d[j].major == t.major && d[j].minorFrom > t.minorFrom))) { d[j+1] = d[j]; j--; }
      d[j+1] = t;
   }
   d[n].path = NULL;
   this->ttyDrivers = d;
   this->nTtyDrivers = n;
}

static char* ttyName(Machine* this, unsigned long tty_nr) {
   unsigned int maj = major(tty_nr), min = minor(tty_nr);
   TtyDriver* drv = this->ttyDrivers;
   if (drv) {
      for (int i = 0; drv[i].path; i++) {
         if (maj < drv[i].major) break;
         if (maj > drv[i].major) continue;
         if (min < drv[i].minorFrom) break;
         if (min > drv[i].minorTo) continue;
         unsigned int idx = min - drv[i].minorFrom;
         struct stat st;
         char* full;
         for (;;) {
            full = xasprintf("%s/%u", drv[i].path, idx);
            if (stat(full, &st) == 0 && major(st.st_rdev) == maj && minor(st.st_rdev) == min) return full;
            free(full);
            full = xasprintf("%s%u", drv[i].path, idx);
            if (stat(full, &st) == 0 && major(st.st_rdev) == maj && minor(st.st_rdev) == min) return full;
            free(full);
            if (idx == min) break;
            idx = min;
         }
         if (stat(drv[i].path, &st) == 0 && tty_nr == st.st_rdev) return xstrdup(drv[i].path);
      }
   }
   return xasprintf("/dev/%u:%u", maj, min);
}

static void updateCPUcount(Machine* this) {
   if (!this->cpuData) {
      this->cpuData = xcalloc(2, sizeof(CPUData));
      this->cpuData[0].online = true;
      this->cpuData[1].online = true;
      this->activeCPUs = 1;
      this->existingCPUs = 1;
   }
   DIR* dir = opendir("/sys/devices/system/cpu");
   if (!dir) return;
   unsigned int existing = 0, active = 0;
   unsigned int currExisting = this->existingCPUs;
   struct dirent* e;
   while ((e = readdir(dir))) {
      if (!str_starts(e->d_name, "cpu")) continue;
      char* endp;
      unsigned long id = strtoul(e->d_name + 3, &endp, 10);
      if (id == ULONG_MAX || endp == e->d_name + 3 || *endp != '\0') continue;
      existing++;
      unsigned int max = MAXI(existing, id + 1);
      if (max > currExisting) {
         this->cpuData = xrealloc(this->cpuData, sizeof(CPUData) * (max + 1));
         memset(this->cpuData + currExisting + 1, 0, sizeof(CPUData) * (max - currExisting));
         this->cpuData[0].online = true;
         currExisting = max;
      }
      char path[128], buf[8];
      snprintf(path, sizeof(path), "/sys/devices/system/cpu/%s/online", e->d_name);
      ssize_t r = readFileBuf(path, buf, sizeof(buf));
      if (r < 1 || buf[0] != '0') { active++; this->cpuData[id + 1].online = true; }
      else this->cpuData[id + 1].online = false;
   }
   closedir(dir);
   if (existing < 1) return;
   this->existingCPUs = currExisting;
   this->activeCPUs = active;
}

static inline unsigned long long satSub(unsigned long long a, unsigned long long b) { return a > b ? a - b : 0; }

static void scanCPUTime(Machine* this) {
   updateCPUcount(this);
   FILE* f = fopen("/proc/stat", "r");
   if (!f) return;
   bool* processed = xcalloc(this->existingCPUs + 2, sizeof(bool));
   char buffer[1024];
   for (unsigned int i = 0; i <= this->existingCPUs; i++) {
      unsigned long long usertime = 0, nicetime = 0, systemtime = 0, idletime = 0;
      unsigned long long ioWait = 0, irq = 0, softIrq = 0, steal = 0, guest = 0, guestnice = 0;
      if (!fgets(buffer, sizeof(buffer), f)) break;
      if (!str_starts(buffer, "cpu")) break;
      unsigned int adj;
      if (buffer[3] == ' ') {
         (void)sscanf(buffer, "cpu  %16llu %16llu %16llu %16llu %16llu %16llu %16llu %16llu %16llu %16llu", &usertime, &nicetime, &systemtime, &idletime, &ioWait, &irq, &softIrq, &steal, &guest, &guestnice);
         adj = 0;
      } else {
         unsigned int cpuid = 0;
         (void)sscanf(buffer, "cpu%4u %16llu %16llu %16llu %16llu %16llu %16llu %16llu %16llu %16llu %16llu", &cpuid, &usertime, &nicetime, &systemtime, &idletime, &ioWait, &irq, &softIrq, &steal, &guest, &guestnice);
         adj = cpuid + 1;
      }
      if (adj > this->existingCPUs) break;
      usertime -= guest;
      nicetime -= guestnice;
      unsigned long long idlealltime = idletime + ioWait;
      unsigned long long systemalltime = systemtime + irq + softIrq;
      unsigned long long virtalltime = guest + guestnice;
      unsigned long long totaltime = usertime + nicetime + systemalltime + idlealltime + steal + virtalltime;
      CPUData* c = &this->cpuData[adj];
      c->userPeriod = satSub(usertime, c->userTime);
      c->nicePeriod = satSub(nicetime, c->niceTime);
      c->systemPeriod = satSub(systemtime, c->systemTime);
      c->systemAllPeriod = satSub(systemalltime, c->systemAllTime);
      c->idleAllPeriod = satSub(idlealltime, c->idleAllTime);
      c->idlePeriod = satSub(idletime, c->idleTime);
      c->ioWaitPeriod = satSub(ioWait, c->ioWaitTime);
      c->irqPeriod = satSub(irq, c->irqTime);
      c->softIrqPeriod = satSub(softIrq, c->softIrqTime);
      c->stealPeriod = satSub(steal, c->stealTime);
      c->guestPeriod = satSub(virtalltime, c->guestTime);
      c->totalPeriod = satSub(totaltime, c->totalTime);
      c->userTime = usertime; c->niceTime = nicetime; c->systemTime = systemtime;
      c->systemAllTime = systemalltime; c->idleAllTime = idlealltime; c->idleTime = idletime;
      c->ioWaitTime = ioWait; c->irqTime = irq; c->softIrqTime = softIrq; c->stealTime = steal;
      c->guestTime = virtalltime; c->totalTime = totaltime;
      processed[adj] = true;
   }
   processed[this->existingCPUs + 1] = true;
   unsigned int last = 0;
   for (unsigned int i = 0; i <= this->existingCPUs + 1; i++) {
      if (processed[i]) {
         for (unsigned int j = last + 1; j < i; j++) {
            bool online = this->cpuData[j].online;
            memset(&this->cpuData[j], 0, sizeof(CPUData));
            (void)online;
         }
         last = i;
      }
   }
   free(processed);
   this->period = (double)this->cpuData[0].totalPeriod / (this->activeCPUs ? this->activeCPUs : 1);
   while (fgets(buffer, sizeof(buffer), f)) {
      if (str_starts(buffer, "procs_running")) {
         this->runningTasks = strtoul(buffer + strlen("procs_running"), NULL, 10);
         break;
      }
   }
   fclose(f);
}

static void scanMemory(Machine* this) {
   unsigned long long availableMem = 0, freeMem = 0, totalMem = 0, buffersMem = 0, cachedMem = 0, sharedMem = 0;
   unsigned long long swapTotalMem = 0, swapCacheMem = 0, swapFreeMem = 0, sreclaimableMem = 0;
   unsigned long long zswapComp = 0, zswapOrig = 0;
   unsigned long long hpTotal = 0, hpFree = 0;
   FILE* f = fopen("/proc/meminfo", "r");
   if (!f) return;
   char buffer[256];
   while (fgets(buffer, sizeof(buffer), f)) {
#define TRY(label, var) if (str_starts(buffer, label)) { unsigned long long v_; if (sscanf(buffer + strlen(label), "%llu kB", &v_) == 1) var = v_; continue; }
      TRY("MemAvailable:", availableMem);
      TRY("MemFree:", freeMem);
      TRY("MemTotal:", totalMem);
      TRY("Buffers:", buffersMem);
      TRY("Cached:", cachedMem);
      TRY("Shmem:", sharedMem);
      TRY("SwapTotal:", swapTotalMem);
      TRY("SwapCached:", swapCacheMem);
      TRY("SwapFree:", swapFreeMem);
      TRY("SReclaimable:", sreclaimableMem);
      TRY("Zswap:", zswapComp);
      TRY("Zswapped:", zswapOrig);
#undef TRY
      if (str_starts(buffer, "HugePages_Total:")) { sscanf(buffer + 16, "%llu", &hpTotal); continue; }
      if (str_starts(buffer, "HugePages_Free:")) { sscanf(buffer + 15, "%llu", &hpFree); continue; }
   }
   fclose(f);
   this->totalMem = totalMem;
   this->cachedMem = cachedMem + sreclaimableMem - sharedMem;
   this->sharedMem = sharedMem;
   unsigned long long usedDiff = freeMem + cachedMem + sreclaimableMem + buffersMem;
   this->usedMem = (totalMem >= usedDiff) ? totalMem - usedDiff : totalMem - freeMem;
   this->buffersMem = buffersMem;
   this->availableMem = availableMem != 0 ? MINI(availableMem, totalMem) : freeMem;
   this->totalSwap = swapTotalMem;
   this->usedSwap = swapTotalMem - swapFreeMem - swapCacheMem;
   this->cachedSwap = swapCacheMem;
   this->zswapComp = zswapComp;
   this->zswapOrig = zswapOrig;
   (void)hpTotal; (void)hpFree;
}

static void scanHugePages(Machine* this) {
   this->hugePageTotal = 0;
   this->hugePageFree = 0;
   memset(this->hugePageSizes, 0, sizeof(this->hugePageSizes));
   DIR* dir = opendir("/sys/kernel/mm/hugepages");
   if (!dir) return;
   struct dirent* e;
   while ((e = readdir(dir))) {
      if (!str_starts(e->d_name, "hugepages-")) continue;
      char* end;
      unsigned long long sizeKB = strtoull(e->d_name + 10, &end, 10);
      if (end == e->d_name + 10 || !str_eq(end, "kB")) continue;
      char path[256], buf[32];
      snprintf(path, sizeof(path), "/sys/kernel/mm/hugepages/%s/nr_hugepages", e->d_name);
      if (readFileBuf(path, buf, sizeof(buf)) <= 0) continue;
      unsigned long long total = strtoull(buf, NULL, 10);
      snprintf(path, sizeof(path), "/sys/kernel/mm/hugepages/%s/free_hugepages", e->d_name);
      if (readFileBuf(path, buf, sizeof(buf)) <= 0) continue;
      unsigned long long fr = strtoull(buf, NULL, 10);
      int shift = __builtin_ctzll(sizeKB) - 6;
      if (shift >= 0 && shift < 4) {
         this->hugePageSizes[shift] = (total - fr) * sizeKB;
      }
      this->hugePageTotal += total * sizeKB;
      this->hugePageFree += fr * sizeKB;
   }
   closedir(dir);
}

static void scanLoad(Machine* this) {
   char buf[256];
   if (readFileBuf("/proc/loadavg", buf, sizeof(buf)) <= 0) {
      this->load[0] = this->load[1] = this->load[2] = NAN;
      return;
   }
   if (sscanf(buf, "%lf %lf %lf", &this->load[0], &this->load[1], &this->load[2]) != 3)
      this->load[0] = this->load[1] = this->load[2] = NAN;
}

static void scanFrequencies(Machine* this) {
   for (unsigned int i = 0; i <= this->existingCPUs; i++) this->cpuData[i].frequency = NAN;
   FILE* f = fopen("/proc/cpuinfo", "r");
   if (!f) return;
   char buf[512];
   int cpuid = -1;
   double total = 0; int n = 0;
   while (fgets(buf, sizeof(buf), f)) {
      int id; double mhz;
      if (sscanf(buf, "processor : %d", &id) == 1) { cpuid = id; continue; }
      if (sscanf(buf, "cpu MHz : %lf", &mhz) == 1 || sscanf(buf, "clock : %lfMHz", &mhz) == 1) {
         if (cpuid >= 0 && (unsigned)cpuid < this->existingCPUs) {
            CPUData* c = &this->cpuData[cpuid + 1];
            if (isnan(c->frequency)) c->frequency = 0;
            c->frequency += mhz;
            total += mhz; n++;
         }
      }
   }
   fclose(f);
   if (n > 0) this->cpuData[0].frequency = total / n;
}

Machine* Machine_new(uid_t userId) {
   Machine* this = xcalloc(1, sizeof(Machine));
   this->userId = userId;
   this->htopUserId = getuid();
   this->iterationsRemaining = -1;
   this->pageSize = sysconf(_SC_PAGESIZE);
   if (this->pageSize <= 0) this->pageSize = 4096;
   this->pageSizeKB = this->pageSize / 1024;
   this->jiffies = sysconf(_SC_CLK_TCK);
   if (this->jiffies <= 0) this->jiffies = 100;
   this->rows = vec_new();
   this->displayList = vec_new();
   this->following = -1;
   this->needsSort = true;
   /* boot time */
   FILE* f = fopen("/proc/stat", "r");
   if (f) {
      char buf[1024];
      while (fgets(buf, sizeof(buf), f)) {
         if (str_starts(buf, "btime ")) { this->bootTime = strtod(buf + 6, NULL); break; }
      }
      fclose(f);
   }
   struct stat st;
   this->haveAutogroup = stat("/proc/self/autogroup", &st) == 0;
   initTtyDrivers(this);
   updateCPUcount(this);
   scanCPUTime(this);
   return this;
}

void Machine_setSettings(Machine* this, Settings* s) { this->settings = s; }

const char* Machine_lookupUser(Machine* this, uid_t uid) {
   for (UserEntry* e = this->users; e; e = e->next) if (e->uid == uid) return e->name;
   struct passwd* pw = getpwuid(uid);
   UserEntry* e = xcalloc(1, sizeof(UserEntry));
   e->uid = uid;
   e->name = pw ? xstrdup(pw->pw_name) : NULL;
   e->next = this->users;
   this->users = e;
   return e->name;
}

void Machine_forEachUser(Machine* this, void (*fn)(uid_t, const char*, void*), void* data) {
   for (UserEntry* e = this->users; e; e = e->next) if (e->name) fn(e->uid, e->name, data);
}

void Machine_scan(Machine* this) {
   realtimeNow(&this->realtime, &this->realtimeMs);
   if (this->firstScanDone) {
      this->prevMonotonicMs = this->monotonicMs;
      this->monotonicMs = monotonicMs();
   } else {
      this->prevMonotonicMs = 0;
      this->monotonicMs = monotonicMs();
   }
   scanMemory(this);
   scanHugePages(this);
   scanCPUTime(this);
   scanLoad(this);
   if (this->settings && this->settings->showCPUFrequency) scanFrequencies(this);
}

/* ------------------------------------------------------------------ */
/* process scanning                                                    */

Process* Machine_findProcess(Machine* this, int pid) {
   /* rows is kept sorted only sometimes; linear scan with a small hash */
   for (int i = 0; i < this->rows->size; i++) {
      Process* p = this->rows->items[i];
      if (p->pid == pid) return p;
   }
   return NULL;
}

typedef struct { int pid; Process* p; } HEnt;
typedef struct { HEnt* e; int cap; } PHash;
static PHash g_hash;
static void phash_rebuild(Machine* this) {
   int need = 16;
   while (need < this->rows->size * 2 + 16) need *= 2;
   if (g_hash.cap < need) { free(g_hash.e); g_hash.e = xcalloc(need, sizeof(HEnt)); g_hash.cap = need; }
   else memset(g_hash.e, 0, sizeof(HEnt) * g_hash.cap);
   for (int i = 0; i < this->rows->size; i++) {
      Process* p = this->rows->items[i];
      unsigned h = (unsigned)p->pid * 2654435761u;
      int idx = h & (g_hash.cap - 1);
      while (g_hash.e[idx].p) idx = (idx + 1) & (g_hash.cap - 1);
      g_hash.e[idx].pid = p->pid; g_hash.e[idx].p = p;
   }
}
static Process* phash_get(int pid) {
   if (!g_hash.cap) return NULL;
   unsigned h = (unsigned)pid * 2654435761u;
   int idx = h & (g_hash.cap - 1);
   while (g_hash.e[idx].p) {
      if (g_hash.e[idx].pid == pid) return g_hash.e[idx].p;
      idx = (idx + 1) & (g_hash.cap - 1);
   }
   return NULL;
}
static void phash_put(Process* p) {
   int count = 0;
   for (int i = 0; i < g_hash.cap; i++) if (g_hash.e[i].p) count++;
   if (!g_hash.cap || count * 2 + 2 > g_hash.cap) {
      int nc = g_hash.cap ? g_hash.cap * 2 : 64;
      HEnt* old = g_hash.e; int oc = g_hash.cap;
      g_hash.e = xcalloc(nc, sizeof(HEnt)); g_hash.cap = nc;
      for (int i = 0; i < oc; i++) if (old[i].p) {
         unsigned h = (unsigned)old[i].pid * 2654435761u;
         int idx = h & (nc - 1);
         while (g_hash.e[idx].p) idx = (idx + 1) & (nc - 1);
         g_hash.e[idx] = old[i];
      }
      free(old);
   }
   unsigned h = (unsigned)p->pid * 2654435761u;
   int idx = h & (g_hash.cap - 1);
   while (g_hash.e[idx].p) idx = (idx + 1) & (g_hash.cap - 1);
   g_hash.e[idx].pid = p->pid; g_hash.e[idx].p = p;
}

static Process* Process_new(Machine* host) {
   Process* p = xcalloc(1, sizeof(Process));
   p->super.cls = &Process_class;
   p->host = host;
   p->show = true;
   p->showChildren = true;
   p->isRunningInContainer = -1;
   p->ioPriority = -1;
   p->autogroup_id = -1;
   p->scheduling_policy = -1;
   p->io_rate_read_bps = NAN;
   p->io_rate_write_bps = NAN;
   p->io_rchar = p->io_wchar = p->io_syscr = p->io_syscw = ULLONG_MAX;
   p->io_read_bytes = p->io_write_bytes = p->io_cancelled_write_bytes = ULLONG_MAX;
   p->m_lrs = 0;
   p->gpu_percent = NAN;
   return p;
}

static void Process_free(Process* p) {
   free(p->tty_name); free(p->cgroup); free(p->cgroup_short); free(p->container_short);
   free(p->secattr); free(p->cmdline); free(p->procComm); free(p->procExe); free(p->procCwd);
   free(p->mcStr);
   free(p);
}

static ProcessState stateFromChar(char c) {
   switch (c) {
   case 'S': return SLEEPING;
   case 'X': return DEFUNCT;
   case 'Z': return ZOMBIE;
   case 't': return TRACED;
   case 'T': return STOPPED;
   case 'D': return UNINTERRUPTIBLE_WAIT;
   case 'R': return RUNNING;
   case 'P': return BLOCKED;
   case 'I': return IDLE;
   default: return UNKNOWN;
   }
}

static unsigned long long adjTime(Machine* host, unsigned long long t) {
   return t * 100 / host->jiffies;
}

static bool readStat(Process* p, const char* dir, char* command, size_t commLen) {
   char path[256], buf[4096];
   snprintf(path, sizeof(path), "%s/stat", dir);
   ssize_t r = readFileBuf(path, buf, sizeof(buf));
   if (r <= 0) return false;
   char* loc = strchr(buf, ' ');
   if (!loc) return false;
   loc += 2;
   char* end = strrchr(loc, ')');
   if (!end) return false;
   size_t clen = end - loc;
   if (clen >= commLen) clen = commLen - 1;
   memcpy(command, loc, clen);
   command[clen] = 0;
   loc = end + 2;
   Machine* host = p->host;
   p->state = stateFromChar(loc[0]);
   loc += 2;
   p->ppid = strtol(loc, &loc, 10); loc++;
   p->pgrp = strtol(loc, &loc, 10); loc++;
   p->session = strtol(loc, &loc, 10); loc++;
   p->tty_nr = strtoul(loc, &loc, 10); loc++;
   p->tpgid = strtol(loc, &loc, 10); loc++;
   p->kflags = strtoul(loc, &loc, 10); loc++;
   p->minflt = strtoull(loc, &loc, 10); loc++;
   p->cminflt = strtoull(loc, &loc, 10); loc++;
   p->majflt = strtoull(loc, &loc, 10); loc++;
   p->cmajflt = strtoull(loc, &loc, 10); loc++;
   p->utime = adjTime(host, strtoull(loc, &loc, 10)); loc++;
   p->stime = adjTime(host, strtoull(loc, &loc, 10)); loc++;
   p->cutime = adjTime(host, strtoull(loc, &loc, 10)); loc++;
   p->cstime = adjTime(host, strtoull(loc, &loc, 10)); loc++;
   p->priority = strtol(loc, &loc, 10); loc++;
   p->nice = strtol(loc, &loc, 10); loc++;
   p->nlwp = strtol(loc, &loc, 10); loc++;
   /* itrealvalue */
   strtol(loc, &loc, 10); loc++;
   unsigned long long starttime = strtoull(loc, &loc, 10); loc++;
   p->starttime_ctime = (time_t)(host->bootTime + adjTime(host, starttime) / 100);
   for (int i = 0; i < 15; i++) { while (*loc && *loc != ' ') loc++; if (*loc) loc++; }
   /* exit_signal */
   strtol(loc, &loc, 10); loc++;
   p->processor = strtol(loc, &loc, 10);
   p->time = p->utime + p->stime;
   return true;
}

static bool readStatm(Process* p, const char* dir) {
   char path[256], buf[256];
   snprintf(path, sizeof(path), "%s/statm", dir);
   if (readFileBuf(path, buf, sizeof(buf)) <= 0) return false;
   long v[7];
   if (sscanf(buf, "%ld %ld %ld %ld %ld %ld %ld", &v[0], &v[1], &v[2], &v[3], &v[4], &v[5], &v[6]) != 7) return false;
   int pk = p->host->pageSizeKB;
   p->m_virt = v[0] * pk;
   p->m_resident = v[1] * pk;
   p->m_share = v[2];
   p->m_trs = v[3];
   p->m_drs = v[5];
   p->m_priv = p->m_resident - p->m_share * pk;
   return true;
}

static void readIo(Process* p, const char* dir) {
   Machine* host = p->host;
   char path[256], buf[1024];
   snprintf(path, sizeof(path), "%s/io", dir);
   ssize_t r = readFileBuf(path, buf, sizeof(buf));
   if (r <= 0) {
      p->io_rate_read_bps = NAN; p->io_rate_write_bps = NAN;
      p->io_rchar = p->io_wchar = p->io_syscr = p->io_syscw = ULLONG_MAX;
      p->io_read_bytes = p->io_write_bytes = p->io_cancelled_write_bytes = ULLONG_MAX;
      p->io_last_scan_time_ms = host->realtimeMs;
      return;
   }
   unsigned long long lastRead = p->io_read_bytes, lastWrite = p->io_write_bytes;
   unsigned long long delta = satSub(host->realtimeMs, p->io_last_scan_time_ms);
   char* save = NULL;
   for (char* line = strtok_r(buf, "\n", &save); line; line = strtok_r(NULL, "\n", &save)) {
      if (str_starts(line, "rchar: ")) p->io_rchar = strtoull(line + 7, NULL, 10);
      else if (str_starts(line, "wchar: ")) p->io_wchar = strtoull(line + 7, NULL, 10);
      else if (str_starts(line, "syscr: ")) p->io_syscr = strtoull(line + 7, NULL, 10);
      else if (str_starts(line, "syscw: ")) p->io_syscw = strtoull(line + 7, NULL, 10);
      else if (str_starts(line, "read_bytes: ")) {
         p->io_read_bytes = strtoull(line + 12, NULL, 10);
         p->io_rate_read_bps = delta ? satSub(p->io_read_bytes, lastRead) * 1000. / delta : NAN;
         if (lastRead == ULLONG_MAX) p->io_rate_read_bps = delta ? 0 : NAN;
      } else if (str_starts(line, "write_bytes: ")) {
         p->io_write_bytes = strtoull(line + 13, NULL, 10);
         p->io_rate_write_bps = delta ? satSub(p->io_write_bytes, lastWrite) * 1000. / delta : NAN;
         if (lastWrite == ULLONG_MAX) p->io_rate_write_bps = delta ? 0 : NAN;
      } else if (str_starts(line, "cancelled_write_bytes: ")) p->io_cancelled_write_bytes = strtoull(line + 23, NULL, 10);
   }
   p->io_last_scan_time_ms = host->realtimeMs;
}

static void readCmdline(Process* p, const char* dir, const char* statCommand) {
   char path[256];
   snprintf(path, sizeof(path), "%s/cmdline", dir);
   int fd = open(path, O_RDONLY);
   char command[4097];
   ssize_t amt = -1;
   if (fd >= 0) {
      amt = 0;
      while (amt < (ssize_t)sizeof(command) - 1) {
         ssize_t r = read(fd, command + amt, sizeof(command) - 1 - amt);
         if (r <= 0) break;
         amt += r;
      }
      close(fd);
   }
   if (amt <= 0) {
      free(p->cmdline);
      p->cmdline = statCommand ? xstrdup(statCommand) : NULL;
      p->cmdlineBasenameStart = 0;
      p->cmdlineBasenameEnd = statCommand ? (int)strlen(statCommand) : 0;
      p->mcLastUpdate = 0;
      return;
   }
   int tokenEnd = 0, tokenStart = 0, lastChar = 0;
   bool argSepNUL = false, argSepSpace = false;
   for (int i = 0; i < amt; i++) {
      if (command[i] == '\0') {
         command[i] = '\n';
      } else {
         if (tokenEnd) argSepNUL = true;
         if ((unsigned char)command[i] <= ' ') argSepSpace = true;
      }
      if (command[i] == '\n') {
         if (tokenEnd == 0) tokenEnd = i;
      } else {
         if (!tokenEnd && command[i] == '/') tokenStart = i + 1;
         lastChar = i;
      }
   }
   command[lastChar + 1] = '\0';
   /* restore separators: we marked NULs as '\n'; real newlines were also '\n'.
      Track NUL positions separately. */
   (void)argSepNUL; (void)argSepSpace;
   if (tokenEnd == 0) tokenEnd = lastChar + 1;
   free(p->cmdline);
   p->cmdline = xstrdup(command);
   p->cmdlineBasenameStart = tokenStart;
   p->cmdlineBasenameEnd = tokenEnd;
   p->mcLastUpdate = 0;
}

static void readComm(Process* p, const char* dir) {
   char path[256], buf[64];
   snprintf(path, sizeof(path), "%s/comm", dir);
   ssize_t r = readFileBuf(path, buf, sizeof(buf));
   if (r > 0) {
      if (buf[r - 1] == '\n') buf[r - 1] = 0;
      if (!p->procComm || strcmp(p->procComm, buf) != 0) {
         free(p->procComm);
         p->procComm = xstrdup(buf);
         p->mcLastUpdate = 0;
      }
   } else if (p->procComm) {
      free(p->procComm); p->procComm = NULL; p->mcLastUpdate = 0;
   }
}

static void readExe(Process* p, const char* dir) {
   char path[256], buf[4097];
   snprintf(path, sizeof(path), "%s/exe", dir);
   ssize_t r = readlink(path, buf, sizeof(buf) - 1);
   if (r > 0) {
      buf[r] = 0;
      if (!p->procExe || strcmp(p->procExe, buf) != 0) {
         free(p->procExe);
         p->procExe = xstrdup(buf);
         p->procExeLen = r;
         p->procExeBasenameOffset = 0;
         for (int i = 0; i < r; i++) if (buf[i] == '/') p->procExeBasenameOffset = i + 1;
         const char* deleted = " (deleted)";
         size_t dl = strlen(deleted);
         p->procExeDeleted = (size_t)r > dl && strcmp(buf + r - dl, deleted) == 0;
         if (p->procExeDeleted) {
            p->procExe[r - dl] = 0;
            p->procExeLen = r - dl;
         }
         p->mcLastUpdate = 0;
      }
   } else if (p->procExe) {
      free(p->procExe); p->procExe = NULL; p->procExeLen = 0; p->procExeBasenameOffset = 0;
      p->procExeDeleted = false; p->mcLastUpdate = 0;
   }
}

static void readCwd(Process* p, const char* dir) {
   char path[256], buf[4097];
   snprintf(path, sizeof(path), "%s/cwd", dir);
   ssize_t r = readlink(path, buf, sizeof(buf) - 1);
   free(p->procCwd);
   if (r > 0) { buf[r] = 0; p->procCwd = xstrdup(buf); }
   else p->procCwd = NULL;
}

static void readMaps(Process* p, const char* dir, bool calcSize, bool checkDeletedLib) {
   p->usesDeletedLib = false;
   char path[256];
   snprintf(path, sizeof(path), "%s/maps", dir);
   FILE* f = fopen(path, "r");
   if (!f) return;
   typedef struct { unsigned long long inode; unsigned long long size; bool exec; } Lib;
   int cap = 64, n = 0;
   Lib* libs = calcSize ? xcalloc(cap, sizeof(Lib)) : NULL;
   char buffer[1024];
   while (fgets(buffer, sizeof(buffer), f)) {
      if (!strchr(buffer, '/')) continue;
      unsigned long long start, end, off, inode;
      char perms[8];
      unsigned int dmaj, dmin;
      int consumed = 0;
      if (sscanf(buffer, "%llx-%llx %7s %llx %x:%x %llu%n", &start, &end, perms, &off, &dmaj, &dmin, &inode, &consumed) < 7) continue;
      if (!dmaj && !dmin) continue;
      if (!inode) continue;
      bool ex = perms[2] == 'x';
      if (calcSize) {
         int k;
         for (k = 0; k < n; k++) if (libs[k].inode == inode) break;
         if (k == n) {
            if (n >= cap) { cap *= 2; libs = xrealloc(libs, cap * sizeof(Lib)); }
            libs[n].inode = inode; libs[n].size = 0; libs[n].exec = false; n++;
         }
         libs[k].size += end - start;
         libs[k].exec |= ex;
      }
      if (checkDeletedLib && ex && !p->usesDeletedLib) {
         char* rp = buffer + consumed;
         while (*rp == ' ') rp++;
         if (*rp != '/') continue;
         if (str_starts(rp, "/memfd:")) continue;
         if (str_eq(rp, "/dev/zero (deleted)\n")) continue;
         if (strstr(rp, " (deleted)\n")) {
            p->usesDeletedLib = true;
            if (!calcSize) break;
         }
      }
   }
   fclose(f);
   if (calcSize) {
      unsigned long long total = 0;
      for (int k = 0; k < n; k++) if (libs[k].exec) total += libs[k].size;
      free(libs);
      p->m_lrs = total / 1024;
   }
}

static void readSmaps(Process* p, const char* dir) {
   char path[256];
   snprintf(path, sizeof(path), "%s/smaps_rollup", dir);
   FILE* f = fopen(path, "r");
   if (!f) {
      snprintf(path, sizeof(path), "%s/smaps", dir);
      f = fopen(path, "r");
      if (!f) return;
   }
   p->m_pss = 0; p->m_swap = 0; p->m_psswp = 0;
   char buf[256];
   while (fgets(buf, sizeof(buf), f)) {
      long v;
      if (sscanf(buf, "Pss: %ld kB", &v) == 1) p->m_pss += v;
      else if (sscanf(buf, "Swap: %ld kB", &v) == 1) p->m_swap += v;
      else if (sscanf(buf, "SwapPss: %ld kB", &v) == 1) p->m_psswp += v;
   }
   fclose(f);
}

static void readOom(Process* p, const char* dir) {
   char path[256], buf[64];
   snprintf(path, sizeof(path), "%s/oom_score", dir);
   if (readFileBuf(path, buf, sizeof(buf)) > 0) {
      char* end;
      unsigned long v = strtoul(buf, &end, 10);
      if (end != buf) p->oom = v;
   }
}

static void readCtxt(Process* p, const char* dir) {
   char path[256], buf[4096];
   snprintf(path, sizeof(path), "%s/status", dir);
   if (readFileBuf(path, buf, sizeof(buf)) <= 0) { p->ctxtValid = false; return; }
   unsigned long long ctxt = 0;
   char* save = NULL;
   for (char* line = strtok_r(buf, "\n", &save); line; line = strtok_r(NULL, "\n", &save)) {
      if (str_starts(line, "voluntary_ctxt_switches:")) ctxt += strtoull(line + 24, NULL, 10);
      else if (str_starts(line, "nonvoluntary_ctxt_switches:")) ctxt += strtoull(line + 27, NULL, 10);
   }
   p->ctxt_diff = p->ctxtValid ? (ctxt > p->ctxt_total ? ctxt - p->ctxt_total : 0) : 0;
   p->ctxt_total = ctxt;
   p->ctxtValid = true;
}

static void readSecattr(Process* p, const char* dir) {
   char path[256], buf[4096];
   snprintf(path, sizeof(path), "%s/attr/current", dir);
   ssize_t r = readFileBuf(path, buf, sizeof(buf));
   free(p->secattr); p->secattr = NULL;
   if (r <= 0) return;
   char* nl = strchr(buf, '\n');
   if (nl) *nl = 0;
   p->secattr = xstrdup(buf);
}

static void readAutogroup(Process* p, const char* dir) {
   char path[256], buf[256];
   snprintf(path, sizeof(path), "%s/autogroup", dir);
   p->autogroup_id = -1;
   if (readFileBuf(path, buf, sizeof(buf)) <= 0) return;
   long id; int nice;
   if (sscanf(buf, "/autogroup-%ld nice %d", &id, &nice) == 2) {
      p->autogroup_id = id;
      p->autogroup_nice = nice;
   }
}

extern char* CGroup_filterName(const char* cgroup);
extern char* CGroup_filterContainer(const char* cgroup);

static void readCGroup(Process* p, const char* dir) {
   char path[256];
   snprintf(path, sizeof(path), "%s/cgroup", dir);
   char* buf = readFileStr(path, 0);
   free(p->cgroup); p->cgroup = NULL;
   free(p->cgroup_short); p->cgroup_short = NULL;
   free(p->container_short); p->container_short = NULL;
   if (!buf) return;
   /* build output like htop: lines joined by ';' with hierarchy prefix stripped */
   size_t cap = strlen(buf) + 2;
   char* out = xcalloc(cap, 1);
   size_t len = 0;
   char* save = NULL;
   for (char* line = strtok_r(buf, "\n", &save); line; line = strtok_r(NULL, "\n", &save)) {
      char* group = strchr(line, ':');
      if (!group) continue;
      group++;
      char* eol = group;
      (void)eol;
      if (len > 0) out[len++] = ';';
      size_t gl = strlen(group);
      memcpy(out + len, group, gl);
      len += gl;
      out[len] = 0;
   }
   free(buf);
   /* strip leading ':' for v2-only "0::/" lines */
   char* res = out;
   if (res[0] == ':') res++;
   p->cgroup = xstrdup(res);
   free(out);
   p->cgroup_short = CGroup_filterName(p->cgroup);
   p->container_short = CGroup_filterContainer(p->cgroup);
}

static bool updateUser(Process* p, const char* dir) {
   char path[256];
   struct stat st;
   snprintf(path, sizeof(path), "%s", dir);
   if (stat(path, &st) != 0) return false;
   if (p->st_uid != st.st_uid || !p->user) {
      p->st_uid = st.st_uid;
      p->user = Machine_lookupUser(p->host, st.st_uid);
   }
   return true;
}

static void fillStarttime(Process* p) {
   struct tm date;
   time_t now = p->host->realtime.tv_sec;
   localtime_r(&p->starttime_ctime, &date);
   strftime(p->starttime_show, sizeof(p->starttime_show) - 1,
            (p->starttime_ctime > now - 86400) ? "%R " : (p->starttime_ctime > now - 364 * 86400) ? "%b%d " : " %Y ",
            &date);
}

extern int ioprio_get_wrap(int pid);
int Process_getIOPriority(Process* p) {
   long r = syscall(SYS_ioprio_get, 1, p->pid);
   p->ioPriority = (r < 0) ? -1 : (int)r;
   return p->ioPriority;
}
bool Process_setIOPriority(Process* p, int ioprio) {
   if (Settings_readonly) return false;
   syscall(SYS_ioprio_set, 1, p->pid, ioprio);
   return Process_getIOPriority(p) == ioprio;
}

static void readSchedPolicy(Process* p) {
   int pol = sched_getscheduler(p->pid);
   if (pol < 0) { p->scheduling_policy = -1; return; }
   p->reset_on_fork = (pol & SCHED_RESET_ON_FORK) != 0;
   p->scheduling_policy = pol & ~SCHED_RESET_ON_FORK;
}

static void checkContainer(Process* p, const char* dir) {
   /* Heuristic: compare pid namespace with init's */
   (void)dir;
   p->isRunningInContainer = 0;
}

static void scanDir(Machine* this, const char* dirname, Process* parent) {
   Settings* settings = this->settings;
   ScreenSettings* ss = settings->ss;
   DIR* dir = opendir(dirname);
   if (!dir) return;
   bool hideKernelThreads = settings->hideKernelThreads;
   bool hideUserlandThreads = settings->hideUserlandThreads;
   bool hideRunningInContainer = settings->hideRunningInContainer;
   struct dirent* entry;
   while ((entry = readdir(dir))) {
      const char* name = entry->d_name;
      if (entry->d_type != DT_DIR && entry->d_type != DT_UNKNOWN) continue;
      if (name[0] == '.') name++;
      if (name[0] < '0' || name[0] > '9') continue;
      char* endptr;
      unsigned long parsed = strtoul(name, &endptr, 10);
      if (parsed == 0 || parsed == ULONG_MAX || *endptr != '\0') continue;
      int pid = (int)parsed;
      if (parent && pid == parent->pid) continue;

      char procDir[512];
      snprintf(procDir, sizeof(procDir), "%s/%s", dirname, entry->d_name);

      Process* proc = phash_get(pid);
      bool preExisting = proc != NULL;
      if (!proc) proc = Process_new(this);
      proc->pid = pid;
      proc->tgid = parent ? parent->pid : pid;
      proc->isUserlandThread = proc->pid != proc->tgid;

      if (!parent) {
         char taskDir[600];
         snprintf(taskDir, sizeof(taskDir), "%s/task", procDir);
         scanDir(this, taskDir, proc);
      }

      if (preExisting && hideKernelThreads && proc->isKernelThread) {
         proc->updated = true; proc->show = false;
         this->kernelThreads++; this->totalTasks++;
         continue;
      }
      if (preExisting && hideUserlandThreads && proc->isUserlandThread) {
         proc->updated = true; proc->show = false;
         this->userlandThreads++; this->totalTasks++;
         continue;
      }
      if (preExisting && hideRunningInContainer && proc->isRunningInContainer == 1) {
         proc->updated = true; proc->show = false;
         continue;
      }

      if (ss->flags & PF_IO) readIo(proc, procDir);

      if (!readStatm(proc, procDir)) goto errorReading;

      {
         bool prev = proc->usesDeletedLib;
         if (!proc->isKernelThread && !proc->isUserlandThread &&
             ((ss->flags & PF_LRS) || (settings->highlightDeletedExe && !proc->procExeDeleted))) {
            uint64_t passed = this->realtimeMs - proc->last_mlrs_calctime;
            uint64_t recheck = ((uint64_t)rand()) % 2048;
            if (passed > recheck) {
               proc->last_mlrs_calctime = this->realtimeMs;
               readMaps(proc, procDir, ss->flags & PF_LRS, settings->highlightDeletedExe);
            }
         } else {
            proc->usesDeletedLib = (proc->isUserlandThread && parent) ? parent->usesDeletedLib : false;
            proc->m_lrs = (proc->isUserlandThread && parent) ? parent->m_lrs : 0;
         }
         if (prev != proc->usesDeletedLib) proc->mcLastUpdate = 0;
      }

      if ((ss->flags & PF_SMAPS) && !proc->isKernelThread) {
         if (!parent) readSmaps(proc, procDir);
         else { proc->m_pss = parent->m_pss; proc->m_swap = parent->m_swap; proc->m_psswp = parent->m_psswp; }
      }

      char statCommand[256];
      unsigned long long lasttimes = proc->utime + proc->stime;
      unsigned long tty_nr = proc->tty_nr;
      if (!readStat(proc, procDir, statCommand, sizeof(statCommand))) goto errorReading;
      if (proc->kflags & 0x00200000) proc->isKernelThread = true;

      if (!preExisting || tty_nr != proc->tty_nr) {
         free(proc->tty_name);
         proc->tty_name = proc->tty_nr ? ttyName(this, proc->tty_nr) : NULL;
      }

      if (ss->flags & PF_IOPRIO) Process_getIOPriority(proc);

      {
         double period = this->period;
         float pc = (period < 1E-6) ? 0.0F : (float)(satSub(proc->utime + proc->stime, lasttimes) / period * 100.0);
         if (!preExisting) pc = (period < 1E-6) ? 0.0F : (float)((proc->utime + proc->stime - lasttimes) / period * 100.0);
         if (!preExisting) pc = 0.0F;
         if (isnan(pc)) pc = 0.0F;
         proc->percent_cpu = MINI(pc, this->activeCPUs * 100.0F);
         if (proc->percent_cpu < 0) proc->percent_cpu = 0;
         proc->percent_mem = this->totalMem ? proc->m_resident / (double)this->totalMem * 100.0 : 0;
         /* update CPU field widths */
         float perc = proc->percent_cpu;
         if (perc >= 99.9F) {
            int w = (int)ceil(log10(perc + 0.1)) + 2;
            if (w > Row_fieldWidths[PERCENT_CPU]) Row_fieldWidths[PERCENT_CPU] = w;
            if (w > Row_fieldWidths[PERCENT_NORM_CPU]) Row_fieldWidths[PERCENT_NORM_CPU] = w;
         }
      }

      if (!updateUser(proc, procDir)) goto errorReading;
      if ((int)proc->st_uid > this->maxUserId) this->maxUserId = proc->st_uid;

      if (!preExisting) {
         if (proc->isKernelThread) {
            free(proc->cmdline); proc->cmdline = NULL;
            proc->cmdlineBasenameStart = 0; proc->cmdlineBasenameEnd = 0;
         } else {
            readCmdline(proc, procDir, statCommand);
         }
         fillStarttime(proc);
         readComm(proc, procDir);
         readExe(proc, procDir);
         proc->seenStampMs = this->monotonicMs;
         vec_push(this->rows, proc);
         phash_put(proc);
      } else {
         if (settings->updateProcessNames && proc->state != ZOMBIE) {
            if (proc->isKernelThread) { free(proc->cmdline); proc->cmdline = NULL; }
            else readCmdline(proc, procDir, statCommand);
         }
         readComm(proc, procDir);
         if (!proc->isKernelThread) readExe(proc, procDir);
      }

      if (ss->flags & PF_CGROUP) readCGroup(proc, procDir);
      if (ss->flags & PF_OOM) readOom(proc, procDir);
      if (ss->flags & PF_CTXT) readCtxt(proc, procDir);
      if (ss->flags & PF_SECATTR) readSecattr(proc, procDir);
      if (ss->flags & PF_CWD) readCwd(proc, procDir);
      if ((ss->flags & PF_AUTOGROUP) && this->haveAutogroup) readAutogroup(proc, procDir);
      if (ss->flags & PF_SCHEDPOL) readSchedPolicy(proc);
      if (proc->isRunningInContainer < 0) checkContainer(proc, procDir);

      if (!proc->cmdline && statCommand[0] &&
          (proc->state == ZOMBIE || proc->isKernelThread || settings->showThreadNames)) {
         free(proc->cmdline);
         proc->cmdline = xstrdup(statCommand);
         proc->cmdlineBasenameStart = 0;
         proc->cmdlineBasenameEnd = strlen(statCommand);
         proc->mcLastUpdate = 0;
      }

      if (proc->isKernelThread) this->kernelThreads++;
      else if (proc->isUserlandThread) this->userlandThreads++;

      proc->show = !((hideKernelThreads && proc->isKernelThread) ||
                     (hideUserlandThreads && proc->isUserlandThread) ||
                     (hideRunningInContainer && proc->isRunningInContainer == 1));
      this->totalTasks++;
      proc->updated = true;
      continue;

errorReading:
      if (!preExisting) Process_free(proc);
      else proc->updated = false;
   }
   closedir(dir);
}

extern char* CGroup_dummy;

void Machine_scanProcesses(Machine* this) {
   Settings* settings = this->settings;
   for (int i = 0; i < LAST_PROCESSFIELD; i++) {
      if (Fields[i].autoWidth) Row_fieldWidths[i] = Fields[i].title ? (int)strlen(Fields[i].title) : 0;
   }
   this->maxUserId = 0;
   this->totalTasks = 0;
   this->userlandThreads = 0;
   this->kernelThreads = 0;
   for (int i = 0; i < this->rows->size; i++) {
      Process* p = this->rows->items[i];
      p->updated = false;
      p->wasShown = p->show;
      p->show = true;
   }
   phash_rebuild(this);
   scanDir(this, "/proc", NULL);

   /* compute autowidths for string columns */
   for (int i = 0; i < this->rows->size; i++) {
      Process* p = this->rows->items[i];
      if (!p->updated) continue;
      if (p->secattr) { int l = strlen(p->secattr); if (l > Row_fieldWidths[SECATTR]) Row_fieldWidths[SECATTR] = MINI(l, 255); }
      if (p->cgroup) { int l = strlen(p->cgroup); if (l > Row_fieldWidths[CGROUP]) Row_fieldWidths[CGROUP] = MINI(l, 255); }
      if (p->cgroup_short) { int l = strlen(p->cgroup_short); if (l > Row_fieldWidths[CCGROUP]) Row_fieldWidths[CCGROUP] = MINI(l, 255); }
      if (p->container_short) { int l = strlen(p->container_short); if (l > Row_fieldWidths[CONTAINER]) Row_fieldWidths[CONTAINER] = MINI(l, 255); }
   }

   /* remove dead processes */
   for (int i = this->rows->size - 1; i >= 0; i--) {
      Process* p = this->rows->items[i];
      if (p->tombStampMs > 0) {
         if (this->monotonicMs >= p->tombStampMs) {
            vec_remove(this->rows, i);
            if (this->panel) {
               int idx = vec_indexOf(this->panel->items, p);
               if (idx >= 0) vec_remove(this->panel->items, idx);
            }
            int di = vec_indexOf(this->displayList, p);
            if (di >= 0) vec_remove(this->displayList, di);
            Process_free(p);
         } else {
            p->show = p->wasShown;
         }
      } else if (!p->updated) {
         if (settings->highlightChanges && p->wasShown) {
            p->tombStampMs = this->monotonicMs + 1000 * settings->highlightDelaySecs;
            p->show = p->wasShown;
         } else {
            vec_remove(this->rows, i);
            if (this->panel) {
               int idx = vec_indexOf(this->panel->items, p);
               if (idx >= 0) vec_remove(this->panel->items, idx);
            }
            int di = vec_indexOf(this->displayList, p);
            if (di >= 0) vec_remove(this->displayList, di);
            Process_free(p);
         }
      }
   }

   /* pid width from max pid */
   int maxPid = 0;
   for (int i = 0; i < this->rows->size; i++) {
      Process* p = this->rows->items[i];
      if (p->pid > maxPid) maxPid = p->pid;
   }
   (void)maxPid;
   {
      char buf[32];
      int pidMax = 32768;
      if (readFileBuf("/proc/sys/kernel/pid_max", buf, sizeof(buf)) > 0) pidMax = atoi(buf);
      (void)pidMax;
      Row_pidDigits = 5;
   }
   {
      int digits = 5;
      if (this->maxUserId >= 100000) {
         digits = 0;
         int v = this->maxUserId;
         while (v) { digits++; v /= 10; }
      }
      Row_uidDigits = digits;
   }
   this->firstScanDone = true;
   this->needsSort = true;
}

bool Machine_isInPidList(const Machine* this, int pid) {
   for (int i = 0; i < this->pidMatchCount; i++) if (this->pidMatchList[i] == pid) return true;
   return false;
}
