   if (totalDays < 365) {
      len = xsnprintf(buffer, sizeof(buffer), "%4ud", (unsigned int)totalDays);
      rs_appendn(str, dayColor, buffer, len);
      len = xsnprintf(buffer, sizeof(buffer), "%02uh ", hours);
      rs_appendn(str, hourColor, buffer, len);
      return;
   }
   unsigned long long totalYears = totalDays / 365;
   totalDays %= 365;
   if (totalYears < 1000) {
