/* ---------- command string ---------- */

static bool findCommInCmdline(const char* comm, const char* cmdline, int cmdlineBasenameStart, int* pCommStart, int* pCommLen) {
   int tokenLen;
   const char* token;
   const char* tokenBase;
   size_t commLen = strlen(comm);
   if (cmdlineBasenameStart < 0) return false;
   for (token = cmdline + cmdlineBasenameStart; *token;) {
      for (tokenBase = token; *token && *token != '\n' && *token != ' '; ++token) {
         if (*token == '/') tokenBase = token + 1;
      }
      if (!*tokenBase) return false;
      tokenLen = token - tokenBase;
      if ((tokenLen == (int)commLen || (tokenLen > (int)commLen && commLen == 15)) &&
          strncmp(tokenBase, comm, commLen) == 0) {
         *pCommStart = tokenBase - cmdline;
         *pCommLen = tokenLen;
         return true;
      }
      if (*token) {
         do { ++token; } while (*token && '\n' == *token);
      }
   }
   return false;
}

static int matchCmdlinePrefixWithExeSuffix(const char* cmdline, int cmdlineBaseOffset, const char* exe, int exeBaseOffset, int exeBaseLen) {
   int matchLen;
   if (!cmdline || !exe) return 0;
   if (cmdlineBaseOffset < 0) return 0;
   if (strncmp(cmdline + cmdlineBaseOffset, exe + exeBaseOffset, exeBaseLen) == 0) {
      matchLen = exeBaseLen + cmdlineBaseOffset;
      if (cmdline[matchLen] == '\0' || cmdline[matchLen] == ' ' || cmdline[matchLen] == '\n')
         return matchLen;
   }
   return 0;
}

const char* Process_getCommand(const Process* this) {
   const Settings* settings = this->host->settings;
   if ((this->isUserlandThread && settings->showThreadNames) || !this->mcStr) return this->cmdline;
   return this->mcStr;
}

void Process_makeCommandStr(Process* this) {
   const Settings* settings = this->host->settings;
   bool showMergedCommand = settings->showMergedCommand;
   bool showProgramPath = settings->showProgramPath;
   bool searchCommInCmdline = settings->findCommInCmdline;
   bool stripExeFromCmdline = settings->stripExeFromCmdline;
   bool showThreadNames = settings->showThreadNames;
   bool shadowDistPathPrefix = settings->shadowDistPathPrefix;
   uint64_t settingsStamp = settings->lastUpdate;

   if (this->isKernelThread) return;
   if (this->state == ZOMBIE && !this->mcStr) return;
   if (this->isUserlandThread && settings->showThreadNames && (showThreadNames == this->mcPrevThreadNames) && (this->mcPrevMergeSet == showMergedCommand)) return;
   if (this->mcLastUpdate >= settingsStamp) return;
   this->mcLastUpdate = settingsStamp;
   this->mcPrevMergeSet = showMergedCommand;
   this->mcPrevThreadNames = showThreadNames;

   const char* SEPARATOR = CRT_treeStr[TREE_STR_VERT];
   const int SEPARATOR_LEN = strlen(SEPARATOR);
   size_t maxLen = 2 * SEPARATOR_LEN + 1;
   maxLen += this->cmdline ? strlen(this->cmdline) : strlen("(zombie)");
   maxLen += this->procComm ? strlen(this->procComm) : 0;
   maxLen += this->procExe ? strlen(this->procExe) : 0;
   free(this->mcStr);
   this->mcStr = xcalloc(1, maxLen);
   this->mcHighlightCount = 0;
   memset(this->mcHighlights, 0, sizeof(this->mcHighlights));

   char* strStart = this->mcStr;
   char* str = strStart;
   int mbMismatch = 0;

#define WRITE_HIGHLIGHT(_offset, _length, _attr, _flags) do { \
      if (this->mcHighlightCount >= (int)ARRLEN(this->mcHighlights)) break; \
      this->mcHighlights[this->mcHighlightCount].offset = str - strStart + (_offset) - mbMismatch; \
      this->mcHighlights[this->mcHighlightCount].length = _length; \
      this->mcHighlights[this->mcHighlightCount].attr = _attr; \
      this->mcHighlights[this->mcHighlightCount].flags = _flags; \
      this->mcHighlightCount++; } while (0)
#define WRITE_SEPARATOR do { \
      WRITE_HIGHLIGHT(0, 1, CRT_colors[FAILED_READ], HL_FLAG_SEPARATOR); \
      mbMismatch += SEPARATOR_LEN - 1; \
      str = stpcpy(str, SEPARATOR); } while (0)
#define CHECK_AND_MARK(str_, prefix_) \
      if (str_starts(str_, prefix_)) { \
         WRITE_HIGHLIGHT(0, strlen(prefix_), CRT_colors[PROCESS_SHADOW], HL_FLAG_PREFIXDIR); \
         break; \
      } else (void)0
#define CHECK_AND_MARK_DIST_PATH_PREFIXES(str_) do { \
      if ((str_)[0] != '/') break; \
      switch ((str_)[1]) { \
      case 'b': CHECK_AND_MARK(str_, "/bin/"); break; \
      case 'l': CHECK_AND_MARK(str_, "/lib/"); CHECK_AND_MARK(str_, "/lib32/"); CHECK_AND_MARK(str_, "/lib64/"); CHECK_AND_MARK(str_, "/libx32/"); break; \
      case 's': CHECK_AND_MARK(str_, "/sbin/"); break; \
      case 'u': \
         if (str_starts(str_, "/usr/")) { \
            switch ((str_)[5]) { \
            case 'b': CHECK_AND_MARK(str_, "/usr/bin/"); break; \
            case 'l': CHECK_AND_MARK(str_, "/usr/libexec/"); CHECK_AND_MARK(str_, "/usr/lib/"); CHECK_AND_MARK(str_, "/usr/lib32/"); \
                      CHECK_AND_MARK(str_, "/usr/lib64/"); CHECK_AND_MARK(str_, "/usr/libx32/"); \
                      CHECK_AND_MARK(str_, "/usr/local/bin/"); CHECK_AND_MARK(str_, "/usr/local/lib/"); CHECK_AND_MARK(str_, "/usr/local/sbin/"); break; \
            case 's': CHECK_AND_MARK(str_, "/usr/sbin/"); break; \
            } \
         } \
         break; \
      } } while (0)

   const int baseAttr = Process_isThread(this) ? CRT_colors[PROCESS_THREAD_BASENAME] : CRT_colors[PROCESS_BASENAME];
   const int commAttr = Process_isThread(this) ? CRT_colors[PROCESS_THREAD_COMM] : CRT_colors[PROCESS_COMM];
   const int delExeAttr = CRT_colors[FAILED_READ];
   const int delLibAttr = CRT_colors[PROCESS_LOW_PRIORITY];

   const char* cmdline = this->cmdline;
   const char* procComm = this->procComm;
   const char* procExe = this->procExe;
   int cmdlineBasenameStart = this->cmdlineBasenameStart;
   int cmdlineBasenameEnd = this->cmdlineBasenameEnd;
   if (!cmdline) {
      cmdlineBasenameStart = 0;
      cmdlineBasenameEnd = 0;
      cmdline = "(zombie)";
   }

   if (!showMergedCommand || !procExe || !procComm) {
      if ((showMergedCommand || (this->isUserlandThread && showThreadNames)) && procComm && strlen(procComm)) {
         if (strncmp(cmdline + cmdlineBasenameStart, procComm, MINI(15, (int)strlen(procComm))) != 0) {
            WRITE_HIGHLIGHT(0, strlen(procComm), commAttr, HL_FLAG_COMM);
            str = stpcpy(str, procComm);
            if (!showMergedCommand) return;
            WRITE_SEPARATOR;
         }
      }
      if (shadowDistPathPrefix && showProgramPath) CHECK_AND_MARK_DIST_PATH_PREFIXES(cmdline);
      if (cmdlineBasenameEnd > cmdlineBasenameStart)
         WRITE_HIGHLIGHT(showProgramPath ? cmdlineBasenameStart : 0, cmdlineBasenameEnd - cmdlineBasenameStart, baseAttr, HL_FLAG_BASENAME);
      if (this->procExeDeleted)
         WRITE_HIGHLIGHT(showProgramPath ? cmdlineBasenameStart : 0, cmdlineBasenameEnd - cmdlineBasenameStart, delExeAttr, HL_FLAG_DELETED);
      else if (this->usesDeletedLib)
         WRITE_HIGHLIGHT(showProgramPath ? cmdlineBasenameStart : 0, cmdlineBasenameEnd - cmdlineBasenameStart, delLibAttr, HL_FLAG_DELETED);
      (void)stpcpy(str, cmdline + (showProgramPath ? 0 : cmdlineBasenameStart));
      return;
   }

   int exeLen = strlen(procExe);
   int exeBasenameOffset = this->procExeBasenameOffset;
   int exeBasenameLen = exeLen - exeBasenameOffset;

   bool haveCommInExe = false;
   if (procExe && procComm && (!this->isUserlandThread || showThreadNames)) {
      haveCommInExe = strncmp(procExe + exeBasenameOffset, procComm, 15) == 0;
   }

   if (showProgramPath) {
      if (shadowDistPathPrefix) CHECK_AND_MARK_DIST_PATH_PREFIXES(procExe);
      if (haveCommInExe) WRITE_HIGHLIGHT(exeBasenameOffset, exeBasenameLen, commAttr, HL_FLAG_COMM);
      WRITE_HIGHLIGHT(exeBasenameOffset, exeBasenameLen, baseAttr, HL_FLAG_BASENAME);
      if (this->procExeDeleted) WRITE_HIGHLIGHT(exeBasenameOffset, exeBasenameLen, delExeAttr, HL_FLAG_DELETED);
      else if (this->usesDeletedLib) WRITE_HIGHLIGHT(exeBasenameOffset, exeBasenameLen, delLibAttr, HL_FLAG_DELETED);
      str = stpcpy(str, procExe);
   } else {
      if (haveCommInExe) WRITE_HIGHLIGHT(0, exeBasenameLen, commAttr, HL_FLAG_COMM);
      WRITE_HIGHLIGHT(0, exeBasenameLen, baseAttr, HL_FLAG_BASENAME);
      if (this->procExeDeleted) WRITE_HIGHLIGHT(0, exeBasenameLen, delExeAttr, HL_FLAG_DELETED);
      else if (this->usesDeletedLib) WRITE_HIGHLIGHT(0, exeBasenameLen, delLibAttr, HL_FLAG_DELETED);
      str = stpcpy(str, procExe + exeBasenameOffset);
   }

   bool haveCommInCmdline = false;
   int commStart = 0;
   int commLen = 0;
   if (!haveCommInExe && searchCommInCmdline) {
      haveCommInCmdline = (!this->isUserlandThread || showThreadNames) && findCommInCmdline(procComm, cmdline, cmdlineBasenameStart, &commStart, &commLen);
   }

   int matchLen = matchCmdlinePrefixWithExeSuffix(cmdline, cmdlineBasenameStart, procExe, exeBasenameOffset, exeBasenameLen);

   bool haveCommField = false;
   if (!haveCommInExe && !haveCommInCmdline && procComm && (!this->isUserlandThread || showThreadNames)) {
      WRITE_SEPARATOR;
      WRITE_HIGHLIGHT(0, strlen(procComm), commAttr, HL_FLAG_COMM);
      str = stpcpy(str, procComm);
      haveCommField = true;
   }

   if (matchLen) {
      if (stripExeFromCmdline) {
         cmdline += matchLen;
         commStart -= matchLen;
      } else {
         matchLen = 0;
      }
   }

   if (!matchLen || (haveCommField && *cmdline)) {
      WRITE_SEPARATOR;
   }

   if (shadowDistPathPrefix) CHECK_AND_MARK_DIST_PATH_PREFIXES(cmdline);

   if (!haveCommInExe && haveCommInCmdline && !haveCommField && (!this->isUserlandThread || showThreadNames))
      WRITE_HIGHLIGHT(commStart, commLen, commAttr, HL_FLAG_COMM);

   if (*cmdline) (void)stpcpy(str, cmdline);

#undef CHECK_AND_MARK_DIST_PATH_PREFIXES
#undef CHECK_AND_MARK
#undef WRITE_SEPARATOR
#undef WRITE_HIGHLIGHT
}

static void writeCommand(const Process* this, int attr, int baseAttr, RStr* str) {
   const char* merged = this->mcStr;
   int strStart = str->len;
   const Settings* settings = this->host->settings;
   bool highlightBaseName = settings->highlightBaseName;
   bool highlightDeleted = settings->highlightDeletedExe;
   bool highlightPrefixDir = settings->shadowDistPathPrefix;

   if (!merged || (this->isUserlandThread && settings->showThreadNames)) {
      int len = 0;
      const char* cmdline = this->cmdline;
      if (!cmdline) cmdline = "";
      if (highlightBaseName || !settings->showProgramPath) {
         int basename = 0;
         for (int i = 0; i < this->cmdlineBasenameEnd && cmdline[i]; i++) {
            if (cmdline[i] == '/') basename = i + 1;
            else if (cmdline[i] == ':') { len = i + 1; break; }
         }
         if (len == 0) {
            if (settings->showProgramPath) strStart += basename;
            else cmdline += basename;
            len = this->cmdlineBasenameEnd - basename;
         }
      }
      rs_append(str, attr, cmdline);
      if (settings->highlightBaseName) rs_setAttrn(str, baseAttr, strStart, len);
      return;
   }

   rs_append(str, attr, merged);
   for (int i = 0; i < this->mcHighlightCount; i++) {
      const CmdHighlight* hl = &this->mcHighlights[i];
      if (!hl->length) continue;
      if ((hl->flags & HL_FLAG_BASENAME) && !highlightBaseName) continue;
      if ((hl->flags & HL_FLAG_DELETED) && !highlightDeleted) continue;
      if ((hl->flags & HL_FLAG_PREFIXDIR) && !highlightPrefixDir) continue;
      rs_setAttrn(str, hl->attr, strStart + hl->offset, hl->length);
   }
}

/* ---------- fields ---------- */

void Process_writeField(const Process* this, RStr* str, int field) {
   const Machine* host = this->host;
   const Settings* settings = host->settings;
   bool coloring = settings->highlightMegabytes;
   char buffer[256];
   int attr = CRT_colors[DEFAULT_COLOR];
   size_t n = sizeof(buffer) - 1;
   buffer[0] = 0;
   int pk = host->pageSizeKB;

   switch (field) {
   case PID: xsnprintf(buffer, n, "%*d ", Row_pidDigits, this->pid); break;
   case PPID: xsnprintf(buffer, n, "%*d ", Row_pidDigits, this->ppid); break;
   case PGRP: xsnprintf(buffer, n, "%*d ", Row_pidDigits, this->pgrp); break;
   case SESSION: xsnprintf(buffer, n, "%*d ", Row_pidDigits, this->session); break;
   case TPGID: xsnprintf(buffer, n, "%*d ", Row_pidDigits, this->tpgid); break;
   case TGID:
      if (this->tgid == this->pid) attr = CRT_colors[PROCESS_SHADOW];
      xsnprintf(buffer, n, "%*d ", Row_pidDigits, this->tgid);
      break;
   case STATE: {
      xsnprintf(buffer, n, "%c ", stateChar(this->state));
      switch (this->state) {
      case RUNNABLE: case RUNNING: case TRACED:
         attr = CRT_colors[PROCESS_RUN_STATE]; break;
      case BLOCKED: case DEFUNCT: case PAGING: case UNINTERRUPTIBLE_WAIT: case ZOMBIE:
         attr = CRT_colors[PROCESS_D_STATE]; break;
      case QUEUED: case WAITING: case IDLE: case SLEEPING:
         attr = CRT_colors[PROCESS_SHADOW]; break;
      case UNKNOWN: case STOPPED:
         break;
      }
      break;
   }
   case COMM: {
      int baseattr = CRT_colors[PROCESS_BASENAME];
      if (settings->highlightThreads && Process_isThread(this)) {
         attr = CRT_colors[PROCESS_THREAD];
         baseattr = CRT_colors[PROCESS_THREAD_BASENAME];
      }
      const ScreenSettings* ss = settings->ss;
      if (!ss->treeView || this->indent == 0) {
         writeCommand(this, attr, baseattr, str);
         return;
      }
      char* buf = buffer;
      size_t rem = n;
      bool lastItem = (this->indent < 0);
      for (uint32_t indent = (this->indent < 0 ? -this->indent : this->indent); indent > 1; indent >>= 1) {
         int ret;
         if (indent & 1U) ret = snprintf(buf, rem, "%s  ", CRT_treeStr[TREE_STR_VERT]);
         else ret = snprintf(buf, rem, "   ");
         int written = (ret < 0 || (size_t)ret >= rem) ? (int)rem : ret;
         buf += written;
         rem -= written;
      }
      const char* draw = CRT_treeStr[lastItem ? TREE_STR_BEND : TREE_STR_RTEE];
      snprintf(buf, rem, "%s%s ", draw, this->showChildren ? CRT_treeStr[TREE_STR_SHUT] : CRT_treeStr[TREE_STR_OPEN]);
      rs_append(str, CRT_colors[PROCESS_TREE], buffer);
      writeCommand(this, attr, baseattr, str);
      return;
   }
   case PROC_COMM: {
      const char* procComm;
      if (this->procComm) {
         attr = CRT_colors[this->isUserlandThread ? PROCESS_THREAD_COMM : PROCESS_COMM];
         procComm = this->procComm;
      } else {
         attr = CRT_colors[PROCESS_SHADOW];
         procComm = this->isKernelThread ? kthreadID : "N/A";
      }
      printLeftAligned(str, attr, procComm, 15);
      return;
   }
   case PROC_EXE: {
      const char* procExe;
      if (this->procExe) {
         attr = CRT_colors[this->isUserlandThread ? PROCESS_THREAD_BASENAME : PROCESS_BASENAME];
         if (settings->highlightDeletedExe) {
            if (this->procExeDeleted) attr = CRT_colors[FAILED_READ];
            else if (this->usesDeletedLib) attr = CRT_colors[PROCESS_LOW_PRIORITY];
         }
         procExe = this->procExe + this->procExeBasenameOffset;
      } else {
         attr = CRT_colors[PROCESS_SHADOW];
         procExe = this->isKernelThread ? kthreadID : "N/A";
      }
      printLeftAligned(str, attr, procExe, 15);
      return;
   }
   case CWD: {
      const char* cwd;
      if (!this->procCwd) {
         attr = CRT_colors[PROCESS_SHADOW];
         cwd = "N/A";
      } else if (str_starts(this->procCwd, "/proc/") && strstr(this->procCwd, " (deleted)") != NULL) {
         attr = CRT_colors[PROCESS_SHADOW];
         cwd = "main thread terminated";
      } else {
         cwd = this->procCwd;
      }
      printLeftAligned(str, attr, cwd, 25);
      return;
   }
   case ELAPSED: {
      uint64_t rt = host->realtimeMs;
      uint64_t st = (uint64_t)this->starttime_ctime * 1000;
      uint64_t dt = rt < st ? 0 : rt - st;
      Process_printTime(str, dt / 10, coloring);
      return;
   }
   case MAJFLT: Process_printCount(str, this->majflt, coloring); return;
   case MINFLT: Process_printCount(str, this->minflt, coloring); return;
   case CMAJFLT: Process_printCount(str, this->cmajflt, coloring); return;
   case CMINFLT: Process_printCount(str, this->cminflt, coloring); return;
   case M_RESIDENT: Process_printKBytes(str, this->m_resident, coloring); return;
   case M_VIRT: Process_printKBytes(str, this->m_virt, coloring); return;
   case M_SHARE: Process_printKBytes(str, this->m_share * pk, coloring); return;
   case M_TRS: Process_printKBytes(str, this->m_trs * pk, coloring); return;
   case M_DRS: Process_printKBytes(str, this->m_drs * pk, coloring); return;
   case M_PRIV: Process_printKBytes(str, this->m_priv, coloring); return;
   case M_LRS:
      if (this->m_lrs) { Process_printKBytes(str, this->m_lrs, coloring); return; }
      attr = CRT_colors[PROCESS_SHADOW];
      xsnprintf(buffer, n, "  N/A ");
      break;
   case M_PSS: Process_printKBytes(str, this->m_pss, coloring); return;
   case M_SWAP: Process_printKBytes(str, this->m_swap, coloring); return;
   case M_PSSWP: Process_printKBytes(str, this->m_psswp, coloring); return;
   case UTIME: Process_printTime(str, this->utime, coloring); return;
   case STIME: Process_printTime(str, this->stime, coloring); return;
   case CUTIME: Process_printTime(str, this->cutime, coloring); return;
   case CSTIME: Process_printTime(str, this->cstime, coloring); return;
   case TIME: Process_printTime(str, this->time, coloring); return;
   case NICE:
      xsnprintf(buffer, n, "%3ld ", this->nice);
      attr = this->nice < 0 ? CRT_colors[PROCESS_HIGH_PRIORITY]
           : this->nice > 0 ? CRT_colors[PROCESS_LOW_PRIORITY]
           : CRT_colors[PROCESS_SHADOW];
      break;
   case NLWP:
      if (this->nlwp == 1) attr = CRT_colors[PROCESS_SHADOW];
      xsnprintf(buffer, n, "%4ld ", this->nlwp);
      break;
   case PERCENT_CPU: printPercentage(this->percent_cpu, buffer, n, Row_fieldWidths[PERCENT_CPU], &attr); break;
   case PERCENT_NORM_CPU: {
      float cpuPercentage = this->percent_cpu / (host->activeCPUs ? host->activeCPUs : 1);
      printPercentage(cpuPercentage, buffer, n, Row_fieldWidths[PERCENT_CPU], &attr);
      break;
   }
   case PERCENT_MEM: printPercentage(this->percent_mem, buffer, n, 4, &attr); break;
   case PRIORITY:
      if (this->priority <= -100) xsnprintf(buffer, n, " RT ");
      else xsnprintf(buffer, n, "%3ld ", this->priority);
      break;
   case PROCESSOR: xsnprintf(buffer, n, "%3d ", Settings_cpuId(settings, this->processor)); break;
   case SCHEDULERPOLICY: {
      const char* s = "N/A ";
      if (this->scheduling_policy >= 0) s = schedPolicyName(this->scheduling_policy);
      xsnprintf(buffer, n, "%-5s ", s);
      break;
   }
   case ST_UID: xsnprintf(buffer, n, "%*d ", Row_uidDigits, this->st_uid); break;
   case STARTTIME: xsnprintf(buffer, n, "%s", this->starttime_show); break;
   case TTY:
      if (!this->tty_name) {
         attr = CRT_colors[PROCESS_SHADOW];
         xsnprintf(buffer, n, "(no tty) ");
      } else {
         const char* name = str_starts(this->tty_name, "/dev/") ? (this->tty_name + 5) : this->tty_name;
         xsnprintf(buffer, n, "%-8s ", name);
      }
      break;
   case USER:
      if (this->elevatedPriv) attr = CRT_colors[PROCESS_PRIV];
      else if (host->htopUserId != this->st_uid) attr = CRT_colors[PROCESS_SHADOW];
      if (this->user) { printLeftAligned(str, attr, this->user, 10); return; }
      xsnprintf(buffer, n, "%-10d ", this->st_uid);
      break;
   case RBYTES: printBytes(str, this->io_read_bytes, coloring); return;
   case WBYTES: printBytes(str, this->io_write_bytes, coloring); return;
   case CNCLWB: printBytes(str, this->io_cancelled_write_bytes, coloring); return;
   case IO_READ_RATE: printRate(str, this->io_rate_read_bps, coloring); return;
   case IO_WRITE_RATE: printRate(str, this->io_rate_write_bps, coloring); return;
   case IO_RATE: {
      double totalRate;
      if (!isnan(this->io_rate_read_bps) && !isnan(this->io_rate_write_bps)) totalRate = this->io_rate_read_bps + this->io_rate_write_bps;
      else if (!isnan(this->io_rate_read_bps)) totalRate = this->io_rate_read_bps;
      else if (!isnan(this->io_rate_write_bps)) totalRate = this->io_rate_write_bps;
      else totalRate = NAN;
      printRate(str, totalRate, coloring);
      return;
   }
   case RCHAR: printBytes(str, this->io_rchar, coloring); return;
   case WCHAR: printBytes(str, this->io_wchar, coloring); return;
   case SYSCR: Process_printCount(str, this->io_syscr, coloring); return;
   case SYSCW: Process_printCount(str, this->io_syscw, coloring); return;
   case CGROUP: printLeftAligned(str, attr, this->cgroup ? this->cgroup : "N/A", Row_fieldWidths[CGROUP]); return;
   case CCGROUP: printLeftAligned(str, attr, this->cgroup_short ? this->cgroup_short : (this->cgroup ? this->cgroup : "N/A"), Row_fieldWidths[CCGROUP]); return;
   case CONTAINER: printLeftAligned(str, attr, this->container_short ? this->container_short : "N/A", Row_fieldWidths[CONTAINER]); return;
   case OOM: xsnprintf(buffer, n, "%4u ", this->oom); break;
   case IO_PRIORITY: {
      int klass = this->ioPriority < 0 ? IOPRIO_CLASS_NONE : (int)IOPRIO_PRIO_CLASS(this->ioPriority);
      if (klass == IOPRIO_CLASS_NONE) {
         xsnprintf(buffer, n, "B%1d ", (int)(this->nice + 20) / 5);
      } else if (klass == IOPRIO_CLASS_BE) {
         xsnprintf(buffer, n, "B%1d ", (int)IOPRIO_PRIO_DATA(this->ioPriority));
      } else if (klass == IOPRIO_CLASS_RT) {
         attr = CRT_colors[PROCESS_HIGH_PRIORITY];
         xsnprintf(buffer, n, "R%1d ", (int)IOPRIO_PRIO_DATA(this->ioPriority));
      } else if (klass == IOPRIO_CLASS_IDLE) {
         attr = CRT_colors[PROCESS_LOW_PRIORITY];
         xsnprintf(buffer, n, "id ");
      } else {
         xsnprintf(buffer, n, "?? ");
      }
      break;
   }
   case CTXT:
      if (this->ctxt_diff > 1000) attr |= A_BOLD;
      xsnprintf(buffer, n, "%5llu ", this->ctxt_diff);
      break;
   case SECATTR: printLeftAligned(str, attr, this->secattr ? this->secattr : "N/A", Row_fieldWidths[SECATTR]); return;
   case AUTOGROUP_ID:
      if (this->autogroup_id != -1) {
         xsnprintf(buffer, n, "%4ld ", this->autogroup_id);
      } else {
         attr = CRT_colors[PROCESS_SHADOW];
         xsnprintf(buffer, n, " N/A ");
      }
      break;
   case AUTOGROUP_NICE:
      if (this->autogroup_id != -1) {
         xsnprintf(buffer, n, "%3d ", this->autogroup_nice);
         attr = this->autogroup_nice < 0 ? CRT_colors[PROCESS_HIGH_PRIORITY]
              : this->autogroup_nice > 0 ? CRT_colors[PROCESS_LOW_PRIORITY]
              : CRT_colors[PROCESS_SHADOW];
      } else {
         attr = CRT_colors[PROCESS_SHADOW];
         xsnprintf(buffer, n, "N/A ");
      }
      break;
   case GPU_TIME: {
      unsigned long long ns = this->gpu_time;
      if (ns == 0) { xsnprintf(buffer, n, "%8s ", "0ns"); attr = CRT_colors[PROCESS_SHADOW]; }
      else xsnprintf(buffer, n, "%8llu ", ns);
      break;
   }
   case GPU_PERCENT:
      printPercentage(isnan(this->gpu_percent) ? 0.0F : this->gpu_percent, buffer, n, 5, &attr);
      break;
   case ISCONTAINER:
      switch (this->isRunningInContainer) {
      case 1: xsnprintf(buffer, n, "YES  "); break;
      case 0: xsnprintf(buffer, n, "NO   "); break;
      default: attr = CRT_colors[PROCESS_SHADOW]; xsnprintf(buffer, n, "N/A  "); break;
      }
      break;
   default:
      xsnprintf(buffer, n, "- ");
      break;
   }
   rs_append(str, attr, buffer);
}

static bool isNew(const Process* this) {
   const Machine* host = this->host;
   if (host->monotonicMs < this->seenStampMs) return false;
   return host->monotonicMs - this->seenStampMs <= 1000 * (uint64_t)host->settings->highlightDelaySecs;
}

void Process_display(const Item* cast, RStr* out) {
   const Process* this = (const Process*)cast;
   const Settings* settings = this->host->settings;
   const int* fields = settings->ss->fields;
   for (int i = 0; fields[i]; i++) Process_writeField(this, out, fields[i]);
   if (settings->shadowOtherUsers && this->st_uid != this->host->htopUserId)
      rs_setAttr(out, CRT_colors[PROCESS_SHADOW]);
   if (this->tag) rs_setAttr(out, CRT_colors[PROCESS_TAG]);
   if (settings->highlightChanges) {
      if (this->tombStampMs > 0) out->highlightAttr = CRT_colors[PROCESS_TOMB];
      else if (isNew(this)) out->highlightAttr = CRT_colors[PROCESS_NEW];
   }
}

/* ---------- comparison ---------- */
#define SPACESHIP(a, b) (((a) > (b)) - ((a) < (b)))
static int cmpNullStr(const char* a, const char* b) {
   if (!a) a = ""; if (!b) b = "";
   return strcmp(a, b);
}
static int cmpReal(double a, double b) {
   int r = isgreater(a, b) - isgreater(b, a);
   if (r) return r;
   return !isnan(a) - !isnan(b);
}

static int compareByKey(const Process* p1, const Process* p2, int key) {
   int r;
   int pk = p1->host->pageSizeKB; (void)pk;
   switch (key) {
   case PERCENT_CPU:
   case PERCENT_NORM_CPU:
      return cmpReal(p1->percent_cpu, p2->percent_cpu);
   case PERCENT_MEM:
      return SPACESHIP(p1->m_resident, p2->m_resident);
   case COMM:
      return cmpNullStr(Process_getCommand(p1), Process_getCommand(p2));
   case PROC_COMM: {
      const char* c1 = p1->procComm ? p1->procComm : (p1->isKernelThread ? kthreadID : "");
      const char* c2 = p2->procComm ? p2->procComm : (p2->isKernelThread ? kthreadID : "");
      return cmpNullStr(c1, c2);
   }
   case PROC_EXE: {
      const char* e1 = p1->procExe ? (p1->procExe + p1->procExeBasenameOffset) : (p1->isKernelThread ? kthreadID : "");
      const char* e2 = p2->procExe ? (p2->procExe + p2->procExeBasenameOffset) : (p2->isKernelThread ? kthreadID : "");
      return cmpNullStr(e1, e2);
   }
   case CWD: return cmpNullStr(p1->procCwd, p2->procCwd);
   case ELAPSED:
      r = -SPACESHIP(p1->starttime_ctime, p2->starttime_ctime);
      return r != 0 ? r : SPACESHIP(p1->pid, p2->pid);
   case MAJFLT: return SPACESHIP(p1->majflt, p2->majflt);
   case MINFLT: return SPACESHIP(p1->minflt, p2->minflt);
   case CMAJFLT: return SPACESHIP(p1->cmajflt, p2->cmajflt);
   case CMINFLT: return SPACESHIP(p1->cminflt, p2->cminflt);
   case M_RESIDENT: return SPACESHIP(p1->m_resident, p2->m_resident);
   case M_VIRT: return SPACESHIP(p1->m_virt, p2->m_virt);
   case M_SHARE: return SPACESHIP(p1->m_share, p2->m_share);
   case M_TRS: return SPACESHIP(p1->m_trs, p2->m_trs);
   case M_DRS: return SPACESHIP(p1->m_drs, p2->m_drs);
   case M_LRS: return SPACESHIP(p1->m_lrs, p2->m_lrs);
   case M_PSS: return SPACESHIP(p1->m_pss, p2->m_pss);
   case M_SWAP: return SPACESHIP(p1->m_swap, p2->m_swap);
   case M_PSSWP: return SPACESHIP(p1->m_psswp, p2->m_psswp);
   case M_PRIV: return SPACESHIP(p1->m_priv, p2->m_priv);
   case NICE: return SPACESHIP(p1->nice, p2->nice);
   case NLWP: return SPACESHIP(p1->nlwp, p2->nlwp);
   case PGRP: return SPACESHIP(p1->pgrp, p2->pgrp);
   case PID: return SPACESHIP(p1->pid, p2->pid);
   case PPID: return SPACESHIP(p1->ppid, p2->ppid);
   case PRIORITY: return SPACESHIP(p1->priority, p2->priority);
   case PROCESSOR: return SPACESHIP(p1->processor, p2->processor);
   case SCHEDULERPOLICY: return SPACESHIP(p1->scheduling_policy, p2->scheduling_policy);
   case SESSION: return SPACESHIP(p1->session, p2->session);
   case STARTTIME:
      r = SPACESHIP(p1->starttime_ctime, p2->starttime_ctime);
      return r != 0 ? r : SPACESHIP(p1->pid, p2->pid);
   case STATE: return SPACESHIP(p1->state, p2->state);
   case ST_UID: return SPACESHIP(p1->st_uid, p2->st_uid);
   case TIME: return SPACESHIP(p1->time, p2->time);
   case UTIME: return SPACESHIP(p1->utime, p2->utime);
   case STIME: return SPACESHIP(p1->stime, p2->stime);
   case CUTIME: return SPACESHIP(p1->cutime, p2->cutime);
   case CSTIME: return SPACESHIP(p1->cstime, p2->cstime);
   case TGID: return SPACESHIP(p1->tgid, p2->tgid);
   case TPGID: return SPACESHIP(p1->tpgid, p2->tpgid);
   case TTY: {
      const char* a = p1->tty_name ? p1->tty_name : "\x7F";
      const char* b = p2->tty_name ? p2->tty_name : "\x7F";
      return strcmp(a, b);
   }
   case USER: return cmpNullStr(p1->user, p2->user);
   case RCHAR: return SPACESHIP(p1->io_rchar, p2->io_rchar);
   case WCHAR: return SPACESHIP(p1->io_wchar, p2->io_wchar);
   case SYSCR: return SPACESHIP(p1->io_syscr, p2->io_syscr);
   case SYSCW: return SPACESHIP(p1->io_syscw, p2->io_syscw);
   case RBYTES: return SPACESHIP(p1->io_read_bytes, p2->io_read_bytes);
   case WBYTES: return SPACESHIP(p1->io_write_bytes, p2->io_write_bytes);
   case CNCLWB: return SPACESHIP(p1->io_cancelled_write_bytes, p2->io_cancelled_write_bytes);
   case IO_READ_RATE: return cmpReal(p1->io_rate_read_bps, p2->io_rate_read_bps);
   case IO_WRITE_RATE: return cmpReal(p1->io_rate_write_bps, p2->io_rate_write_bps);
   case IO_RATE: {
      double a = (isnan(p1->io_rate_read_bps) ? 0 : p1->io_rate_read_bps) + (isnan(p1->io_rate_write_bps) ? 0 : p1->io_rate_write_bps);
      double b = (isnan(p2->io_rate_read_bps) ? 0 : p2->io_rate_read_bps) + (isnan(p2->io_rate_write_bps) ? 0 : p2->io_rate_write_bps);
      if (isnan(p1->io_rate_read_bps) && isnan(p1->io_rate_write_bps)) a = NAN;
      if (isnan(p2->io_rate_read_bps) && isnan(p2->io_rate_write_bps)) b = NAN;
      return cmpReal(a, b);
   }
   case CGROUP: return cmpNullStr(p1->cgroup, p2->cgroup);
   case CCGROUP: return cmpNullStr(p1->cgroup_short, p2->cgroup_short);
   case CONTAINER: return cmpNullStr(p1->container_short, p2->container_short);
   case OOM: return SPACESHIP(p1->oom, p2->oom);
   case IO_PRIORITY: return SPACESHIP(p1->ioPriority, p2->ioPriority);
   case CTXT: return SPACESHIP(p1->ctxt_diff, p2->ctxt_diff);
   case SECATTR: return cmpNullStr(p1->secattr, p2->secattr);
   case AUTOGROUP_ID: return SPACESHIP(p1->autogroup_id, p2->autogroup_id);
   case AUTOGROUP_NICE: return SPACESHIP(p1->autogroup_nice, p2->autogroup_nice);
   case GPU_TIME: return SPACESHIP(p1->gpu_time, p2->gpu_time);
   case GPU_PERCENT: return cmpReal(p1->gpu_percent, p2->gpu_percent);
   case ISCONTAINER: return SPACESHIP(p1->isRunningInContainer, p2->isRunningInContainer);
   default:
      return SPACESHIP(p1->pid, p2->pid);
   }
}

int Process_compare(const void* v1, const void* v2) {
   const Process* p1 = v1;
   const Process* p2 = v2;
   const ScreenSettings* ss = p1->host->settings->ss;
   int key = ScreenSettings_getActiveSortKey(ss);
   int result = compareByKey(p1, p2, key);
   if (!result) return SPACESHIP(p1->pid, p2->pid);
   return (ScreenSettings_getActiveDirection(ss) == 1) ? result : -result;
}

static int Process_compareItem(const void* a, const void* b) { return Process_compare(a, b); }
const ItemClass Process_class = { Process_display, NULL, Process_compareItem };

/* ---------- header ---------- */
void Process_printHeader(const Settings* settings, RStr* header) {
   rs_reset(header);
   const ScreenSettings* ss = settings->ss;
   const int* fields = ss->fields;
   int key = ScreenSettings_getActiveSortKey(ss);
   for (int i = 0; fields[i]; i++) {
      int color;
      if (ss->treeView && ss->treeViewAlwaysByPID) color = CRT_colors[PANEL_HEADER_FOCUS];
      else if (key == fields[i]) color = CRT_colors[PANEL_SELECTION_FOCUS];
      else color = CRT_colors[PANEL_HEADER_FOCUS];
      int field = fields[i];
      const char* title = Fields[field].title;
      char buf[300];
      if (!title) {
         title = "- ";
      } else if (Fields[field].pidColumn) {
         xsnprintf(buf, sizeof(buf), "%*s ", Row_pidDigits, title);
         title = buf;
      } else if (field == ST_UID) {
         xsnprintf(buf, sizeof(buf), "%*s ", Row_uidDigits, title);
         title = buf;
      } else if (Fields[field].autoWidth) {
         if (field == PERCENT_CPU || field == PERCENT_NORM_CPU)
            xsnprintf(buf, sizeof(buf), "%*s ", Row_fieldWidths[field], title);
         else
            xsnprintf(buf, sizeof(buf), "%-*.*s ", Row_fieldWidths[field], Row_fieldWidths[field], title);
         title = buf;
      }
      rs_append(header, color, title);
      if (key == field && header->len > 0 && rs_getChar(header, header->len - 1) == ' ') {
         bool ascending = ScreenSettings_getActiveDirection(ss) == 1;
         rs_rewind(header, 1);
         rs_append(header, CRT_colors[PANEL_SELECTION_FOCUS], CRT_treeStr[ascending ? TREE_STR_ASC : TREE_STR_DESC]);
      }
      if (field == COMM && settings->showMergedCommand) {
         rs_append(header, color, "(merged)");
      }
   }
}

/* ---------- actions on processes ---------- */
bool Process_setPriority(Process* this, int priority) {
   if (Settings_readonly) return false;
   int old_prio = getpriority(PRIO_PROCESS, this->pid);
   int err = setpriority(PRIO_PROCESS, this->pid, priority);
   if (err == 0 && old_prio != getpriority(PRIO_PROCESS, this->pid)) this->nice = priority;
   return (err == 0);
}
bool Process_changePriorityBy(Process* this, int delta) { return Process_setPriority(this, this->nice + delta); }
bool Process_sendSignal(Process* this, int sgn) {
   if (Settings_readonly) return false;
   return kill(this->pid, sgn) == 0;
}
