#define ONE_K 1024ULL
#define ONE_M (ONE_K * ONE_K)
#define ONE_G (ONE_M * ONE_K)
#define ONE_T (ONE_G * ONE_K)
#define ONE_P (ONE_T * ONE_K)
#define ONE_DECIMAL_K 1000ULL
#define ONE_DECIMAL_M (ONE_DECIMAL_K * ONE_DECIMAL_K)
#define ONE_DECIMAL_G (ONE_DECIMAL_M * ONE_DECIMAL_K)
#define ONE_DECIMAL_T (ONE_DECIMAL_G * ONE_DECIMAL_K)

static const char* kthreadID = "KTHREAD";

bool Process_isThread(const Process* p) { return p->isUserlandThread || p->isKernelThread; }
int Process_getGroupOrParent(const Process* p) { return p->tgid == p->pid ? p->ppid : p->tgid; }

void Process_printKBytes(RStr* str, unsigned long long number, bool coloring) {
   char buffer[32];
   int len;
   int largeNumberColor = coloring ? CRT_colors[LARGE_NUMBER] : CRT_colors[PROCESS];
   int megabytesColor = coloring ? CRT_colors[PROCESS_MEGABYTES] : CRT_colors[PROCESS];
   int gigabytesColor = coloring ? CRT_colors[PROCESS_GIGABYTES] : CRT_colors[PROCESS];
   int processColor = CRT_colors[PROCESS];
   if (number == ULLONG_MAX) {
      rs_append(str, CRT_colors[PROCESS_SHADOW], "  N/A ");
      return;
   }
   if (number < 1000) {
      len = xsnprintf(buffer, sizeof(buffer), "%5llu ", number);
      rs_appendn(str, processColor, buffer, len);
   } else if (number < 100000) {
      len = xsnprintf(buffer, sizeof(buffer), "%2llu", number / 1000);
      rs_appendn(str, megabytesColor, buffer, len);
      number %= 1000;
      len = xsnprintf(buffer, sizeof(buffer), "%03llu ", number);
      rs_appendn(str, processColor, buffer, len);
   } else if (number < 1000 * ONE_K) {
      number /= ONE_K;
      len = xsnprintf(buffer, sizeof(buffer), "%4lluM ", number);
      rs_appendn(str, megabytesColor, buffer, len);
   } else if (number < 10000 * ONE_K) {
      number /= ONE_K;
      len = xsnprintf(buffer, sizeof(buffer), "%1llu", number / 1000);
      rs_appendn(str, gigabytesColor, buffer, len);
      number %= 1000;
      len = xsnprintf(buffer, sizeof(buffer), "%03lluM ", number);
      rs_appendn(str, megabytesColor, buffer, len);
   } else if (number < 100000 * ONE_K) {
      number /= 100 * ONE_K;
      len = xsnprintf(buffer, sizeof(buffer), "%2llu", number / 10);
      rs_appendn(str, gigabytesColor, buffer, len);
      number %= 10;
      len = xsnprintf(buffer, sizeof(buffer), ".%1llu", number);
      rs_appendn(str, megabytesColor, buffer, len);
      rs_append(str, gigabytesColor, "G ");
   } else if (number < 1000 * ONE_M) {
      number /= ONE_M;
      len = xsnprintf(buffer, sizeof(buffer), "%4lluG ", number);
      rs_appendn(str, gigabytesColor, buffer, len);
   } else if (number < 10000ULL * ONE_M) {
      number /= ONE_M;
      len = xsnprintf(buffer, sizeof(buffer), "%1llu", number / 1000);
      rs_appendn(str, largeNumberColor, buffer, len);
      number %= 1000;
      len = xsnprintf(buffer, sizeof(buffer), "%03lluG ", number);
      rs_appendn(str, gigabytesColor, buffer, len);
   } else if (number < 100000 * ONE_M) {
      number /= 100 * ONE_M;
      len = xsnprintf(buffer, sizeof(buffer), "%2llu", number / 10);
      rs_appendn(str, largeNumberColor, buffer, len);
      number %= 10;
      len = xsnprintf(buffer, sizeof(buffer), ".%1llu", number);
      rs_appendn(str, gigabytesColor, buffer, len);
      rs_append(str, largeNumberColor, "T ");
   } else if (number < 10000ULL * ONE_G) {
      number /= ONE_G;
      len = xsnprintf(buffer, sizeof(buffer), "%4lluT ", number);
      rs_appendn(str, largeNumberColor, buffer, len);
   } else {
      len = xsnprintf(buffer, sizeof(buffer), "%4.1lfP ", (double)number / ONE_T);
      rs_appendn(str, largeNumberColor, buffer, len);
   }
}

static void printBytes(RStr* str, unsigned long long number, bool coloring) {
   if (number == ULLONG_MAX) Process_printKBytes(str, ULLONG_MAX, coloring);
   else Process_printKBytes(str, number / ONE_K, coloring);
}

void Process_printCount(RStr* str, unsigned long long number, bool coloring) {
   char buffer[16];
   int largeNumberColor = coloring ? CRT_colors[LARGE_NUMBER] : CRT_colors[PROCESS];
   int megabytesColor = coloring ? CRT_colors[PROCESS_MEGABYTES] : CRT_colors[PROCESS];
   int shadowColor = coloring ? CRT_colors[PROCESS_SHADOW] : CRT_colors[PROCESS];
   int baseColor = CRT_colors[PROCESS];
   if (number == ULLONG_MAX) {
      int len = xsnprintf(buffer, sizeof(buffer), "        N/A ");
      rs_appendn(str, CRT_colors[PROCESS_SHADOW], buffer, len);
   } else if (number >= 100000LL * ONE_DECIMAL_T) {
      int len = xsnprintf(buffer, sizeof(buffer), "%11llu ", number / ONE_DECIMAL_G);
      rs_appendn(str, largeNumberColor, buffer, len);
   } else if (number >= 100LL * ONE_DECIMAL_T) {
      xsnprintf(buffer, sizeof(buffer), "%11llu ", number / ONE_DECIMAL_M);
      rs_appendn(str, largeNumberColor, buffer, 8);
      rs_appendn(str, megabytesColor, buffer + 8, 4);
   } else if (number >= 10LL * ONE_DECIMAL_G) {
      xsnprintf(buffer, sizeof(buffer), "%11llu ", number / ONE_DECIMAL_K);
      rs_appendn(str, largeNumberColor, buffer, 5);
      rs_appendn(str, megabytesColor, buffer + 5, 3);
      rs_appendn(str, baseColor, buffer + 8, 4);
   } else {
      xsnprintf(buffer, sizeof(buffer), "%11llu ", number);
      rs_appendn(str, largeNumberColor, buffer, 2);
      rs_appendn(str, megabytesColor, buffer + 2, 3);
      rs_appendn(str, baseColor, buffer + 5, 3);
      rs_appendn(str, shadowColor, buffer + 8, 4);
   }
}

void Process_printTime(RStr* str, unsigned long long totalHundredths, bool coloring) {
   char buffer[16];
   int len;
   int yearColor = CRT_colors[LARGE_NUMBER];
   int dayColor = CRT_colors[PROCESS_GIGABYTES];
   int hourColor = CRT_colors[PROCESS_MEGABYTES];
   int baseColor = CRT_colors[PROCESS];
   if (!coloring) yearColor = dayColor = hourColor = CRT_colors[PROCESS];
   if (totalHundredths == 0) {
      rs_append(str, CRT_colors[PROCESS_SHADOW], " 0:00.00 ");
      return;
   }
   unsigned long long totalSeconds = totalHundredths / 100;
   unsigned long long totalMinutes = totalSeconds / 60;
   unsigned long long totalHours = totalMinutes / 60;
   unsigned int seconds = totalSeconds % 60;
   unsigned int minutes = totalMinutes % 60;
   if (totalMinutes < 60) {
      unsigned int hundredths = totalHundredths % 100;
      len = xsnprintf(buffer, sizeof(buffer), "%2u:%02u.%02u ", (unsigned int)totalMinutes, seconds, hundredths);
      rs_appendn(str, baseColor, buffer, len);
      return;
   }
   if (totalHours < 24) {
      len = xsnprintf(buffer, sizeof(buffer), "%2uh", (unsigned int)totalHours);
      rs_appendn(str, hourColor, buffer, len);
      len = xsnprintf(buffer, sizeof(buffer), "%02u:%02u ", minutes, seconds);
      rs_appendn(str, baseColor, buffer, len);
      return;
   }
   unsigned long long totalDays = totalHours / 24;
   unsigned int hours = totalHours % 24;
   if (totalDays < 10) {
      len = xsnprintf(buffer, sizeof(buffer), "%1ud", (unsigned int)totalDays);
      rs_appendn(str, dayColor, buffer, len);
      len = xsnprintf(buffer, sizeof(buffer), "%02uh", hours);
      rs_appendn(str, hourColor, buffer, len);
      len = xsnprintf(buffer, sizeof(buffer), "%02um ", minutes);
      rs_appendn(str, baseColor, buffer, len);
      return;
   }
   if (totalDays < 365) {
      len = xsnprintf(buffer, sizeof(buffer), "%4ud", (unsigned int)totalDays);
      rs_appendn(str, dayColor, buffer, len);
      len = xsnprintf(buffer, sizeof(buffer), "%02uh ", hours);
      rs_appendn(str, hourColor, buffer, len);
      return;
   }
   unsigned long long totalYears = totalDays / 365;
   totalDays %= 365;
   if (totalYears < 1000) {
      len = xsnprintf(buffer, sizeof(buffer), "%3lluy", totalYears);
      rs_appendn(str, yearColor, buffer, len);
      len = xsnprintf(buffer, sizeof(buffer), "%03ud ", (unsigned int)totalDays);
      rs_appendn(str, dayColor, buffer, len);
   } else if (totalYears < 10000000) {
      len = xsnprintf(buffer, sizeof(buffer), "%7lluy ", totalYears);
      rs_appendn(str, yearColor, buffer, len);
   } else {
      rs_append(str, yearColor, "eternity ");
   }
}

static void printRate(RStr* str, double rate, bool coloring) {
   char buffer[32];
   int largeNumberColor = CRT_colors[LARGE_NUMBER];
   int megabytesColor = CRT_colors[PROCESS_MEGABYTES];
   int shadowColor = CRT_colors[PROCESS_SHADOW];
   int processColor = CRT_colors[PROCESS];
   if (!coloring) { largeNumberColor = CRT_colors[PROCESS]; megabytesColor = CRT_colors[PROCESS]; }
   int len;
   if (isnan(rate) || rate < 0) {
      len = xsnprintf(buffer, sizeof(buffer), "        N/A ");
      rs_appendn(str, shadowColor, buffer, len);
   } else if (rate < 0.005) {
      len = xsnprintf(buffer, sizeof(buffer), "%7.2f B/s ", rate);
      rs_appendn(str, shadowColor, buffer, len);
   } else if (rate < ONE_K) {
      len = xsnprintf(buffer, sizeof(buffer), "%7.2f B/s ", rate);
      rs_appendn(str, processColor, buffer, len);
   } else if (rate < ONE_M) {
      len = xsnprintf(buffer, sizeof(buffer), "%7.2f K/s ", rate / ONE_K);
      rs_appendn(str, processColor, buffer, len);
   } else if (rate < ONE_G) {
      len = xsnprintf(buffer, sizeof(buffer), "%7.2f M/s ", rate / ONE_M);
      rs_appendn(str, megabytesColor, buffer, len);
   } else if (rate < ONE_T) {
      len = xsnprintf(buffer, sizeof(buffer), "%7.2f G/s ", rate / ONE_G);
      rs_appendn(str, largeNumberColor, buffer, len);
   } else if (rate < ONE_P) {
      len = xsnprintf(buffer, sizeof(buffer), "%7.2f T/s ", rate / ONE_T);
      rs_appendn(str, largeNumberColor, buffer, len);
   } else {
      len = xsnprintf(buffer, sizeof(buffer), "%7.2f P/s ", rate / ONE_P);
      rs_appendn(str, largeNumberColor, buffer, len);
   }
}

static void printPercentage(float val, char* buffer, size_t n, int width, int* attr) {
   if (!isnan(val) && val >= 0) {
      if (val < 0.05F) *attr = CRT_colors[PROCESS_SHADOW];
      else if (val >= 99.9F) *attr = CRT_colors[PROCESS_MEGABYTES];
      int precision = 1;
      if (width == 4 && val > 99.9F) { precision = 0; val = 100.0F; }
      xsnprintf(buffer, n, "%*.*f ", width, precision, val);
   } else {
      *attr = CRT_colors[PROCESS_SHADOW];
      xsnprintf(buffer, n, "%*.*s ", width, width, "N/A");
   }
}

static void printLeftAligned(RStr* str, int attr, const char* content, int width) {
