static void buildTreeBranch(Machine* this, int rowid, unsigned int level, int32_t indent, bool show) {
   if (rowid == 0) return;
   int vsize = this->rows->size;
   int l = 0, r = vsize;
   while (l < r) {
      int c = (l + r) / 2;
      Process* p = this->rows->items[c];
      int parent = p->isRoot ? 0 : Process_getGroupOrParent(p);
      if (parent < rowid) l = c + 1;
      else r = c;
   }
   int lastShown = r;
   while (r < vsize) {
      Process* p = this->rows->items[r];
      if (p->isRoot || !isChildOf(p, rowid)) break;
      if (p->show) lastShown = r;
      r++;
   }
   for (int i = l; i < r; i++) {
      Process* p = this->rows->items[i];
      if (!show) p->show = false;
      vec_push(this->displayList, p);
      int shift = MINI(level, (int)(sizeof(p->indent) * 8 - 2));
      int32_t nextIndent = indent | ((int32_t)1 << shift);
      buildTreeBranch(this, p->pid, level + 1, (i < lastShown) ? nextIndent : indent, p->show && p->showChildren);
      if (i == lastShown) p->indent = -nextIndent;
      else p->indent = nextIndent;
      p->tree_depth = level + 1;
   }
}

static int compareByParent(const void* v1, const void* v2) {
   const Process* p1 = v1;
   const Process* p2 = v2;
   int a = p1->isRoot ? 0 : Process_getGroupOrParent(p1);
   int b = p2->isRoot ? 0 : Process_getGroupOrParent(p2);
   int r = (a > b) - (a < b);
   if (r) return r;
   return Process_compare(v1, v2);
}

static void buildTree(Machine* this) {
   vec_clear(this->displayList);
   int vsize = this->rows->size;
   for (int i = 0; i < vsize; i++) {
      Process* p = this->rows->items[i];
      int parent = Process_getGroupOrParent(p);
      p->isRoot = false;
      if (p->pid == parent) { p->isRoot = true; continue; }
      if (!parent) { p->isRoot = true; continue; }
      if (!findById(this, parent)) { p->isRoot = true; continue; }
   }
   vec_sort(this->rows, compareByParent);
   for (int i = 0; i < vsize; i++) {
      Process* p = this->rows->items[i];
      if (p->isRoot) {
         p->indent = 0;
         p->tree_depth = 0;
         vec_push(this->displayList, p);
         buildTreeBranch(this, p->pid, 0, 0, p->showChildren);
      }
   }
   this->needsSort = false;
}

void Machine_updateDisplayList(Machine* this) {
   const Settings* settings = this->settings;
   if (settings->ss->treeView) {
      if (this->needsSort) buildTree(this);
   } else {
      if (this->needsSort) vec_isort(this->rows, Process_compare);
      vec_clear(this->displayList);
      for (int i = 0; i < this->rows->size; i++) vec_push(this->displayList, this->rows->items[i]);
   }
   this->needsSort = false;
}

static bool containsMulti(const char* hay, const char* needle) {
   if (!hay) hay = "";
   if (!strchr(needle, '|')) return strcasestr(hay, needle) != NULL;
   char* copy = xstrdup(needle);
   char* save = NULL;
   bool found = false;
   for (char* tok = strtok_r(copy, "|", &save); tok; tok = strtok_r(NULL, "|", &save)) {
      if (strcasestr(hay, tok)) { found = true; break; }
   }
   free(copy);
   return found;
}

static bool filteredOut(const Machine* this, const Process* p) {
   if (this->userId != (uid_t)-1 && p->st_uid != this->userId) return true;
   if (this->incFilter && !containsMulti(Process_getCommand(p), this->incFilter)) return true;
   if (this->pidMatchList && !Machine_isInPidList(this, p->tgid)) return true;
   return false;
}

