   Machine_updateDisplayList(this);
   Panel* panel = this->panel;
   int currPos = panel->selected;
   int currScrollV = panel->scrollV;
   int currSize = panel->items->size;
   bool ownsSave = panel->ownsItems;
   panel->ownsItems = false;
   Panel_prune(panel);
   panel->ownsItems = ownsSave;

   int rowCount = this->displayList->size;
   bool foundFollowed = false;
   int idx = 0;
   for (int i = 0; i < rowCount; i++) {
