/* ---------- cgroup name shortening ---------- */
static bool isSuffix(const char* s, size_t len, const char* suf) {
   size_t l = strlen(suf);
   return len >= l && strncmp(s + len - l, suf, l) == 0;
}

char* CGroup_filterName(const char* cgroup) {
   /* Port of the condensing rules described in the manual */
   size_t cap = strlen(cgroup) + 16;
   char* out = xcalloc(cap, 1);
   size_t olen = 0;
   const char* str = cgroup;
   while (*str) {
      if (*str == ';') {
         out[olen++] = ';';
         str++;
         continue;
      }
      if (*str != '/') {
         /* copy controller prefix etc. */
         const char* next = str;
         while (*next && *next != '/' && *next != ';') next++;
         memcpy(out + olen, str, next - str);
         olen += next - str;
         str = next;
         continue;
      }
      /* segment */
      const char* segStart = str + 1;
      const char* segEnd = segStart;
      while (*segEnd && *segEnd != '/' && *segEnd != ';') segEnd++;
      size_t segLen = segEnd - segStart;
      char seg[4096];
      if (segLen >= sizeof(seg)) segLen = sizeof(seg) - 1;
      memcpy(seg, segStart, segLen);
      seg[segLen] = 0;
      char repl[4200];
      if (str_eq(seg, "system.slice")) {
         snprintf(repl, sizeof(repl), "/[S]");
      } else if (str_eq(seg, "user.slice")) {
         snprintf(repl, sizeof(repl), "/[U]");
      } else if (str_starts(seg, "user-") && isSuffix(seg, segLen, ".slice")) {
         /* drop directly preceding /[U] */
         if (olen >= 4 && strncmp(out + olen - 4, "/[U]", 4) == 0) olen -= 4;
         snprintf(repl, sizeof(repl), "/[U:%.*s]", (int)(segLen - 5 - 6), seg + 5);
      } else if (str_eq(seg, "machine.slice")) {
         snprintf(repl, sizeof(repl), "/[M]");
      } else if (str_starts(seg, "machine-") && isSuffix(seg, segLen, ".scope")) {
         snprintf(repl, sizeof(repl), "/[SNC:%.*s]", (int)(segLen - 8 - 6), seg + 8);
      } else if (str_starts(seg, "lxc.monitor.")) {
         snprintf(repl, sizeof(repl), "/[LXC:%s]", seg + 12);
      } else if (str_starts(seg, "lxc.payload.")) {
         snprintf(repl, sizeof(repl), "/[lxc:%s]", seg + 12);
      } else if (isSuffix(seg, segLen, ".slice")) {
         snprintf(repl, sizeof(repl), "/[%.*s]", (int)(segLen - 6), seg);
      } else if (isSuffix(seg, segLen, ".scope")) {
         snprintf(repl, sizeof(repl), "/!%.*s", (int)(segLen - 6), seg);
      } else if (isSuffix(seg, segLen, ".service")) {
         snprintf(repl, sizeof(repl), "/%.*s", (int)(segLen - 8), seg);
      } else {
         snprintf(repl, sizeof(repl), "/%s", seg);
      }
      size_t rl = strlen(repl);
      if (olen + rl + 2 > cap) { cap = (olen + rl) * 2 + 16; out = xrealloc(out, cap); }
      memcpy(out + olen, repl, rl);
      olen += rl;
      str = segEnd;
   }
   out[olen] = 0;
   return out;
}

char* CGroup_filterContainer(const char* cgroup) {
   (void)cgroup;
   return xstrdup("/");
}
