#define GRAPH_HEIGHT 4
static const char unitPrefixes[] = { 'K', 'M', 'G', 'T', 'P', 'E', 'Z', 'Y', 'R', 'Q' };

const char* const Meter_modeNames[] = { "", "Bar", "Text", "Graph", "LED" };

int Meter_humanUnit(char* buffer, double value, size_t size) {
   size_t i = 0;
   if (value < 0 || isnan(value)) value = 0;
   while (value >= 1024) {
      if (i >= ARRLEN(unitPrefixes) - 1) {
         if (value > 9999.0) return xsnprintf(buffer, size, "inf");
         break;
      }
      value /= 1024;
      ++i;
   }
   int precision = 0;
   if (i > 0) {
      precision = value <= 99.9 ? (value <= 9.99 ? 2 : 1) : 0;
      if (precision < 2) {
         double limit = precision == 1 ? 10.0 : 100.0;
         if (value < limit) value = limit;
      }
   }
   return xsnprintf(buffer, size, "%.*f%c", precision, value, unitPrefixes[i]);
}

static double sumPositive(const double* v, int n) {
   double s = 0;
   for (int i = 0; i < n; i++) if (v[i] > 0 && !isnan(v[i])) s += v[i];
   return s;
}

static const char* Meter_getCaption(const Meter* this) { return this->caption ? this->caption : this->cls->caption; }

