static void Meter_displayBuffer(const Meter* this, RStr* out) {
   if (this->cls->display) {
      this->cls->display(this, out);
   } else {
      rs_append(out, CRT_colors[Meter_attrs(this)[0]], this->txtBuffer);
   }
