/* ---------------- draw modes ---------------- */
static const char BarMeterMode_characters[] = "|#*@$%&.";

static void BarMeterMode_draw(Meter* this, int x, int y, int w) {
   const char* caption = Meter_getCaption(this);
   attrset(CRT_colors[METER_TEXT]);
   int captionLen = 3;
   mvaddnstr(y, x, caption, captionLen);
   x += captionLen;
   w -= captionLen;
   attrset(CRT_colors[BAR_BORDER]);
   mvaddch(y, x, '[');
   w--;
   mvaddch(y, x + MAXI(w, 0), ']');
   w--;
   attrset(CRT_colors[RESET_COLOR]);
   x++;
   if (w < 1) return;

   RStr bar; rs_init(&bar);
   rs_appendChr(&bar, 0, ' ', w);
   rs_append(&bar, 0, this->txtBuffer);
   int startPos = bar.len - w;
   if (startPos > w) {
      for (int pos = 2 * w; pos > w; pos--) {
         if (pos < bar.len && rs_getChar(&bar, pos) == ' ') {
            while (pos > w && rs_getChar(&bar, pos - 1) == ' ') pos--;
            startPos = pos - w;
            break;
         }
      }
      startPos = MINI(startPos, w);
   }
   int blockSizes[16];
   int offset = 0;
   const int* attrs = Meter_attrs(this);
   for (int i = 0; i < this->curItems && i < 16; i++) {
      double value = this->values[i];
      if (value > 0 && !isnan(value) && this->total > 0.0) {
         value = MINI(value, this->total);
         blockSizes[i] = (int)ceil((value / this->total) * w);
         blockSizes[i] = MINI(blockSizes[i], w - offset);
      } else {
         blockSizes[i] = 0;
      }
      int nextOffset = offset + blockSizes[i];
      for (int j = offset; j < nextOffset; j++) {
         if (rs_getChar(&bar, startPos + j) == ' ') {
            if (CRT_colorScheme == COLORSCHEME_MONOCHROME) rs_setChar(&bar, startPos + j, BarMeterMode_characters[i]);
            else rs_setChar(&bar, startPos + j, '|');
         }
      }
      offset = nextOffset;
   }
   offset = 0;
   for (int i = 0; i < this->curItems && i < 16; i++) {
      int attr = attrs[i];
      rs_setAttrn(&bar, CRT_colors[attr], startPos + offset, blockSizes[i]);
      rs_print(&bar, y, x + offset, startPos + offset, blockSizes[i]);
      offset += blockSizes[i];
   }
   if (offset < w) {
      rs_setAttrn(&bar, CRT_colors[BAR_SHADOW], startPos + offset, w - offset);
      rs_print(&bar, y, x + offset, startPos + offset, w - offset);
   }
   rs_free(&bar);
   move(y, x + w + 1);
   attrset(CRT_colors[RESET_COLOR]);
}

static const char* const GraphMeterMode_dotsAscii[] = {
   /*00*/" ", /*01*/".", /*02*/":",
   /*10*/".", /*11*/".", /*12*/":",
   /*20*/":", /*21*/":", /*22*/":"
};

static void GraphMeterMode_draw(Meter* this, int x, int y, int w) {
   const char* caption = Meter_getCaption(this);
   attrset(CRT_colors[METER_TEXT]);
   int captionLen = 3;
   mvaddnstr(y, x, caption, captionLen);
   x += captionLen;
   w -= captionLen;
   GraphData* data = &this->drawData;
   int h = this->h;
   const int pixPerRow = 2;
   if ((size_t)MAXI(w, 0) * 2 > data->nValues && 32768 > data->nValues) {
      size_t oldN = data->nValues;
      size_t newN = MAXI(oldN + oldN / 2, (size_t)w * 2);
      newN = MINI(newN, (size_t)32768);
      data->values = xrealloc(data->values, newN * sizeof(double));
      memmove(data->values + (newN - oldN), data->values, oldN * sizeof(double));
      for (size_t i = 0; i < newN - oldN; i++) data->values[i] = 0;
      data->nValues = newN;
   }
   size_t nValues = data->nValues;
   if (nValues < 1) return;
   const Machine* host = this->host;
   if (!timercmp(&host->realtime, &data->time, <)) {
      int gd = host->settings->delay;
      struct timeval delay = { .tv_sec = gd / 10, .tv_usec = (gd % 10) * 100000L };
      timeradd(&host->realtime, &delay, &data->time);
      memmove(&data->values[0], &data->values[1], (nValues - 1) * sizeof(double));
      data->values[nValues - 1] = sumPositive(this->values, this->curItems);
   }
   if (w <= 0) return;
   if ((size_t)w > nValues / 2) {
      x += w - nValues / 2;
      w = nValues / 2;
   }
   double total = this->total;
   if (this->cls->dynamicGraphScale) {
      total = 0;
      for (size_t i = nValues - (size_t)w * 2; i < nValues; i++) if (data->values[i] > total) total = data->values[i];
   }
   if (!(total > 0)) total = 1;
   size_t i = nValues - (size_t)w * 2;
   for (int col = 0; i < nValues - 1; i += 2, col++) {
      int pix = pixPerRow * h;
      double a = data->values[i] / total; if (isnan(a) || a < 0) a = 0; if (a > 1) a = 1;
      double b = data->values[i + 1] / total; if (isnan(b) || b < 0) b = 0; if (b > 1) b = 1;
      int v1 = (int)lround(a * pix);
      int v2 = (int)lround(b * pix);
      if (v1 < 1) v1 = 1;
      if (v2 < 1) v2 = 1;
      int colorIdx = GRAPH_1;
      for (int line = 0; line < h; line++) {
         int line1 = CLAMPI(v1 - (pixPerRow * (h - 1 - line)), 0, pixPerRow);
         int line2 = CLAMPI(v2 - (pixPerRow * (h - 1 - line)), 0, pixPerRow);
         attrset(CRT_colors[colorIdx]);
         mvaddstr(y + line, x + col, GraphMeterMode_dotsAscii[line1 * (pixPerRow + 1) + line2]);
         colorIdx = GRAPH_2;
      }
   }
   attrset(CRT_colors[RESET_COLOR]);
}

