static void AllCPUsMeter_getRange(const Meter* this, unsigned int* start, unsigned int* count) {
   const CPUMeterData* data = this->meterData;
   unsigned int cpus = data->cpus;
   switch (this->cls->name[0]) {
   default:
   case 'A': *start = 0; *count = cpus; break;
   case 'L': *start = 0; *count = (cpus + 1) / 2; break;
   case 'R': *start = (cpus + 1) / 2; *count = cpus - *start; break;
   }
}

static int AllCPUsMeter_cols(const Meter* this) {
   const char* n = this->cls->name;
   size_t l = strlen(n);
   char last = n[l - 1];
   if (last == '2') return 2;
   if (last == '4') return 4;
   if (last == '8') return 8;
   return 1;
}

static void AllCPUsMeter_updateValues(Meter* this) {
   CPUMeterData* data = this->meterData;
   unsigned int start, count;
   AllCPUsMeter_getRange(this, &start, &count);
   for (unsigned int i = 0; i < count; i++) Meter_updateValues(data->meters[i]);
}

static void AllCPUsMeter_updateMode(Meter* this, int mode) {
   CPUMeterData* data = this->meterData;
   this->mode = mode;
   unsigned int start, count;
   AllCPUsMeter_getRange(this, &start, &count);
   for (unsigned int i = 0; i < count; i++) Meter_setMode(data->meters[i], mode);
   int ncol = AllCPUsMeter_cols(this);
   int h = Meter_modes[mode].h;
   this->h = h * (int)((count + ncol - 1) / ncol);
}

static void CPUMeterCommonInit(Meter* this) {
   unsigned int cpus = this->host->existingCPUs;
   CPUMeterData* data = this->meterData;
   if (!data) {
      data = this->meterData = xcalloc(1, sizeof(CPUMeterData));
      data->cpus = cpus;
      data->meters = xcalloc(cpus, sizeof(Meter*));
   }
   Meter** meters = data->meters;
   unsigned int start, count;
   AllCPUsMeter_getRange(this, &start, &count);
   for (unsigned int i = 0; i < count; i++) {
      if (!meters[i]) meters[i] = Meter_new(this->host, start + i + 1, &CPUMeter_class);
      CPUMeter_init(meters[i]);
   }
   if (this->mode <= 0) this->mode = BAR_METERMODE;
   int ncol = AllCPUsMeter_cols(this);
   int h = Meter_modes[this->mode].h;
   this->h = h * (int)((count + ncol - 1) / ncol);
}

static void AllCPUsMeter_done(Meter* this) {
   CPUMeterData* data = this->meterData;
   if (!data) return;
   unsigned int start, count;
   AllCPUsMeter_getRange(this, &start, &count);
   for (unsigned int i = 0; i < count; i++) Meter_delete(data->meters[i]);
   free(data->meters);
   free(data);
   this->meterData = NULL;
}

static void CPUMeterCommonDraw(Meter* this, int x, int y, int w, int ncol) {
   CPUMeterData* data = this->meterData;
   Meter** meters = data->meters;
   unsigned int start, count;
   AllCPUsMeter_getRange(this, &start, &count);
   int colwidth = w / ncol;
   int diff = w % ncol;
   unsigned int nrows = (count + ncol - 1) / ncol;
   for (int i = 0; i < ncol; i++) {
      int d = (i < diff) ? 1 : 0;
      for (unsigned int j = 0; j < nrows; j++) {
         unsigned int m = i * nrows + j;
         if (m >= count) break;
         Meter_draw(meters[m], x, y + j * meters[m]->h, colwidth);
      }
      x += colwidth + d;
   }
}

static void AllCPUsMeter_draw(Meter* this, int x, int y, int w) {
   int ncol = AllCPUsMeter_cols(this);
   if (ncol == 1) {
      CPUMeterData* data = this->meterData;
      unsigned int start, count;
      AllCPUsMeter_getRange(this, &start, &count);
      for (unsigned int i = 0; i < count; i++) {
         Meter_draw(data->meters[i], x, y, w);
         y += data->meters[i]->h;
      }
   } else {
      CPUMeterCommonDraw(this, x, y, w, ncol);
   }
}

