   .defaultMode = CUSTOM_METERMODE, .maxItems = 0, .total = 100.0, .attributes = MemoryMeter_attributes, .isMultiColumn = true,
   .init = MemorySwapMeter_init, .done = MemorySwapMeter_done, .updateMode = MemorySwapMeter_updateMode,
   .updateValues = MemorySwapMeter_updateValues, .draw = MemorySwapMeter_draw,
};

/* ---- System ---- */
static const int SysArchMeter_attributes[] = { HOSTNAME };
static char* sysarchString;
static void SysArchMeter_updateValues(Meter* this) {
   if (!sysarchString) {
      struct utsname uts;
      char distro[256] = "";
      if (uname(&uts) != 0) memset(&uts, 0, sizeof(uts));
      FILE* f = fopen("/etc/os-release", "r");
      if (!f) f = fopen("/usr/lib/os-release", "r");
      if (f) {
         char line[512];
         while (fgets(line, sizeof(line), f)) {
            if (str_starts(line, "PRETTY_NAME=")) {
               char* v = line + 12;
               size_t l = strlen(v);
               while (l > 0 && (v[l-1] == '\n' || v[l-1] == '\r')) v[--l] = 0;
               if (l >= 2 && (v[0] == '"' || v[0] == '\'') && v[l-1] == v[0]) { v[l-1] = 0; v++; }
               snprintf(distro, sizeof(distro), "%s", v);
               break;
            }
         }
         fclose(f);
      }
      if (distro[0]) sysarchString = xasprintf("%s %s [%s] @ %s", uts.sysname, uts.release, uts.machine, distro);
      else sysarchString = xasprintf("%s %s [%s]", uts.sysname, uts.release, uts.machine);
   }
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%s", sysarchString);
}
