/* ---- Uptime ---- */
static int getUptime(void) {
   char buf[128];
   if (readFileBuf("/proc/uptime", buf, sizeof(buf)) <= 0) return 0;
   double up = 0;
   sscanf(buf, "%lf", &up);
   return (int)floor(up);
}
static const int UptimeMeter_attributes[] = { UPTIME };
static void UptimeMeter_updateValues(Meter* this) {
   int totalseconds = getUptime();
   if (totalseconds <= 0) { xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "(unknown)"); return; }
   int seconds = totalseconds % 60;
   int minutes = (totalseconds / 60) % 60;
   int hours = (totalseconds / 3600) % 24;
   int days = (totalseconds / 86400);
   this->values[0] = days;
   if (days > this->total) this->total = days;
   char daysbuf[32];
   if (days > 100) xsnprintf(daysbuf, sizeof(daysbuf), "%d days(!), ", days);
   else if (days > 1) xsnprintf(daysbuf, sizeof(daysbuf), "%d days, ", days);
   else if (days == 1) xsnprintf(daysbuf, sizeof(daysbuf), "1 day, ");
   else daysbuf[0] = '\0';
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%s%02d:%02d:%02d", daysbuf, hours, minutes, seconds);
}
