/* ---- Battery ---- */
static const int BatteryMeter_attributes[] = { BATTERY };
static void BatteryMeter_updateValues(Meter* this) {
   double percent = NAN;
   bool ac = false, haveAC = false;
   DIR* d = opendir("/sys/class/power_supply");
   double totalFull = 0, totalRemain = 0;
   if (d) {
      struct dirent* e;
      while ((e = readdir(d))) {
         if (e->d_name[0] == '.') continue;
         char path[512], buf[256];
         snprintf(path, sizeof(path), "/sys/class/power_supply/%s/type", e->d_name);
         if (readFileBuf(path, buf, sizeof(buf)) <= 0) continue;
         if (str_starts(buf, "Battery")) {
            snprintf(path, sizeof(path), "/sys/class/power_supply/%s/capacity", e->d_name);
            if (readFileBuf(path, buf, sizeof(buf)) > 0) { totalRemain += atof(buf); totalFull += 100; }
         } else if (str_starts(buf, "Mains")) {
            snprintf(path, sizeof(path), "/sys/class/power_supply/%s/online", e->d_name);
            if (readFileBuf(path, buf, sizeof(buf)) > 0) { haveAC = true; if (buf[0] == '1') ac = true; }
         }
      }
      closedir(d);
   }
   if (totalFull > 0) percent = totalRemain / totalFull * 100.0;
   if (isnan(percent)) {
      this->values[0] = NAN;
      xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "N/A");
      return;
   }
   this->values[0] = percent;
   const char* src = haveAC ? (ac ? "AC" : "battery") : "?";
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%.1f%%(%s)", percent, src);
}
