static const int PressureStallMeter_attributes[] = { PRESSURE_STALL_TEN, PRESSURE_STALL_SIXTY, PRESSURE_STALL_THREEHUNDRED };
static void PressureStallMeter_updateValues(Meter* this) {
   const char* file;
   const char* nm = this->cls->name;
   bool some;
   if (strstr(nm, "CPU")) file = "cpu";
   else if (strstr(nm, "IO")) file = "io";
   else if (strstr(nm, "IRQ")) file = "irq";
   else file = "memory";
   some = strstr(nm, "Some") != NULL;
   char path[64];
   snprintf(path, sizeof(path), "/proc/pressure/%s", file);
   char buf[512];
   this->values[0] = this->values[1] = this->values[2] = 0;
   if (readFileBuf(path, buf, sizeof(buf)) > 0) {
      char* line = strstr(buf, some ? "some" : "full");
      if (line) {
         double a, b, c;
         if (sscanf(line + 4, " avg10=%lf avg60=%lf avg300=%lf", &a, &b, &c) == 3) {
            this->values[0] = a; this->values[1] = b; this->values[2] = c;
         }
      }
   }
   this->curItems = 1;
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%s %s %5.2lf%% %5.2lf%% %5.2lf%%", some ? "some" : "full", file, this->values[0], this->values[1], this->values[2]);
}
