   char buffer[32];
   int len;
   len = xsnprintf(buffer, sizeof(buffer), "%5.2lf%% ", this->values[0]);
   rs_appendn(out, CRT_colors[PRESSURE_STALL_TEN], buffer, len);
   len = xsnprintf(buffer, sizeof(buffer), "%5.2lf%% ", this->values[1]);
   rs_appendn(out, CRT_colors[PRESSURE_STALL_SIXTY], buffer, len);
   len = xsnprintf(buffer, sizeof(buffer), "%5.2lf%% ", this->values[2]);
   rs_appendn(out, CRT_colors[PRESSURE_STALL_THREEHUNDRED], buffer, len);
}
