/* ---- Disk IO ---- */
typedef struct { unsigned long long rd, wr, ms, n; uint64_t stampMs; bool valid; } DiskStat;
static DiskStat diskPrev, diskCur;
static double diskReadRate, diskWriteRate, diskBusy;
static uint64_t diskLastUpdate;
static bool readDiskStats(DiskStat* s) {
   FILE* fp = fopen("/proc/diskstats", "r");
   if (!fp) return false;
   char last[32] = "";
   unsigned long long rs = 0, ws = 0, ts = 0, n = 0;
   char line[512];
   while (fgets(line, sizeof(line), fp)) {
      char name[32];
      unsigned long long r, w, t;
      if (sscanf(line, "%*d %*d %31s %*u %*u %llu %*u %*u %*u %llu %*u %*u %llu", name, &r, &w, &t) == 4) {
         if (str_starts(name, "dm-")) continue;
         if (str_starts(name, "zram")) continue;
         if (name[0] && last[0] && str_starts(name, last)) continue;
         snprintf(last, sizeof(last), "%s", name);
         rs += r; ws += w; ts += t; n++;
      }
   }
   fclose(fp);
   s->rd = 512 * rs; s->wr = 512 * ws; s->ms = ts; s->n = n; s->valid = true;
   return true;
}
static void updateDisk(Machine* host) {
   if (diskLastUpdate == host->monotonicMs) return;
   diskLastUpdate = host->monotonicMs;
   DiskStat s;
   if (!readDiskStats(&s)) { diskCur.valid = false; return; }
   s.stampMs = host->monotonicMs;
   diskPrev = diskCur;
   diskCur = s;
   if (diskPrev.valid && diskCur.stampMs > diskPrev.stampMs) {
      double dt = (diskCur.stampMs - diskPrev.stampMs);
      diskReadRate = (diskCur.rd > diskPrev.rd ? diskCur.rd - diskPrev.rd : 0) / dt * 1000.0;
      diskWriteRate = (diskCur.wr > diskPrev.wr ? diskCur.wr - diskPrev.wr : 0) / dt * 1000.0;
      diskBusy = MINI(100.0, (diskCur.ms > diskPrev.ms ? diskCur.ms - diskPrev.ms : 0) / dt * 100.0 / MAXI(1ULL, diskCur.n));
   } else if (!diskPrev.valid) {
      diskReadRate = diskWriteRate = diskBusy = 0;
   }
}
static void humanRate(char* buf, size_t sz, double bytesPerSec) {
   char tmp[32];
   Meter_humanUnit(tmp, bytesPerSec / 1024.0, sizeof(tmp));
   xsnprintf(buf, sz, "%siB/s", tmp);
}
static const int DiskIORateMeter_attributes[] = { METER_VALUE_IOREAD, METER_VALUE_IOWRITE };
static const int DiskIOTimeMeter_attributes[] = { METER_VALUE_NOTICE };
static void DiskIORateMeter_updateValues(Meter* this) {
   updateDisk(this->host);
   this->values[0] = diskReadRate / 1024.0;
   this->values[1] = diskWriteRate / 1024.0;
   this->total = MAXI(this->total, this->values[0] + this->values[1]);
   if (this->total < 1) this->total = 1;
   char r[32], w[32];
   humanRate(r, sizeof(r), diskReadRate);
   humanRate(w, sizeof(w), diskWriteRate);
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "r:%s|w:%s", r, w);
}
