/* ---- Network IO ---- */
typedef struct { unsigned long long rxB, txB, rxP, txP; uint64_t stamp; bool valid; } NetStat;
static NetStat netPrev, netCur;
static double netRx, netTx; static unsigned long long netRxP, netTxP;
static uint64_t netLastUpdate;
static void updateNet(Machine* host) {
   if (netLastUpdate == host->monotonicMs) return;
   netLastUpdate = host->monotonicMs;
   FILE* f = fopen("/proc/net/dev", "r");
   if (!f) return;
   char line[512];
   NetStat s = { 0 };
   while (fgets(line, sizeof(line), f)) {
      char* colon = strchr(line, ':');
      if (!colon) continue;
      char name[64];
      char* p = line; while (*p == ' ') p++;
      size_t l = colon - p; if (l >= sizeof(name)) l = sizeof(name) - 1;
      memcpy(name, p, l); name[l] = 0;
      if (str_eq(name, "lo")) continue;
      unsigned long long rb, rp, tb, tp;
      if (sscanf(colon + 1, "%llu %llu %*u %*u %*u %*u %*u %*u %llu %llu", &rb, &rp, &tb, &tp) == 4) {
         s.rxB += rb; s.rxP += rp; s.txB += tb; s.txP += tp;
      }
   }
   fclose(f);
   s.valid = true;
   s.stamp = host->monotonicMs;
   netPrev = netCur;
   netCur = s;
   if (netPrev.valid && netCur.stamp > netPrev.stamp) {
      double dt = netCur.stamp - netPrev.stamp;
      netRx = (netCur.rxB > netPrev.rxB ? netCur.rxB - netPrev.rxB : 0) / dt * 1000.0;
      netTx = (netCur.txB > netPrev.txB ? netCur.txB - netPrev.txB : 0) / dt * 1000.0;
      netRxP = (unsigned long long)((netCur.rxP > netPrev.rxP ? netCur.rxP - netPrev.rxP : 0) / dt * 1000.0);
      netTxP = (unsigned long long)((netCur.txP > netPrev.txP ? netCur.txP - netPrev.txP : 0) / dt * 1000.0);
   } else {
      netRx = netTx = 0; netRxP = netTxP = 0;
   }
}
static const int NetworkIOMeter_attributes[] = { METER_VALUE_IOREAD, METER_VALUE_IOWRITE };
static void NetworkIOMeter_updateValues(Meter* this) {
   updateNet(this->host);
   this->values[0] = netRx / 1024.0;
   this->values[1] = netTx / 1024.0;
   this->total = MAXI(this->total, this->values[0] + this->values[1]);
   char r[32], t[32];
   humanRate(r, sizeof(r), netRx);
   humanRate(t, sizeof(t), netTx);
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "rx:%s tx:%s (%llu/%llupps)", r, t, netRxP, netTxP);
}
static void NetworkIOMeter_display(const Meter* this, RStr* out) {
