   rs_append(out, CRT_colors[METER_VALUE_IOWRITE], t);
   xsnprintf(buf, sizeof(buf), " (%llu/%llu pps)", netRxP, netTxP);
   rs_append(out, CRT_colors[METER_TEXT], buf);
}
