void Meter_setMode(Meter* this, int modeIndex) {
   if (modeIndex == this->mode) return;
   unsigned int supported = this->cls->supportedModes ? this->cls->supportedModes : MODES_DEFAULT;
   if (modeIndex <= 0 || modeIndex >= LAST_METERMODE || !(supported & MODE_BIT(modeIndex))) return;
   if (this->cls->updateMode) {
      this->drawFn = this->cls->draw;
      this->cls->updateMode(this, modeIndex);
   } else {
      free(this->drawData.values);
      this->drawData.values = NULL;
      this->drawData.nValues = 0;
      this->drawFn = Meter_modes[modeIndex].draw;
      this->h = Meter_modes[modeIndex].h;
   }
   this->mode = modeIndex;
}

int Meter_nextSupportedMode(const Meter* this) {
   unsigned int supported = this->cls->supportedModes ? this->cls->supportedModes : MODES_DEFAULT;
   unsigned int mask = ((unsigned int)-1 << 1) << this->mode;
   unsigned int next = supported & mask;
   if (!next) next = supported;
   return __builtin_ctz(next);
}

static void Meter_itemDisplay(const Item* cast, RStr* out) {
   const Meter* this = (const Meter*)cast;
   Meter_displayBuffer(this, out);
}
const ItemClass Meter_itemClass = { Meter_itemDisplay, NULL, NULL };

Meter* Meter_new(Machine* host, unsigned int param, const MeterClass* type) {
   Meter* this = xcalloc(1, sizeof(Meter));
   this->super.cls = &Meter_itemClass;
   this->cls = type;
   this->h = 1;
   this->param = param;
   this->host = host;
   this->curItems = type->maxItems;
   this->curAttributes = NULL;
   this->values = type->maxItems ? xcalloc(type->maxItems + 4, sizeof(double)) : xcalloc(4, sizeof(double));
   this->total = type->total;
   this->caption = xstrdup(type->caption);
   if (type->init) type->init(this);
   this->mode = -1;
   Meter_setMode(this, type->defaultMode);
   return this;
}

void Meter_delete(Meter* this) {
   if (!this) return;
   if (this->cls->done) this->cls->done(this);
   free(this->drawData.values);
   free(this->caption);
   free(this->values);
   free(this);
}

void Meter_updateValues(Meter* this) {
   if (this->cls->updateValues) this->cls->updateValues(this);
}

void Meter_getUiName(const Meter* this, char* buf, size_t len) {
   if (this->cls->getUiName) this->cls->getUiName(this, buf, len);
   else xsnprintf(buf, len, "%s", this->cls->uiName);
}

void Meter_writeName(const Meter* this, char* buf, size_t len) {
   if (this->param) xsnprintf(buf, len, "%s(%u)", this->cls->name, this->param);
   else xsnprintf(buf, len, "%s", this->cls->name);
}

