/* ---- CPU ---- */
enum { CPU_METER_NICE, CPU_METER_NORMAL, CPU_METER_KERNEL, CPU_METER_IRQ, CPU_METER_SOFTIRQ, CPU_METER_STEAL, CPU_METER_GUEST, CPU_METER_IOWAIT, CPU_METER_FREQUENCY, CPU_METER_TEMPERATURE, CPU_METER_ITEMCOUNT };
static const int CPUMeter_attributes[] = { CPU_NICE, CPU_NORMAL, CPU_SYSTEM, CPU_IRQ, CPU_SOFTIRQ, CPU_STEAL, CPU_GUEST, CPU_IOWAIT };

typedef struct { unsigned int cpus; Meter** meters; } CPUMeterData;

static void CPUMeter_init(Meter* this) {
   unsigned int cpu = this->param;
   const Settings* settings = this->host->settings;
   if (cpu == 0) {
      Meter_setCaption(this, "Avg");
   } else if (this->host->activeCPUs > 1) {
      char caption[16];
      xsnprintf(caption, sizeof(caption), "%3u", Settings_cpuId(settings, cpu - 1));
      Meter_setCaption(this, caption);
   }
}

static double setCPUValues(Meter* this, unsigned int cpu) {
   const Machine* host = this->host;
   const Settings* settings = host->settings;
   const CPUData* c = &host->cpuData[cpu];
   double total = (double)(c->totalPeriod == 0 ? 1 : c->totalPeriod);
   double* v = this->values;
   if (!c->online) { this->curItems = 0; return NAN; }
   v[CPU_METER_NICE] = c->nicePeriod / total * 100.0;
   v[CPU_METER_NORMAL] = c->userPeriod / total * 100.0;
   if (settings->detailedCPUTime) {
      v[CPU_METER_KERNEL] = c->systemPeriod / total * 100.0;
      v[CPU_METER_IRQ] = c->irqPeriod / total * 100.0;
      v[CPU_METER_SOFTIRQ] = c->softIrqPeriod / total * 100.0;
      this->curItems = 5;
      v[CPU_METER_STEAL] = c->stealPeriod / total * 100.0;
      v[CPU_METER_GUEST] = c->guestPeriod / total * 100.0;
      if (settings->accountGuestInCPUMeter) this->curItems = 7;
      v[CPU_METER_IOWAIT] = c->ioWaitPeriod / total * 100.0;
   } else {
      v[CPU_METER_KERNEL] = c->systemAllPeriod / total * 100.0;
      v[CPU_METER_IRQ] = (c->stealPeriod + c->guestPeriod) / total * 100.0;
      this->curItems = 4;
   }
   double percent = sumPositive(v, this->curItems);
   percent = MINI(percent, 100.0);
   if (settings->detailedCPUTime) this->curItems = 8;
   v[CPU_METER_FREQUENCY] = c->frequency;
   v[CPU_METER_TEMPERATURE] = NAN;
   return percent;
}

static void CPUMeter_updateValues(Meter* this) {
   memset(this->values, 0, sizeof(double) * CPU_METER_ITEMCOUNT);
   const Machine* host = this->host;
   const Settings* settings = host->settings;
   unsigned int cpu = this->param;
   if (cpu > host->existingCPUs) {
      xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "absent");
      return;
   }
   double percent = setCPUValues(this, cpu);
   if (isnan(percent)) {
      xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "offline");
      return;
   }
   char usage[16] = { 0 }, freq[24] = { 0 };
   if (settings->showCPUUsage) xsnprintf(usage, sizeof(usage), "%.1f%%", percent);
   if (settings->showCPUFrequency) {
      double f = this->values[CPU_METER_FREQUENCY];
      if (!isnan(f) && f >= 0) xsnprintf(freq, sizeof(freq), "%4uMHz", (unsigned)f);
      else xsnprintf(freq, sizeof(freq), "N/A");
   }
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%s%s%s", usage, (usage[0] && freq[0]) ? " " : "", freq);
}

static void CPUMeter_display(const Meter* this, RStr* out) {
   char buffer[50];
   int len;
   const Settings* settings = this->host->settings;
   if (this->param > this->host->existingCPUs) {
      rs_append(out, CRT_colors[METER_SHADOW], " absent");
      return;
   }
   if (this->curItems == 0) {
      rs_append(out, CRT_colors[METER_SHADOW], " offline");
      return;
   }
   len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[CPU_METER_NORMAL]);
   rs_append(out, CRT_colors[METER_TEXT], ":");
   rs_appendn(out, CRT_colors[CPU_NORMAL], buffer, len);
   if (settings->detailedCPUTime) {
      len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[CPU_METER_KERNEL]);
      rs_append(out, CRT_colors[METER_TEXT], "sy:");
      rs_appendn(out, CRT_colors[CPU_SYSTEM], buffer, len);
      len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[CPU_METER_NICE]);
      rs_append(out, CRT_colors[METER_TEXT], "ni:");
      rs_appendn(out, CRT_colors[CPU_NICE_TEXT], buffer, len);
      len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[CPU_METER_IRQ]);
      rs_append(out, CRT_colors[METER_TEXT], "hi:");
      rs_appendn(out, CRT_colors[CPU_IRQ], buffer, len);
      len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[CPU_METER_SOFTIRQ]);
      rs_append(out, CRT_colors[METER_TEXT], "si:");
      rs_appendn(out, CRT_colors[CPU_SOFTIRQ], buffer, len);
      if (this->values[CPU_METER_STEAL] >= 0) {
         len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[CPU_METER_STEAL]);
         rs_append(out, CRT_colors[METER_TEXT], "st:");
         rs_appendn(out, CRT_colors[CPU_STEAL], buffer, len);
      }
      if (this->values[CPU_METER_GUEST] >= 0) {
         len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[CPU_METER_GUEST]);
         rs_append(out, CRT_colors[METER_TEXT], "gu:");
         rs_appendn(out, CRT_colors[CPU_GUEST], buffer, len);
      }
      len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[CPU_METER_IOWAIT]);
      rs_append(out, CRT_colors[METER_TEXT], "wa:");
      rs_appendn(out, CRT_colors[CPU_IOWAIT], buffer, len);
   } else {
      len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[CPU_METER_KERNEL]);
      rs_append(out, CRT_colors[METER_TEXT], "sys:");
      rs_appendn(out, CRT_colors[CPU_SYSTEM], buffer, len);
      len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[CPU_METER_NICE]);
      rs_append(out, CRT_colors[METER_TEXT], "low:");
      rs_appendn(out, CRT_colors[CPU_NICE_TEXT], buffer, len);
      if (this->values[CPU_METER_IRQ] >= 0) {
         len = xsnprintf(buffer, sizeof(buffer), "%5.1f%% ", this->values[CPU_METER_IRQ]);
         rs_append(out, CRT_colors[METER_TEXT], "vir:");
         rs_appendn(out, CRT_colors[CPU_GUEST], buffer, len);
      }
   }
   if (settings->showCPUFrequency) {
      char fb[16];
      double f = this->values[CPU_METER_FREQUENCY];
      if (!isnan(f) && f >= 0) len = xsnprintf(fb, sizeof(fb), "%4uMHz ", (unsigned)f);
      else len = xsnprintf(fb, sizeof(fb), "N/A     ");
      rs_append(out, CRT_colors[METER_TEXT], "freq: ");
      rs_appendn(out, CRT_colors[METER_VALUE], fb, len);
   }
}

