static const int LoadAverageMeter_attributes[] = { LOAD_AVERAGE_ONE, LOAD_AVERAGE_FIVE, LOAD_AVERAGE_FIFTEEN };
static const int OK_attributes[] = { METER_VALUE_OK };
static const int Medium_attributes[] = { METER_VALUE_WARN };
static const int High_attributes[] = { METER_VALUE_ERROR };

static void LoadAverageMeter_updateValues(Meter* this) {
   this->values[0] = this->host->load[0];
   this->values[1] = this->host->load[1];
   this->values[2] = this->host->load[2];
   this->curItems = 1;
   if (this->values[0] < 1.0) { this->curAttributes = OK_attributes; this->total = 1.0; }
   else if (this->values[0] < this->host->activeCPUs) { this->curAttributes = Medium_attributes; this->total = this->host->activeCPUs; }
   else { this->curAttributes = High_attributes; this->total = 2 * this->host->activeCPUs; }
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%.2f/%.2f/%.2f", this->values[0], this->values[1], this->values[2]);
}
