   len = xsnprintf(buffer, sizeof(buffer), "%.2f ", this->values[0]);
   rs_appendn(out, CRT_colors[LOAD_AVERAGE_ONE], buffer, len);
   len = xsnprintf(buffer, sizeof(buffer), "%.2f ", this->values[1]);
   rs_appendn(out, CRT_colors[LOAD_AVERAGE_FIVE], buffer, len);
   len = xsnprintf(buffer, sizeof(buffer), "%.2f ", this->values[2]);
   rs_appendn(out, CRT_colors[LOAD_AVERAGE_FIFTEEN], buffer, len);
}
