/* ---- Memory ---- */
enum { MEMORY_METER_USED, MEMORY_METER_SHARED, MEMORY_METER_COMPRESSED, MEMORY_METER_BUFFERS, MEMORY_METER_CACHE, MEMORY_METER_AVAILABLE, MEMORY_METER_ITEMCOUNT };
static const int MemoryMeter_attributes[] = { MEMORY_USED, MEMORY_SHARED, MEMORY_COMPRESSED, MEMORY_BUFFERS, MEMORY_CACHE };

static void MemoryMeter_updateValues(Meter* this) {
   const Machine* host = this->host;
   this->total = host->totalMem;
   this->values[MEMORY_METER_USED] = host->usedMem;
   this->values[MEMORY_METER_SHARED] = host->sharedMem;
   this->values[MEMORY_METER_COMPRESSED] = 0;
   this->values[MEMORY_METER_BUFFERS] = host->buffersMem;
   this->values[MEMORY_METER_CACHE] = host->cachedMem;
   this->values[MEMORY_METER_AVAILABLE] = host->availableMem;
   if (host->zswapOrig > 0 || host->zswapComp > 0) {
      this->values[MEMORY_METER_USED] -= host->zswapComp;
      this->values[MEMORY_METER_COMPRESSED] += host->zswapComp;
   }
   if ((this->mode == GRAPH_METERMODE || this->mode == BAR_METERMODE) && !host->settings->showCachedMemory) {
      this->values[MEMORY_METER_BUFFERS] = 0;
      this->values[MEMORY_METER_CACHE] = 0;
   }
   this->curItems = MEMORY_METER_AVAILABLE;
   double used = this->values[MEMORY_METER_USED];
   if (this->values[MEMORY_METER_SHARED] > 0) used += this->values[MEMORY_METER_SHARED];
   if (this->values[MEMORY_METER_COMPRESSED] > 0) used += this->values[MEMORY_METER_COMPRESSED];
   char a[32], b[32];
   Meter_humanUnit(a, used, sizeof(a));
   Meter_humanUnit(b, this->total, sizeof(b));
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%s/%s", a, b);
}

static void MemoryMeter_display(const Meter* this, RStr* out) {
   char buffer[50];
   rs_append(out, CRT_colors[METER_TEXT], ":");
   Meter_humanUnit(buffer, this->total, sizeof(buffer));
   rs_append(out, CRT_colors[METER_VALUE], buffer);
   Meter_humanUnit(buffer, this->values[MEMORY_METER_USED], sizeof(buffer));
   rs_append(out, CRT_colors[METER_TEXT], " used:");
   rs_append(out, CRT_colors[MEMORY_USED], buffer);
   if (this->values[MEMORY_METER_SHARED] >= 0) {
      Meter_humanUnit(buffer, this->values[MEMORY_METER_SHARED], sizeof(buffer));
      rs_append(out, CRT_colors[METER_TEXT], " shared:");
      rs_append(out, CRT_colors[MEMORY_SHARED], buffer);
   }
   if (this->values[MEMORY_METER_COMPRESSED] >= 0) {
      Meter_humanUnit(buffer, this->values[MEMORY_METER_COMPRESSED], sizeof(buffer));
      rs_append(out, CRT_colors[METER_TEXT], " compressed:");
      rs_append(out, CRT_colors[MEMORY_COMPRESSED], buffer);
   }
   Meter_humanUnit(buffer, this->values[MEMORY_METER_BUFFERS], sizeof(buffer));
   rs_append(out, CRT_colors[METER_TEXT], " buffers:");
   rs_append(out, CRT_colors[MEMORY_BUFFERS_TEXT], buffer);
   Meter_humanUnit(buffer, this->values[MEMORY_METER_CACHE], sizeof(buffer));
   rs_append(out, CRT_colors[METER_TEXT], " cache:");
   rs_append(out, CRT_colors[MEMORY_CACHE], buffer);
   if (this->values[MEMORY_METER_AVAILABLE] >= 0) {
      Meter_humanUnit(buffer, this->values[MEMORY_METER_AVAILABLE], sizeof(buffer));
      rs_append(out, CRT_colors[METER_TEXT], " available:");
      rs_append(out, CRT_colors[METER_VALUE], buffer);
   }
}
static const MeterClass MemoryMeter_class = {
   .name = "Memory", .uiName = "Memory", .caption = "Mem", .description = "Memory", .defaultMode = BAR_METERMODE,
   .maxItems = MEMORY_METER_ITEMCOUNT, .total = 100.0, .attributes = MemoryMeter_attributes,
   .updateValues = MemoryMeter_updateValues, .display = MemoryMeter_display,
};

