/* ---- MemorySwap ---- */
typedef struct { Meter* mem; Meter* swap; } MemorySwapData;
static void MemorySwapMeter_init(Meter* this) {
   MemorySwapData* d = this->meterData;
   if (!d) d = this->meterData = xcalloc(1, sizeof(MemorySwapData));
   if (!d->mem) d->mem = Meter_new(this->host, 0, &MemoryMeter_class);
   if (!d->swap) d->swap = Meter_new(this->host, 0, &SwapMeter_class);
   if (this->mode <= 0) this->mode = BAR_METERMODE;
   this->h = MAXI(d->mem->h, d->swap->h);
}
static void MemorySwapMeter_updateMode(Meter* this, int mode) {
   MemorySwapData* d = this->meterData;
   this->mode = mode;
   Meter_setMode(d->mem, mode);
   Meter_setMode(d->swap, mode);
   this->h = MAXI(d->mem->h, d->swap->h);
}
static void MemorySwapMeter_updateValues(Meter* this) {
   MemorySwapData* d = this->meterData;
   Meter_updateValues(d->mem);
   Meter_updateValues(d->swap);
}
static void MemorySwapMeter_draw(Meter* this, int x, int y, int w) {
   MemorySwapData* d = this->meterData;
   int colwidth = w / 2;
   int diff = w % 2;
   Meter_draw(d->mem, x, y, colwidth);
   Meter_draw(d->swap, x + colwidth + diff, y, colwidth);
}
static void MemorySwapMeter_done(Meter* this) {
   MemorySwapData* d = this->meterData;
   if (!d) return;
   Meter_delete(d->mem); Meter_delete(d->swap);
   free(d); this->meterData = NULL;
}
static const MeterClass MemorySwapMeter_class = {
   .name = "MemorySwap", .uiName = "Memory & Swap", .caption = "M&S", .description = "Combined memory and swap usage",
   .defaultMode = CUSTOM_METERMODE, .maxItems = 0, .total = 100.0, .attributes = MemoryMeter_attributes, .isMultiColumn = true,
   .init = MemorySwapMeter_init, .done = MemorySwapMeter_done, .updateMode = MemorySwapMeter_updateMode,
   .updateValues = MemorySwapMeter_updateValues, .draw = MemorySwapMeter_draw,
};

/* ---- System ---- */
static const int SysArchMeter_attributes[] = { HOSTNAME };
static char* sysarchString;
static void SysArchMeter_updateValues(Meter* this) {
   if (!sysarchString) {
      struct utsname uts;
      char distro[256] = "";
      if (uname(&uts) != 0) memset(&uts, 0, sizeof(uts));
      FILE* f = fopen("/etc/os-release", "r");
      if (!f) f = fopen("/usr/lib/os-release", "r");
      if (f) {
         char line[512];
         while (fgets(line, sizeof(line), f)) {
            if (str_starts(line, "PRETTY_NAME=")) {
               char* v = line + 12;
               size_t l = strlen(v);
               while (l > 0 && (v[l-1] == '\n' || v[l-1] == '\r')) v[--l] = 0;
               if (l >= 2 && (v[0] == '"' || v[0] == '\'') && v[l-1] == v[0]) { v[l-1] = 0; v++; }
               snprintf(distro, sizeof(distro), "%s", v);
               break;
            }
         }
         fclose(f);
      }
      if (distro[0]) sysarchString = xasprintf("%s %s [%s] @ %s", uts.sysname, uts.release, uts.machine, distro);
      else sysarchString = xasprintf("%s %s [%s]", uts.sysname, uts.release, uts.machine);
   }
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%s", sysarchString);
}
static const MeterClass SysArchMeter_class = {
   .name = "System", .uiName = "System", .caption = "System: ", .description = "System", .defaultMode = TEXT_METERMODE,
   .supportedModes = MODES_TEXT, .maxItems = 0, .total = 100.0, .attributes = SysArchMeter_attributes,
   .updateValues = SysArchMeter_updateValues,
};

