   .name = "Uptime", .uiName = "Uptime", .caption = "Uptime: ", .description = "Uptime", .defaultMode = TEXT_METERMODE,
   .supportedModes = MODES_TEXT_LED, .maxItems = 1, .total = 100.0, .attributes = UptimeMeter_attributes,
