static const int ZramMeter_attributes[] = { ZRAM };
static void ZramMeter_updateValues(Meter* this) {
   unsigned long long totalZram = 0, usedComp = 0, usedOrig = 0;
   DIR* d = opendir("/sys/block");
   if (d) {
      struct dirent* e;
      while ((e = readdir(d))) {
         if (!str_starts(e->d_name, "zram")) continue;
         char path[512], buf[512];
         snprintf(path, sizeof(path), "/sys/block/%s/disksize", e->d_name);
         if (readFileBuf(path, buf, sizeof(buf)) > 0) totalZram += strtoull(buf, NULL, 10) / 1024;
         snprintf(path, sizeof(path), "/sys/block/%s/mm_stat", e->d_name);
         if (readFileBuf(path, buf, sizeof(buf)) > 0) {
            unsigned long long orig, comp;
            if (sscanf(buf, "%llu %llu", &orig, &comp) == 2) { usedOrig += orig / 1024; usedComp += comp / 1024; }
         }
      }
      closedir(d);
   }
   this->total = totalZram;
   this->values[0] = usedComp;
   this->values[1] = usedOrig;
   this->curItems = 1;
   char a[32], b[32], c[32];
   Meter_humanUnit(a, usedComp, sizeof(a));
   Meter_humanUnit(b, usedOrig, sizeof(b));
   Meter_humanUnit(c, totalZram, sizeof(c));
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%s(%s)/%s", a, b, c);
}
