typedef struct { Meter* rate; Meter* time; } DiskIOData;
static void DiskIOMeter_init(Meter* this) {
   DiskIOData* d = this->meterData;
   if (!d) d = this->meterData = xcalloc(1, sizeof(DiskIOData));
   if (!d->rate) d->rate = Meter_new(this->host, 0, &DiskIORateMeter_class);
   if (!d->time) d->time = Meter_new(this->host, 0, &DiskIOTimeMeter_class);
   if (this->mode <= 0) this->mode = TEXT_METERMODE;
   Meter_setMode(d->rate, this->mode); Meter_setMode(d->time, this->mode);
   this->h = MAXI(d->rate->h, d->time->h);
}
static void DiskIOMeter_updateMode(Meter* this, int mode) {
   DiskIOData* d = this->meterData;
   this->mode = mode;
   Meter_setMode(d->rate, mode);
   Meter_setMode(d->time, mode);
   this->h = MAXI(d->rate->h, d->time->h);
}
static void DiskIOMeter_updateValues(Meter* this) {
   DiskIOData* d = this->meterData;
   Meter_updateValues(d->rate);
   Meter_updateValues(d->time);
}
static void DiskIOMeter_draw(Meter* this, int x, int y, int w) {
   DiskIOData* d = this->meterData;
   if (this->mode == TEXT_METERMODE) {
      const char* caption = "Dsk: ";
      attrset(CRT_colors[METER_TEXT]);
      mvaddnstr(y, x, caption, w);
      attrset(CRT_colors[RESET_COLOR]);
      int cl = strlen(caption);
      if (w - cl <= 0) return;
      RStr out; rs_init(&out);
      DiskIORateMeter_display(d->rate, &out);
      rs_append(&out, CRT_colors[METER_TEXT], "; ");
      DiskIOTimeMeter_display(d->time, &out);
      rs_print(&out, y, x + cl, 0, w - cl);
      rs_free(&out);
      return;
   }
   int colwidth = w / 2;
   int diff = w % 2;
   Meter_draw(d->rate, x, y, colwidth);
   Meter_draw(d->time, x + colwidth + diff, y, colwidth);
}
static void DiskIOMeter_done(Meter* this) {
   DiskIOData* d = this->meterData;
   if (!d) return;
   Meter_delete(d->rate); Meter_delete(d->time);
   free(d); this->meterData = NULL;
}
