/* ---- File descriptors ---- */
static const int FileDescriptorMeter_attributes[] = { FILE_DESCRIPTOR_USED, FILE_DESCRIPTOR_MAX };
#define FD_UNLIMITED(x) (!((double)(1ULL << 62) > (x)))
static void FileDescriptorMeter_updateValues(Meter* this) {
   this->values[0] = -1;
   this->values[1] = NAN;
   char buf[128];
   if (readFileBuf("/proc/sys/fs/file-nr", buf, sizeof(buf)) > 0) {
      unsigned long long a, u, m;
      if (sscanf(buf, "%llu %llu %llu", &a, &u, &m) == 3) {
         this->values[0] = (double)a;
         this->values[1] = (double)m;
      }
   }
   this->curItems = 1;
   if (isnan(this->values[1])) this->total = 1;
   else this->total = this->values[1];
   if (this->total > (1 << 16) || isnan(this->values[1])) {
      double upper = 1 << 16;
      while (upper < 16 * this->values[0]) upper *= 2;
      if (!isnan(this->values[1])) this->total = MINI(this->total, upper);
      else this->total = upper;
   }
   if (this->values[0] > this->total) this->total = this->values[0];
   if (isnan(this->values[1]) || FD_UNLIMITED(this->values[1]))
      xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%.0lf/unlimited", this->values[0]);
   else
      xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "%.0lf/%.0lf", this->values[0], this->values[1]);
}
static void FileDescriptorMeter_display(const Meter* this, RStr* out) {
   char buffer[64];
   int len;
   if (this->values[0] < 0) { rs_append(out, CRT_colors[METER_TEXT], "unknown"); return; }
   rs_append(out, CRT_colors[METER_TEXT], "used: ");
   len = xsnprintf(buffer, sizeof(buffer), "%.0lf", this->values[0]);
   rs_appendn(out, CRT_colors[FILE_DESCRIPTOR_USED], buffer, len);
   rs_append(out, CRT_colors[METER_TEXT], " max: ");
   if (isnan(this->values[1]) || FD_UNLIMITED(this->values[1])) {
      rs_append(out, CRT_colors[FILE_DESCRIPTOR_MAX], "unlimited");
   } else {
      len = xsnprintf(buffer, sizeof(buffer), "%.0lf", this->values[1]);
      rs_appendn(out, CRT_colors[FILE_DESCRIPTOR_MAX], buffer, len);
   }
}
