#include "header.h"
#include "crt.h"
#include <math.h>

Header* Header_new(Machine* host, Settings* settings) {
   Header* this = xcalloc(1, sizeof(Header));
   this->host = host;
   this->settings = settings;
   this->headerLayout = settings->hLayout;
   this->nColumns = HeaderLayouts[this->headerLayout].columns;
   for (int i = 0; i < 4; i++) this->columns[i] = vec_new();
   return this;
}

void Header_delete(Header* this) {
   for (int i = 0; i < 4; i++) {
      for (int j = 0; j < this->columns[i]->size; j++) Meter_delete(this->columns[i]->items[j]);
      vec_free(this->columns[i]);
   }
   free(this);
}

void Header_setLayout(Header* this, HeaderLayout hLayout) {
   int oldColumns = HeaderLayouts[this->headerLayout].columns;
   int newColumns = HeaderLayouts[hLayout].columns;
   this->headerLayout = hLayout;
   this->nColumns = newColumns;
   if (newColumns < oldColumns) {
      for (int i = newColumns; i < oldColumns; i++) {
         Vec* from = this->columns[i];
         Vec* to = this->columns[newColumns - 1];
         for (int j = 0; j < from->size; j++) vec_push(to, from->items[j]);
         vec_clear(from);
      }
   }
   Header_calculateHeight(this);
}

Meter* Header_addMeterByClass(Header* this, const MeterClass* type, unsigned int param, int column) {
   Meter* meter = Meter_new(this->host, param, type);
   vec_push(this->columns[column], meter);
   return meter;
}

void Header_addMeterByName(Header* this, const char* name, int mode, int column) {
   const char* paren = strchr(name, '(');
   unsigned int param = 0;
   size_t nameLen;
   if (paren) {
      if (sscanf(paren, "(%10u)", &param) != 1) param = 0;
      nameLen = paren - name;
   } else {
      nameLen = strlen(name);
   }
   for (const MeterClass* const* type = Platform_meterTypes; *type; type++) {
      if (strlen((*type)->name) != nameLen || strncmp(name, (*type)->name, nameLen) != 0) continue;
      Meter* meter = Meter_new(this->host, param, *type);
      if (mode != 0) Meter_setMode(meter, mode);
      vec_push(this->columns[column], meter);
      break;
   }
}

void Header_populateFromSettings(Header* this) {
   this->headerLayout = this->settings->hLayout;
   this->nColumns = HeaderLayouts[this->headerLayout].columns;
   for (int col = 0; col < this->nColumns; col++) {
      const MeterColumnSetting* cs = &this->settings->hColumns[col];
      for (int j = 0; j < this->columns[col]->size; j++) Meter_delete(this->columns[col]->items[j]);
      vec_clear(this->columns[col]);
      for (int i = 0; i < cs->len; i++) {
         if (cs->names && cs->names[i]) Header_addMeterByName(this, cs->names[i], cs->modes ? cs->modes[i] : 0, col);
      }
   }
   Header_calculateHeight(this);
}

void Header_writeBackToSettings(const Header* this) {
   Settings* s = this->settings;
   Settings_setHeaderLayout(s, this->headerLayout);
   for (int col = 0; col < this->nColumns; col++) {
      MeterColumnSetting* cs = &s->hColumns[col];
      str_freeArray(cs->names);
      free(cs->modes);
      Vec* meters = this->columns[col];
      int len = meters->size;
      cs->names = xcalloc(len + 1, sizeof(char*));
      cs->modes = len ? xcalloc(len, sizeof(int)) : NULL;
      cs->len = len;
      for (int i = 0; i < len; i++) {
         Meter* m = meters->items[i];
         char name[64];
         Meter_writeName(m, name, sizeof(name));
         cs->names[i] = xstrdup(name);
         cs->modes[i] = m->mode;
      }
   }
}

void Header_reinit(Header* this) {
   for (int col = 0; col < this->nColumns; col++) {
      for (int i = 0; i < this->columns[col]->size; i++) {
         Meter* m = this->columns[col]->items[i];
         if (m->cls->init) m->cls->init(m);
      }
   }
}

void Header_updateData(Header* this) {
   for (int col = 0; col < this->nColumns; col++) {
      Vec* meters = this->columns[col];
      for (int i = 0; i < meters->size; i++) Meter_updateValues(meters->items[i]);
   }
}

static int calcColumnWidthCount(const Header* this, const Meter* curMeter, int pad, int curColumn, int curHeight) {
   for (int i = curColumn + 1; i < this->nColumns; i++) {
      const Vec* meters = this->columns[i];
      int height = pad;
      for (int j = 0; j < meters->size; j++) {
         const Meter* meter = meters->items[j];
         if (height >= curHeight + curMeter->h) break;
         height += meter->h;
         if (height <= curHeight) continue;
         if (meter->cls != &BlankMeter_class) return i - curColumn;
      }
   }
   return this->nColumns - curColumn;
}

int Header_calculateHeight(Header* this) {
   int pad = this->settings->headerMargin ? 2 : 0;
   int maxHeight = pad;
   for (int col = 0; col < this->nColumns; col++) {
      Vec* meters = this->columns[col];
      int height = pad;
      for (int i = 0; i < meters->size; i++) {
         Meter* meter = meters->items[i];
         meter->columnWidthCount = calcColumnWidthCount(this, meter, pad, col, height);
         height += meter->h;
      }
      maxHeight = MAXI(maxHeight, height);
   }
   if (this->settings->screenTabs) maxHeight++;
   this->height = maxHeight;
   this->pad = pad;
   return maxHeight;
}

void Header_draw(const Header* this) {
   int height = this->height;
   int pad = this->pad;
   attrset(CRT_colors[RESET_COLOR]);
   for (int y = 0; y < height; y++) mvhline(y, 0, ' ', COLS);
   int numCols = this->nColumns;
   int width = COLS - 2 * pad - (numCols - 1);
   int x = pad;
   float roundingLoss = 0.0F;
   for (int col = 0; col < numCols; col++) {
      Vec* meters = this->columns[col];
      float colWidth = (float)width * HeaderLayouts[this->headerLayout].widths[col] / 100.0F;
      roundingLoss += colWidth - floorf(colWidth);
      if (roundingLoss >= 1.0F) {
         colWidth += 1.0F;
         roundingLoss -= 1.0F;
      }
      for (int y = (pad / 2), i = 0; i < meters->size; i++) {
         Meter* meter = meters->items[i];
         float actualWidth = colWidth;
         if (meter->mode == TEXT_METERMODE && !meter->cls->isMultiColumn) {
            for (int j = 1; j < meter->columnWidthCount; j++) {
               actualWidth++;
               actualWidth += (float)width * HeaderLayouts[this->headerLayout].widths[col + j] / 100.0F;
            }
         }
         Meter_draw(meter, x, y, (int)floorf(actualWidth));
         y += meter->h;
      }
      x += (int)floorf(colWidth);
      x++;
   }
}
