#include "app.h"
#include "crt.h"
#include <ctype.h>
#include <math.h>
#include <pwd.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

/* ======================= IncSet ======================= */
static const char* const searchFunctions[] = {"Next  ", "Prev   ", "Cancel ", " Search: ", NULL};
static const char* const searchKeys[] = {"F3", "S-F3", "Esc", "  "};
static const int searchEvents[] = {KEY_F(3), KEY_F(15), 27, ERR};
static const char* const filterFunctions[] = {"Done  ", "Clear ", " Filter: ", NULL};
static const char* const filterKeys[] = {"Enter", "Esc", "  "};
static const int filterEvents[] = {13, 27, ERR};

IncSet* IncSet_new(FunctionBar* bar) {
   IncSet* this = xcalloc(1, sizeof(IncSet));
   this->modes[INC_SEARCH].bar = FunctionBar_new(searchFunctions, searchKeys, searchEvents);
   this->modes[INC_SEARCH].isFilter = false;
   this->modes[INC_FILTER].bar = FunctionBar_new(filterFunctions, filterKeys, filterEvents);
   this->modes[INC_FILTER].isFilter = true;
   this->active = NULL;
   this->filtering = false;
   this->found = false;
   this->defaultBar = bar;
   return this;
}
void IncSet_delete(IncSet* this) {
   FunctionBar_delete(this->modes[0].bar);
   FunctionBar_delete(this->modes[1].bar);
   free(this);
}
static void IncMode_reset(IncMode* m) { m->index = 0; m->buffer[0] = 0; }
void IncSet_reset(IncSet* this, IncType type) { IncMode_reset(&this->modes[type]); }
void IncSet_setFilter(IncSet* this, const char* filter) {
   IncMode* m = &this->modes[INC_FILTER];
   snprintf(m->buffer, sizeof(m->buffer), "%s", filter);
   m->index = strlen(m->buffer);
   this->filtering = true;
}

static bool containsMulti(const char* hay, const char* needle) {
   if (!hay) hay = "";
   if (!strchr(needle, '|')) return strcasestr(hay, needle) != NULL;
   char* copy = xstrdup(needle);
   char* save = NULL;
   bool found = false;
   for (char* tok = strtok_r(copy, "|", &save); tok; tok = strtok_r(NULL, "|", &save)) {
      if (strcasestr(hay, tok)) { found = true; break; }
   }
   free(copy);
   return found;
}

static void updateWeakPanel(const IncSet* this, Panel* panel, Vec* lines) {
   const Item* selected = Panel_getSelected(panel);
   bool owns = panel->ownsItems;
   panel->ownsItems = false;
   Panel_prune(panel);
   panel->ownsItems = owns;
   if (this->filtering) {
      int n = 0;
      const char* incFilter = this->modes[INC_FILTER].buffer;
      for (int i = 0; i < lines->size; i++) {
         ListItem* line = lines->items[i];
         if (containsMulti(line->value, incFilter)) {
            Panel_add(panel, (Item*)line);
            if (selected == (Item*)line) Panel_setSelected(panel, n);
            n++;
         }
      }
   } else {
      for (int i = 0; i < lines->size; i++) {
         Item* line = lines->items[i];
         Panel_add(panel, line);
         if (selected == line) Panel_setSelected(panel, i);
      }
   }
}

static bool doSearchFn(const IncSet* this, Panel* panel, IncMode_GetPanelValue getPanelValue) {
   int size = Panel_size(panel);
   for (int i = 0; i < size; i++) {
      if (containsMulti(getPanelValue(panel, i), this->active->buffer)) {
         Panel_setSelected(panel, i);
         return true;
      }
   }
   return false;
}

void IncSet_drawBar(const IncSet* this, int attr) {
   if (this->active) {
      if (!this->active->isFilter && !this->found) attr = CRT_colors[FAILED_SEARCH];
      FunctionBar_drawExtra(this->active->bar, this->active->buffer, attr, true);
   } else {
      FunctionBar_draw(this->defaultBar);
   }
}

void IncSet_activate(IncSet* this, IncType type, Panel* panel) {
   this->active = &this->modes[type];
   panel->currentBar = this->active->bar;
   panel->cursorOn = true;
   this->panel = panel;
   IncSet_drawBar(this, CRT_colors[FUNCTION_BAR]);
}

static void IncSet_deactivate(IncSet* this, Panel* panel) {
   this->active = NULL;
   panel->currentBar = panel->defaultBar;
   panel->cursorOn = false;
   FunctionBar_draw(this->defaultBar);
}

static bool IncMode_find(const IncMode* mode, Panel* panel, IncMode_GetPanelValue getPanelValue, int step) {
   int size = Panel_size(panel);
   int here = Panel_getSelectedIndex(panel);
   int i = here;
   for (;;) {
      i += step;
      if (i == size) i = 0;
      if (i == -1) i = size - 1;
      if (i == here) return false;
      if (containsMulti(getPanelValue(panel, i), mode->buffer)) {
         Panel_setSelected(panel, i);
         return true;
      }
   }
}
bool IncSet_next(IncSet* this, IncType type, Panel* panel, IncMode_GetPanelValue getPanelValue) {
   return IncMode_find(&this->modes[type], panel, getPanelValue, 1);
}
bool IncSet_prev(IncSet* this, IncType type, Panel* panel, IncMode_GetPanelValue getPanelValue) {
   return IncMode_find(&this->modes[type], panel, getPanelValue, -1);
}

bool IncSet_handleKey(IncSet* this, int ch, Panel* panel, IncMode_GetPanelValue getPanelValue, Vec* lines) {
   if (ch == ERR) return true;
   IncMode* mode = this->active;
   int size = Panel_size(panel);
   bool filterChanged = false;
   bool doSearch = true;
   if (ch == KEY_F(3) || ch == KEY_F(15)) {
      if (size == 0) return true;
      IncMode_find(mode, panel, getPanelValue, ch == KEY_F(3) ? 1 : -1);
      doSearch = false;
   } else if (0 < ch && ch < 255 && isprint((unsigned char)ch)) {
      if (mode->index < INCMODE_MAX) {
         mode->buffer[mode->index] = (char)ch;
         mode->index++;
         mode->buffer[mode->index] = 0;
         if (mode->isFilter) {
            filterChanged = true;
            if (mode->index == 1) this->filtering = true;
         }
      }
   } else if (ch == KEY_BACKSPACE || ch == 127) {
      if (mode->index > 0) {
         mode->index--;
         mode->buffer[mode->index] = 0;
         if (mode->isFilter) {
            filterChanged = true;
            if (mode->index == 0) {
               this->filtering = false;
               IncMode_reset(mode);
            }
         }
      } else {
         doSearch = false;
      }
   } else if (ch == KEY_RESIZE) {
      doSearch = (mode->index > 0);
   } else {
      if (mode->isFilter) {
         filterChanged = true;
         if (ch == 27) {
            this->filtering = false;
            IncMode_reset(mode);
         }
      } else {
         if (ch == 27) IncMode_reset(mode);
      }
      IncSet_deactivate(this, panel);
      doSearch = false;
   }
   if (doSearch) this->found = doSearchFn(this, panel, getPanelValue);
   if (filterChanged && lines) updateWeakPanel(this, panel, lines);
   return filterChanged;
}

const char* IncSet_getListItemValue(Panel* panel, int i) {
   const ListItem* l = (const ListItem*)Panel_get(panel, i);
   return l ? l->value : "";
}

int IncSet_synthesizeEvent(IncSet* this, int x) {
   if (this->active) return FunctionBar_synthesizeEvent(this->active->bar, x);
   return FunctionBar_synthesizeEvent(this->defaultBar, x);
}

/* ======================= ScreenManager ======================= */
ScreenManager* ScreenManager_new(Header* header, Machine* host, State* state, bool owner) {
   (void)owner;
   ScreenManager* this = xcalloc(1, sizeof(ScreenManager));
   this->panels = vec_new();
   this->header = header;
   this->host = host;
   this->state = state;
   this->allowFocusChange = true;
   this->y1 = 0;
   this->y2 = -1;
   return this;
}
void ScreenManager_delete(ScreenManager* this) {
   vec_free(this->panels);
   free(this);
}
int ScreenManager_headerHeight(const ScreenManager* this) {
   return (this->state && this->state->hideMeters) ? 0 : (this->header ? this->header->height : 0);
}
void ScreenManager_insert(ScreenManager* this, Panel* item, int size, int idx) {
   int lastX = 0;
   if (idx > 0) {
      const Panel* last = this->panels->items[idx - 1];
      lastX = last->x + last->w + 1;
   }
   int height = LINES - this->y1 - ScreenManager_headerHeight(this) + this->y2;
   if (size <= 0) size = COLS - lastX;
   Panel_resize(item, size, height);
   Panel_move(item, lastX, this->y1 + ScreenManager_headerHeight(this));
   if (idx < this->panelCount) {
      for (int i = idx + 1; i <= this->panelCount; i++) {
         Panel* p = this->panels->items[i - 1];
         Panel_move(p, p->x + size, p->y);
      }
   }
   vec_insert(this->panels, idx, item);
   item->needsRedraw = true;
   this->panelCount++;
}
void ScreenManager_add(ScreenManager* this, Panel* item, int size) {
   ScreenManager_insert(this, item, size, this->panelCount);
}
Panel* ScreenManager_remove(ScreenManager* this, int idx) {
   Panel* panel = vec_remove(this->panels, idx);
   this->panelCount--;
   if (idx < this->panelCount) {
      for (int i = idx; i < this->panelCount; i++) {
         Panel* p = this->panels->items[i];
         Panel_move(p, p->x - panel->w, p->y);
      }
   }
   return panel;
}
void ScreenManager_resize(ScreenManager* this) {
   int y1_header = this->y1 + ScreenManager_headerHeight(this);
   int panels = this->panelCount;
   int lastX = 0;
   for (int i = 0; i < panels - 1; i++) {
      Panel* panel = this->panels->items[i];
      Panel_resize(panel, panel->w, LINES - y1_header + this->y2);
      Panel_move(panel, lastX, y1_header);
      lastX = panel->x + panel->w + 1;
   }
   Panel* panel = this->panels->items[panels - 1];
   Panel_resize(panel, COLS - lastX, LINES - y1_header + this->y2);
   Panel_move(panel, lastX, y1_header);
}

static void checkRecalculation(ScreenManager* this, double* oldTime, int* sortTimeout, bool* redraw, bool* rescan, bool* timedOut, bool* force_redraw) {
   Machine* host = this->host;
   struct timeval tv;
   realtimeNow(&tv, NULL);
   double newTime = ((double)tv.tv_sec * 10) + ((double)tv.tv_usec / 100000);
   *timedOut = (newTime - *oldTime > host->settings->delay);
   *rescan |= *timedOut;
   if (newTime < *oldTime) *rescan = true;
   if (*rescan) {
      *oldTime = newTime;
      int oldUidDigits = Row_uidDigits;
      int oldPidDigits = Row_pidDigits;
      if (!this->state->pauseUpdate && (*sortTimeout == 0 || host->settings->ss->treeView)) {
         host->needsSort = true;
         *sortTimeout = 1;
      }
      Machine_scan(host);
      if (!this->state->pauseUpdate) {
         bool ns = host->needsSort;
         Machine_scanProcesses(host);
         host->needsSort = ns;
      }
      Header_updateData(this->header);
      if (Row_uidDigits != oldUidDigits || Row_pidDigits != oldPidDigits) *force_redraw = true;
      *redraw = true;
   }
   if (*redraw) {
      Machine_rebuildPanel(host);
      if (!this->state->hideMeters) Header_draw(this->header);
   }
   *rescan = false;
}

static bool drawTab(int y, int* x, int l, const char* name, bool cur) {
   attrset(CRT_colors[cur ? SCREENS_CUR_BORDER : SCREENS_OTH_BORDER]);
   mvaddch(y, *x, '[');
   (*x)++;
   if (*x >= l) return false;
   int nameWidth = strnlen(name, l - *x);
   attrset(CRT_colors[cur ? SCREENS_CUR_TEXT : SCREENS_OTH_TEXT]);
   mvaddnstr(y, *x, name, nameWidth);
   *x += nameWidth;
   if (*x >= l) return false;
   attrset(CRT_colors[cur ? SCREENS_CUR_BORDER : SCREENS_OTH_BORDER]);
   mvaddch(y, *x, ']');
   *x += 2;
   if (*x >= l) return false;
   return true;
}

static void drawScreenTabs(ScreenManager* this) {
   Settings* s = this->host->settings;
   int cur = s->ssIndex;
   int l = COLS;
   Panel* panel = this->panels->items[0];
   int y = panel->y - 1;
   int x = 2;
   if (y < 0) return;
   if (this->name) {
      drawTab(y, &x, l, this->name, true);
      attrset(CRT_colors[RESET_COLOR]);
      return;
   }
   for (int i = 0; i < s->nScreens; i++) {
      if (!drawTab(y, &x, l, s->screens[i]->heading, i == cur)) break;
   }
   attrset(CRT_colors[RESET_COLOR]);
}

static void drawPanels(ScreenManager* this, int focus, bool force_redraw) {
   if (this->host->settings->screenTabs) drawScreenTabs(this);
   int n = this->panelCount;
   for (int i = 0; i < n; i++) {
      Panel* panel = this->panels->items[i];
      Panel_draw(panel, force_redraw, i == focus,
                 panel != (Panel*)this->state->mainPanel || !this->state->hideSelection,
                 State_hideFunctionBar(this->state));
      mvvline(panel->y, panel->x + panel->w, ' ', panel->h + (State_hideFunctionBar(this->state) ? 1 : 0));
   }
}

static Panel* setCurrentPanel(ScreenManager* this, Panel* panel) {
   (void)this;
   FunctionBar_draw(panel->currentBar);
   return panel;
}

extern volatile sig_atomic_t CRT_resized;

void ScreenManager_run(ScreenManager* this, Panel** lastFocus, int* lastKey, const char* name) {
   bool quit = false;
   int focus = 0;
   Panel* panelFocus = this->panels->items[focus];
   double oldTime = 0.0;
   int ch = ERR;
   int closeTimeout = 0;
   bool timedOut = true;
   bool redraw = true;
   bool force_redraw = true;
   bool rescan = false;
   int sortTimeout = 0;
   int resetSortTimeout = 5;
   this->name = name;

   while (!quit) {
      if (this->header) {
         checkRecalculation(this, &oldTime, &sortTimeout, &redraw, &rescan, &timedOut, &force_redraw);
      }
      if (redraw || force_redraw) {
         drawPanels(this, focus, force_redraw);
         force_redraw = false;
         if (this->host->iterationsRemaining != -1) {
            if (!--this->host->iterationsRemaining) {
               quit = true;
               continue;
            }
         }
      }
      if (panelFocus->cursorOn) {
         move(LINES - 1, CRT_cursorX);
      }
      int prevCh = ch;
      set_escdelay(25);
      ch = getch();

      HandlerResult result = IGNORED;
      if (ch == KEY_MOUSE && this->host->settings->enableMouse) {
         ch = ERR;
         MEVENT mevent;
         int ok = getmouse(&mevent);
         if (ok == OK) {
            if (mevent.bstate & BUTTON1_RELEASED) {
               if (mevent.y == LINES - 1) {
                  ch = FunctionBar_synthesizeEvent(panelFocus->currentBar, mevent.x);
               } else {
                  for (int i = 0; i < this->panelCount; i++) {
                     Panel* panel = this->panels->items[i];
                     if (mevent.x >= panel->x && mevent.x <= panel->x + panel->w) {
                        if (mevent.y == panel->y) {
                           ch = EVENT_HEADER_CLICK(mevent.x - panel->x);
                           break;
                        } else if (mevent.y > panel->y && mevent.y <= panel->y + panel->h) {
                           ch = KEY_MOUSE;
                           if (panel == panelFocus || this->allowFocusChange) {
                              focus = i;
                              panelFocus = setCurrentPanel(this, panel);
                              Item* oldSelection = Panel_getSelected(panel);
                              Panel_setSelected(panel, mevent.y - panel->y + panel->scrollV - 1);
                              if (Panel_getSelected(panel) == oldSelection) ch = KEY_RECLICK;
                           }
                           break;
                        }
                     }
                  }
               }
            } else if (mevent.bstate & BUTTON4_PRESSED) {
               ch = KEY_WHEELUP;
            } else if (mevent.bstate & BUTTON5_PRESSED) {
               ch = KEY_WHEELDOWN;
            }
         }
      }
      if (ch == ERR) {
         if (sortTimeout > 0) sortTimeout--;
         if (prevCh == ch && !timedOut) {
            closeTimeout++;
            if (closeTimeout == 100) break;
         } else {
            closeTimeout = 0;
         }
         redraw = false;
         continue;
      }
      switch (ch) {
      case KEY_ALT('H'): ch = KEY_LEFT; break;
      case KEY_ALT('J'): ch = KEY_DOWN; break;
      case KEY_ALT('K'): ch = KEY_UP; break;
      case KEY_ALT('L'): ch = KEY_RIGHT; break;
      }
      redraw = true;
      if (panelFocus->eventHandler) result = panelFocus->eventHandler(panelFocus, ch);
      if (result & SYNTH_KEY) ch = result >> 16;
      if (result & REFRESH) sortTimeout = resetSortTimeout;
      if (result & REDRAW) force_redraw = true;
      if (result & RESIZE) { ScreenManager_resize(this); force_redraw = true; }
      if (result & RESCAN) { rescan = true; sortTimeout = 0; }
      if (result & HANDLED) continue;
      else if (result & BREAK_LOOP) { quit = true; continue; }

      switch (ch) {
      case KEY_RESIZE:
         ScreenManager_resize(this);
         continue;
      case KEY_LEFT:
      case KEY_CTRL('B'):
         if (this->panelCount < 2) goto defaultHandler;
         if (!this->allowFocusChange) break;
tryLeft:
         if (focus > 0) focus--;
         panelFocus = setCurrentPanel(this, this->panels->items[focus]);
         if (Panel_size(panelFocus) == 0 && focus > 0) goto tryLeft;
         break;
      case KEY_RIGHT:
      case KEY_CTRL('F'):
      case 9:
         if (this->panelCount < 2) goto defaultHandler;
         if (!this->allowFocusChange) break;
tryRight:
         if (focus < this->panelCount - 1) focus++;
         panelFocus = setCurrentPanel(this, this->panels->items[focus]);
         if (Panel_size(panelFocus) == 0 && focus < this->panelCount - 1) goto tryRight;
         break;
      case 27:
      case 'q':
      case KEY_F(10):
         quit = true;
         continue;
      default:
defaultHandler:
         sortTimeout = resetSortTimeout;
         Panel_onKey(panelFocus, ch);
         break;
      }
   }
   if (lastFocus) *lastFocus = panelFocus;
   if (lastKey) *lastKey = ch;
}

/* ======================= MainPanel ======================= */
static const char* const MainFunctions[] = {"Help  ", "Setup ", "Search", "Filter", "Tree  ", "SortBy", "Nice -", "Nice +", "Kill  ", "Quit  ", NULL};
static const char* const MainFunctions_ro[] = {"Help  ", "Setup ", "Search", "Filter", "Tree  ", "SortBy", "      ", "      ", "      ", "Quit  ", NULL};

static const char* MainPanel_getValue(Panel* this, int i) {
   const Process* p = (const Process*)Panel_get(this, i);
   if (!p) return "";
   const char* c = Process_getCommand(p);
   return c ? c : "";
}

static void MainPanel_pidSearch(MainPanel* this, int ch) {
   Panel* super = &this->super;
   int id = ch - 48 + this->pidSearch;
   for (int i = 0; i < Panel_size(super); i++) {
      const Process* p = (const Process*)Panel_get(super, i);
      if (p && p->pid == id) {
         Panel_setSelected(super, i);
         break;
      }
   }
   this->pidSearch = id * 10;
   if (this->pidSearch > 10000000) this->pidSearch = 0;
}

static int fieldKeyAt(const Settings* settings, int at) {
   const int* fields = settings->ss->fields;
   int x = 0;
   for (int i = 0; fields[i]; i++) {
      int field = fields[i];
      int len;
      if (Fields[field].pidColumn) len = Row_pidDigits + 1;
      else if (field == ST_UID) len = Row_uidDigits + 1;
      else if (Fields[field].autoWidth) len = Row_fieldWidths[field] + 1;
      else len = strlen(Fields[field].title);
      if (at < x + len) return field;
      x += len;
   }
   return COMM;
}

static HandlerResult MainPanel_eventHandler(Panel* super, int ch) {
   MainPanel* this = (MainPanel*)super;
   Machine* host = this->state->host;
   Htop_Reaction reaction = HTOP_OK;
   HandlerResult result = IGNORED;
   if (ch == KEY_RESIZE) return IGNORED;
   bool needReset = ch != ERR;
   if (!(ch != KEY_MOUSE || host->settings->enableMouse)) needReset = false;
   if (needReset) this->state->hideSelection = false;
   Settings* settings = host->settings;
   ScreenSettings* ss = settings->ss;

   if (EVENT_IS_HEADER_CLICK(ch)) {
      int x = EVENT_HEADER_CLICK_GET_X(ch);
      int hx = super->scrollH + x + 1;
      int field = fieldKeyAt(settings, hx);
      if (ss->treeView && ss->treeViewAlwaysByPID) {
         ss->treeView = false;
         ss->direction = 1;
         reaction |= Action_setSortKey(settings, field);
      } else if (field == ScreenSettings_getActiveSortKey(ss)) {
         ScreenSettings_invertSortOrder(ss);
      } else {
         reaction |= Action_setSortKey(settings, field);
      }
      reaction |= HTOP_RECALCULATE | HTOP_REDRAW_BAR | HTOP_SAVE_SETTINGS;
      result = HANDLED;
   } else if (ch != ERR && this->inc->active) {
      bool filterChanged = IncSet_handleKey(this->inc, ch, super, MainPanel_getValue, NULL);
      if (filterChanged) {
         free(host->incFilter);
         const char* f = IncSet_filter(this->inc);
         host->incFilter = f ? xstrdup(f) : NULL;
         reaction = HTOP_REFRESH | HTOP_REDRAW_BAR;
      }
      if (this->inc->found) {
         reaction |= Action_follow(this->state);
         reaction |= HTOP_KEEP_FOLLOWING;
      }
      result = HANDLED;
   } else if (ch == 27) {
      this->state->hideSelection = true;
      return HANDLED;
   } else if (ch != ERR && ch > 0 && ch < KEY_MAX && this->keys[ch]) {
      reaction |= (this->keys[ch])(this->state);
      result = HANDLED;
   } else if (0 < ch && ch < 255 && isdigit((unsigned char)ch)) {
      MainPanel_pidSearch(this, ch);
   } else {
      if (ch != ERR) this->pidSearch = 0;
      else reaction |= HTOP_KEEP_FOLLOWING;
   }

   if ((reaction & HTOP_REDRAW_BAR) == HTOP_REDRAW_BAR) MainPanel_updateLabels(this, settings->ss->treeView, host->incFilter != NULL);
   if ((reaction & HTOP_RESIZE) == HTOP_RESIZE) result |= RESIZE;
   if ((reaction & HTOP_UPDATE_PANELHDR) == HTOP_UPDATE_PANELHDR) result |= REDRAW;
   if ((reaction & HTOP_REFRESH) == HTOP_REFRESH) result |= REFRESH;
   if ((reaction & HTOP_RECALCULATE) == HTOP_RECALCULATE) result |= RESCAN;
   if ((reaction & HTOP_SAVE_SETTINGS) == HTOP_SAVE_SETTINGS) host->settings->changed = true;
   if ((reaction & HTOP_QUIT) == HTOP_QUIT) return BREAK_LOOP;
   if ((reaction & HTOP_KEEP_FOLLOWING) != HTOP_KEEP_FOLLOWING) {
      host->following = -1;
      Panel_setSelectionColor(super, PANEL_SELECTION_FOCUS);
   }
   return result;
}

int MainPanel_selectedRow(MainPanel* this) {
   const Process* p = (const Process*)Panel_getSelected(&this->super);
   return p ? p->pid : -1;
}

bool MainPanel_foreachRow(MainPanel* this, bool (*fn)(Process*, int), int arg, bool* wasAnyTagged) {
   Panel* super = &this->super;
   bool ok = true;
   bool anyTagged = false;
   for (int i = 0; i < Panel_size(super); i++) {
      Process* p = (Process*)Panel_get(super, i);
      if (p->tag) {
         ok &= fn(p, arg);
         anyTagged = true;
      }
   }
   if (!anyTagged) {
      Process* p = (Process*)Panel_getSelected(super);
      if (p) ok &= fn(p, arg);
   }
   if (wasAnyTagged) *wasAnyTagged = anyTagged;
   return ok;
}

static void MainPanel_drawFunctionBar(Panel* super, bool hideFunctionBar) {
   MainPanel* this = (MainPanel*)super;
   if (hideFunctionBar && !this->inc->active) return;
   IncSet_drawBar(this->inc, CRT_colors[FUNCTION_BAR]);
   if (this->state->pauseUpdate) FunctionBar_append("PAUSED", CRT_colors[PAUSED]);
}

static void MainPanel_printHeader(Panel* super) {
   MainPanel* this = (MainPanel*)super;
