/* ======================= IncSet ======================= */
static const char* const searchFunctions[] = {"Next  ", "Prev   ", "Cancel ", " Search: ", NULL};
static const char* const searchKeys[] = {"F3", "S-F3", "Esc", "  "};
static const int searchEvents[] = {KEY_F(3), KEY_F(15), 27, ERR};
static const char* const filterFunctions[] = {"Done  ", "Clear ", " Filter: ", NULL};
static const char* const filterKeys[] = {"Enter", "Esc", "  "};
static const int filterEvents[] = {13, 27, ERR};

IncSet* IncSet_new(FunctionBar* bar) {
   IncSet* this = xcalloc(1, sizeof(IncSet));
   this->modes[INC_SEARCH].bar = FunctionBar_new(searchFunctions, searchKeys, searchEvents);
   this->modes[INC_SEARCH].isFilter = false;
   this->modes[INC_FILTER].bar = FunctionBar_new(filterFunctions, filterKeys, filterEvents);
   this->modes[INC_FILTER].isFilter = true;
   this->active = NULL;
   this->filtering = false;
   this->found = false;
   this->defaultBar = bar;
   return this;
}
void IncSet_delete(IncSet* this) {
   FunctionBar_delete(this->modes[0].bar);
   FunctionBar_delete(this->modes[1].bar);
   free(this);
}
static void IncMode_reset(IncMode* m) { m->index = 0; m->buffer[0] = 0; }
void IncSet_reset(IncSet* this, IncType type) { IncMode_reset(&this->modes[type]); }
void IncSet_setFilter(IncSet* this, const char* filter) {
   IncMode* m = &this->modes[INC_FILTER];
   snprintf(m->buffer, sizeof(m->buffer), "%s", filter);
   m->index = strlen(m->buffer);
   this->filtering = true;
}

static bool containsMulti(const char* hay, const char* needle) {
   if (!hay) hay = "";
   if (!strchr(needle, '|')) return strcasestr(hay, needle) != NULL;
   char* copy = xstrdup(needle);
   char* save = NULL;
   bool found = false;
   for (char* tok = strtok_r(copy, "|", &save); tok; tok = strtok_r(NULL, "|", &save)) {
      if (strcasestr(hay, tok)) { found = true; break; }
   }
   free(copy);
   return found;
}

static void updateWeakPanel(const IncSet* this, Panel* panel, Vec* lines) {
   const Item* selected = Panel_getSelected(panel);
   bool owns = panel->ownsItems;
   panel->ownsItems = false;
   Panel_prune(panel);
   panel->ownsItems = owns;
   if (this->filtering) {
      int n = 0;
      const char* incFilter = this->modes[INC_FILTER].buffer;
      for (int i = 0; i < lines->size; i++) {
         ListItem* line = lines->items[i];
         if (containsMulti(line->value, incFilter)) {
            Panel_add(panel, (Item*)line);
            if (selected == (Item*)line) Panel_setSelected(panel, n);
            n++;
         }
      }
   } else {
      for (int i = 0; i < lines->size; i++) {
         Item* line = lines->items[i];
         Panel_add(panel, line);
         if (selected == line) Panel_setSelected(panel, i);
      }
   }
}

static bool doSearchFn(const IncSet* this, Panel* panel, IncMode_GetPanelValue getPanelValue) {
   int size = Panel_size(panel);
   for (int i = 0; i < size; i++) {
      if (containsMulti(getPanelValue(panel, i), this->active->buffer)) {
         Panel_setSelected(panel, i);
         return true;
      }
   }
   return false;
}

void IncSet_drawBar(const IncSet* this, int attr) {
   if (this->active) {
      if (!this->active->isFilter && !this->found) attr = CRT_colors[FAILED_SEARCH];
      FunctionBar_drawExtra(this->active->bar, this->active->buffer, attr, true);
   } else {
      FunctionBar_draw(this->defaultBar);
   }
}

void IncSet_activate(IncSet* this, IncType type, Panel* panel) {
   this->active = &this->modes[type];
   panel->currentBar = this->active->bar;
   panel->cursorOn = true;
   this->panel = panel;
   IncSet_drawBar(this, CRT_colors[FUNCTION_BAR]);
}

static void IncSet_deactivate(IncSet* this, Panel* panel) {
   this->active = NULL;
   panel->currentBar = panel->defaultBar;
   panel->cursorOn = false;
   FunctionBar_draw(this->defaultBar);
}

static bool IncMode_find(const IncMode* mode, Panel* panel, IncMode_GetPanelValue getPanelValue, int step) {
   int size = Panel_size(panel);
   int here = Panel_getSelectedIndex(panel);
   int i = here;
   for (;;) {
      i += step;
      if (i == size) i = 0;
      if (i == -1) i = size - 1;
      if (i == here) return false;
      if (containsMulti(getPanelValue(panel, i), mode->buffer)) {
         Panel_setSelected(panel, i);
         return true;
      }
   }
}
bool IncSet_next(IncSet* this, IncType type, Panel* panel, IncMode_GetPanelValue getPanelValue) {
   return IncMode_find(&this->modes[type], panel, getPanelValue, 1);
}
bool IncSet_prev(IncSet* this, IncType type, Panel* panel, IncMode_GetPanelValue getPanelValue) {
   return IncMode_find(&this->modes[type], panel, getPanelValue, -1);
}

bool IncSet_handleKey(IncSet* this, int ch, Panel* panel, IncMode_GetPanelValue getPanelValue, Vec* lines) {
   if (ch == ERR) return true;
   IncMode* mode = this->active;
   int size = Panel_size(panel);
   bool filterChanged = false;
   bool doSearch = true;
   if (ch == KEY_F(3) || ch == KEY_F(15)) {
      if (size == 0) return true;
      IncMode_find(mode, panel, getPanelValue, ch == KEY_F(3) ? 1 : -1);
      doSearch = false;
   } else if (0 < ch && ch < 255 && isprint((unsigned char)ch)) {
      if (mode->index < INCMODE_MAX) {
         mode->buffer[mode->index] = (char)ch;
         mode->index++;
         mode->buffer[mode->index] = 0;
         if (mode->isFilter) {
            filterChanged = true;
            if (mode->index == 1) this->filtering = true;
         }
      }
   } else if (ch == KEY_BACKSPACE || ch == 127) {
      if (mode->index > 0) {
         mode->index--;
         mode->buffer[mode->index] = 0;
         if (mode->isFilter) {
            filterChanged = true;
            if (mode->index == 0) {
               this->filtering = false;
               IncMode_reset(mode);
            }
         }
      } else {
         doSearch = false;
      }
   } else if (ch == KEY_RESIZE) {
      doSearch = (mode->index > 0);
   } else {
      if (mode->isFilter) {
         filterChanged = true;
         if (ch == 27) {
            this->filtering = false;
            IncMode_reset(mode);
         }
      } else {
         if (ch == 27) IncMode_reset(mode);
      }
      IncSet_deactivate(this, panel);
      doSearch = false;
   }
   if (doSearch) this->found = doSearchFn(this, panel, getPanelValue);
   if (filterChanged && lines) updateWeakPanel(this, panel, lines);
   return filterChanged;
}

const char* IncSet_getListItemValue(Panel* panel, int i) {
   const ListItem* l = (const ListItem*)Panel_get(panel, i);
   return l ? l->value : "";
}

int IncSet_synthesizeEvent(IncSet* this, int x) {
   if (this->active) return FunctionBar_synthesizeEvent(this->active->bar, x);
   return FunctionBar_synthesizeEvent(this->defaultBar, x);
}

/* ======================= ScreenManager ======================= */
ScreenManager* ScreenManager_new(Header* header, Machine* host, State* state, bool owner) {
   (void)owner;
   ScreenManager* this = xcalloc(1, sizeof(ScreenManager));
   this->panels = vec_new();
   this->header = header;
   this->host = host;
   this->state = state;
   this->allowFocusChange = true;
   this->y1 = 0;
   this->y2 = -1;
   return this;
}
void ScreenManager_delete(ScreenManager* this) {
   vec_free(this->panels);
   free(this);
}
int ScreenManager_headerHeight(const ScreenManager* this) {
   return (this->state && this->state->hideMeters) ? 0 : (this->header ? this->header->height : 0);
}
void ScreenManager_insert(ScreenManager* this, Panel* item, int size, int idx) {
   int lastX = 0;
   if (idx > 0) {
      const Panel* last = this->panels->items[idx - 1];
      lastX = last->x + last->w + 1;
   }
   int height = LINES - this->y1 - ScreenManager_headerHeight(this) + this->y2;
   if (size <= 0) size = COLS - lastX;
   Panel_resize(item, size, height);
   Panel_move(item, lastX, this->y1 + ScreenManager_headerHeight(this));
   if (idx < this->panelCount) {
      for (int i = idx + 1; i <= this->panelCount; i++) {
         Panel* p = this->panels->items[i - 1];
         Panel_move(p, p->x + size, p->y);
      }
   }
   vec_insert(this->panels, idx, item);
   item->needsRedraw = true;
   this->panelCount++;
}
void ScreenManager_add(ScreenManager* this, Panel* item, int size) {
   ScreenManager_insert(this, item, size, this->panelCount);
}
Panel* ScreenManager_remove(ScreenManager* this, int idx) {
   Panel* panel = vec_remove(this->panels, idx);
   this->panelCount--;
   if (idx < this->panelCount) {
      for (int i = idx; i < this->panelCount; i++) {
         Panel* p = this->panels->items[i];
         Panel_move(p, p->x - panel->w, p->y);
      }
   }
   return panel;
}
void ScreenManager_resize(ScreenManager* this) {
   int y1_header = this->y1 + ScreenManager_headerHeight(this);
   int panels = this->panelCount;
   int lastX = 0;
   for (int i = 0; i < panels - 1; i++) {
      Panel* panel = this->panels->items[i];
      Panel_resize(panel, panel->w, LINES - y1_header + this->y2);
      Panel_move(panel, lastX, y1_header);
      lastX = panel->x + panel->w + 1;
   }
   Panel* panel = this->panels->items[panels - 1];
   Panel_resize(panel, COLS - lastX, LINES - y1_header + this->y2);
   Panel_move(panel, lastX, y1_header);
}

static void checkRecalculation(ScreenManager* this, double* oldTime, int* sortTimeout, bool* redraw, bool* rescan, bool* timedOut, bool* force_redraw) {
   Machine* host = this->host;
   struct timeval tv;
   realtimeNow(&tv, NULL);
   double newTime = ((double)tv.tv_sec * 10) + ((double)tv.tv_usec / 100000);
   *timedOut = (newTime - *oldTime > host->settings->delay);
   *rescan |= *timedOut;
   if (newTime < *oldTime) *rescan = true;
   if (*rescan) {
      *oldTime = newTime;
      int oldUidDigits = Row_uidDigits;
      int oldPidDigits = Row_pidDigits;
      if (!this->state->pauseUpdate && (*sortTimeout == 0 || host->settings->ss->treeView)) {
         host->needsSort = true;
         *sortTimeout = 1;
      }
      Machine_scan(host);
      if (!this->state->pauseUpdate) {
         bool ns = host->needsSort;
         Machine_scanProcesses(host);
         host->needsSort = ns;
      }
      Header_updateData(this->header);
      if (Row_uidDigits != oldUidDigits || Row_pidDigits != oldPidDigits) *force_redraw = true;
      *redraw = true;
   }
   if (*redraw) {
      Machine_rebuildPanel(host);
      if (!this->state->hideMeters) Header_draw(this->header);
   }
   *rescan = false;
}

static bool drawTab(int y, int* x, int l, const char* name, bool cur) {
   attrset(CRT_colors[cur ? SCREENS_CUR_BORDER : SCREENS_OTH_BORDER]);
   mvaddch(y, *x, '[');
   (*x)++;
   if (*x >= l) return false;
   int nameWidth = strnlen(name, l - *x);
   attrset(CRT_colors[cur ? SCREENS_CUR_TEXT : SCREENS_OTH_TEXT]);
   mvaddnstr(y, *x, name, nameWidth);
   *x += nameWidth;
   if (*x >= l) return false;
   attrset(CRT_colors[cur ? SCREENS_CUR_BORDER : SCREENS_OTH_BORDER]);
   mvaddch(y, *x, ']');
   *x += 2;
   if (*x >= l) return false;
   return true;
}

static void drawScreenTabs(ScreenManager* this) {
   Settings* s = this->host->settings;
   int cur = s->ssIndex;
   int l = COLS;
   Panel* panel = this->panels->items[0];
   int y = panel->y - 1;
   int x = 2;
   if (y < 0) return;
   if (this->name) {
      drawTab(y, &x, l, this->name, true);
      attrset(CRT_colors[RESET_COLOR]);
      return;
   }
   for (int i = 0; i < s->nScreens; i++) {
      if (!drawTab(y, &x, l, s->screens[i]->heading, i == cur)) break;
   }
   attrset(CRT_colors[RESET_COLOR]);
}

static void drawPanels(ScreenManager* this, int focus, bool force_redraw) {
