static bool collapseIntoParent(Panel* panel) {
   const Process* r = (Process*)Panel_getSelected(panel);
   if (!r) return false;
   int parent_id = Process_getGroupOrParent(r);
   for (int i = 0; i < Panel_size(panel); i++) {
      Process* p = (Process*)Panel_get(panel, i);
      if (p->pid == parent_id) {
