/* ---- affinity ---- */
typedef struct { Item super; char* text; int value; int cpu; } MaskItem;
static void MaskItem_display(const Item* cast, RStr* out) {
   const MaskItem* this = (const MaskItem*)cast;
   rs_append(out, CRT_colors[CHECK_BOX], "[");
   if (this->value == 2) rs_append(out, CRT_colors[CHECK_MARK], "x");
   else if (this->value == 1) rs_append(out, CRT_colors[CHECK_MARK], "o");
   else rs_append(out, CRT_colors[CHECK_MARK], " ");
   rs_append(out, CRT_colors[CHECK_BOX], "]");
   rs_append(out, CRT_colors[CHECK_TEXT], " ");
   rs_append(out, CRT_colors[CHECK_TEXT], this->text);
}
static void MaskItem_destroy(Item* cast) { MaskItem* this = (MaskItem*)cast; free(this->text); free(this); }
static const ItemClass MaskItem_class = { MaskItem_display, MaskItem_destroy, NULL };

static HandlerResult AffinityPanel_eventHandler(Panel* super, int ch) {
   MaskItem* selected = (MaskItem*)Panel_getSelected(super);
   switch (ch) {
   case KEY_MOUSE:
   case KEY_RECLICK:
   case ' ':
      if (selected) {
         selected->value = selected->value ? 0 : 2;
      }
      return HANDLED;
   case 0x0a:
   case 0x0d:
   case KEY_ENTER:
      return BREAK_LOOP;
   }
   return IGNORED;
}

static Htop_Reaction actionSetAffinity(State* st) {
   if (Settings_readonly) return HTOP_OK;
   if (st->host->activeCPUs == 1) return HTOP_OK;
   Process* p = (Process*)Panel_getSelected((Panel*)st->mainPanel);
   if (!p) return HTOP_OK;
   cpu_set_t cpuset;
   CPU_ZERO(&cpuset);
   if (sched_getaffinity(p->pid, sizeof(cpu_set_t), &cpuset) != 0) return HTOP_OK;
   Panel* panel = Panel_new(1, 1, 1, 1, true, FunctionBar_newEnterEsc("Set    ", "Cancel "));
   panel->eventHandler = AffinityPanel_eventHandler;
   Panel_setHeader(panel, "Use CPUs:");
   for (unsigned int i = 0; i < st->host->existingCPUs; i++) {
      MaskItem* m = xcalloc(1, sizeof(MaskItem));
      m->super.cls = &MaskItem_class;
      m->text = xasprintf("CPU %d", Settings_cpuId(st->host->settings, i));
      m->value = CPU_ISSET(i, &cpuset) ? 2 : 0;
      m->cpu = i;
      Panel_add(panel, (Item*)m);
   }
   int width = 14;
   const void* set = Action_pickFromVector(st, panel, width, true);
   if (set) {
      cpu_set_t ns;
      CPU_ZERO(&ns);
      for (int i = 0; i < Panel_size(panel); i++) {
         MaskItem* m = (MaskItem*)Panel_get(panel, i);
         if (m->value) CPU_SET(m->cpu, &ns);
      }
      bool ok = true;
      Panel* mp = (Panel*)st->mainPanel;
      bool anyTagged = false;
      for (int i = 0; i < Panel_size(mp); i++) {
         Process* q = (Process*)Panel_get(mp, i);
         if (q->tag) { anyTagged = true; ok &= sched_setaffinity(q->pid, sizeof(cpu_set_t), &ns) == 0; }
      }
      if (!anyTagged) {
         Process* q = (Process*)Panel_getSelected(mp);
         if (q) ok &= sched_setaffinity(q->pid, sizeof(cpu_set_t), &ns) == 0;
      }
      if (!ok) beep();
   }
   Panel_delete(panel);
   return HTOP_REFRESH | HTOP_REDRAW_BAR | HTOP_UPDATE_PANELHDR;
}

/* ---- scheduling policy ---- */
static const struct { int id; const char* name; } policies[] = {
   { SCHED_OTHER, "Other" }, { SCHED_FIFO, "FiFo" }, { SCHED_RR, "RoundRobin" }, { SCHED_BATCH, "Batch" }, { SCHED_IDLE, "Idle" },
};
static bool policyResetOnFork = false;

static HandlerResult SchedulingPanel_eventHandler(Panel* super, int ch) {
   if (ch == ' ' || ch == KEY_RECLICK || ch == 13 || ch == KEY_ENTER) {
      if (Panel_getSelectedIndex(super) == 0) {
         policyResetOnFork = !policyResetOnFork;
         ListItem* li = (ListItem*)Panel_get(super, 0);
         free(li->value);
         li->value = xstrdup(policyResetOnFork ? "Reset on fork: on" : "Reset on fork: off");
         super->needsRedraw = true;
         return HANDLED;
      }
      if (ch == ' ') return HANDLED;
   }
   return IGNORED;
}

static bool setSchedFn(Process* p, int arg) {
   if (Settings_readonly) return false;
   int policy = arg & 0xffff;
   int prio = arg >> 16;
   struct sched_param param = { .sched_priority = prio };
   if (policyResetOnFork) policy |= SCHED_RESET_ON_FORK;
   return sched_setscheduler(p->pid, policy, &param) == 0;
}

static Htop_Reaction actionSetSchedPolicy(State* st) {
   if (Settings_readonly) return HTOP_OK;
   Process* p = (Process*)Panel_getSelected((Panel*)st->mainPanel);
   if (!p) return HTOP_OK;
   int cur = sched_getscheduler(p->pid);
   if (cur >= 0) { policyResetOnFork = (cur & SCHED_RESET_ON_FORK) != 0; cur &= ~SCHED_RESET_ON_FORK; }
   Panel* panel = Panel_new(1, 1, 1, 1, true, FunctionBar_newEnterEsc("Select ", "Cancel "));
   panel->eventHandler = SchedulingPanel_eventHandler;
   Panel_setHeader(panel, "New policy:");
   Panel_add(panel, (Item*)ListItem_new(policyResetOnFork ? "Reset on fork: on" : "Reset on fork: off", -1));
   int selection = 1;
   for (unsigned int i = 0; i < ARRLEN(policies); i++) {
      Panel_add(panel, (Item*)ListItem_new(policies[i].name, policies[i].id));
      if (policies[i].id == cur) selection = i + 1;
   }
   Panel_setSelected(panel, selection);
   const ListItem* policy = (const ListItem*)Action_pickFromVector(st, panel, 18, true);
   if (policy && policy->key >= 0) {
      int prio = 0;
      if (policy->key == SCHED_FIFO || policy->key == SCHED_RR) {
         Panel* pp = Panel_new(1, 1, 1, 1, true, FunctionBar_newEnterEsc("Select ", "Cancel "));
         Panel_setHeader(pp, "Priority:");
         int mn = sched_get_priority_min(policy->key), mx = sched_get_priority_max(policy->key);
         for (int i = mn; i <= mx; i++) {
            char buf[16]; xsnprintf(buf, sizeof(buf), "%d", i);
            Panel_add(pp, (Item*)ListItem_new(buf, i));
         }
         const ListItem* pr = (const ListItem*)Action_pickFromVector(st, pp, 14, true);
         if (pr) prio = pr->key;
         else { Panel_delete(pp); Panel_delete(panel); return HTOP_REFRESH | HTOP_REDRAW_BAR | HTOP_UPDATE_PANELHDR; }
         Panel_delete(pp);
      }
      bool ok = MainPanel_foreachRow(st->mainPanel, setSchedFn, policy->key | (prio << 16), NULL);
      if (!ok) beep();
   }
   Panel_delete(panel);
   return HTOP_REFRESH | HTOP_REDRAW_BAR | HTOP_UPDATE_PANELHDR;
}

/* ---- IO priority ---- */
static Htop_Reaction actionSetIOPriority(State* st) {
   if (Settings_readonly) return HTOP_OK;
   Process* p = (Process*)Panel_getSelected((Panel*)st->mainPanel);
   if (!p) return HTOP_OK;
   int currPrio = Process_getIOPriority(p);
   Panel* panel = Panel_new(1, 1, 1, 1, true, FunctionBar_newEnterEsc("Set    ", "Cancel "));
   Panel_setHeader(panel, "IO Priority:");
   Panel_add(panel, (Item*)ListItem_new("None (based on nice)", IOPriority_None));
   if (currPrio == IOPriority_None) Panel_setSelected(panel, 0);
   static const struct { int klass; const char* name; } classes[] = {
      { IOPRIO_CLASS_RT, "Realtime" }, { IOPRIO_CLASS_BE, "Best-effort" }, { 0, NULL }
   };
   for (int c = 0; classes[c].name; c++) {
      for (int i = 0; i < 8; i++) {
         char name[50];
         xsnprintf(name, sizeof(name), "%s %d %s", classes[c].name, i, i == 0 ? "(High)" : (i == 7 ? "(Low)" : ""));
         int ioprio = IOPriority_tuple(classes[c].klass, i);
         Panel_add(panel, (Item*)ListItem_new(name, ioprio));
         if (currPrio == ioprio) Panel_setSelected(panel, Panel_size(panel) - 1);
      }
   }
   Panel_add(panel, (Item*)ListItem_new("Idle", IOPriority_Idle));
   if (currPrio == IOPriority_Idle) Panel_setSelected(panel, Panel_size(panel) - 1);
   const void* set = Action_pickFromVector(st, panel, 20, true);
   if (set) {
      const ListItem* sel = (const ListItem*)Panel_getSelected(panel);
      int ioprio2 = sel ? sel->key : IOPriority_None;
      bool anyTagged = false, ok = true;
      Panel* mp = (Panel*)st->mainPanel;
      for (int i = 0; i < Panel_size(mp); i++) {
         Process* q = (Process*)Panel_get(mp, i);
         if (q->tag) { anyTagged = true; ok &= Process_setIOPriority(q, ioprio2); }
      }
      if (!anyTagged) { Process* q = (Process*)Panel_getSelected(mp); if (q) ok &= Process_setIOPriority(q, ioprio2); }
      if (!ok) beep();
   }
   Panel_delete(panel);
   return HTOP_REFRESH | HTOP_REDRAW_BAR | HTOP_UPDATE_PANELHDR;
}

static bool killFn(Process* p, int sig) { return Process_sendSignal(p, sig); }

static Htop_Reaction actionKill(State* st) {
   if (Settings_readonly) return HTOP_OK;
   static int preSelectedSignal = 15;
   Panel* signalsPanel = SignalsPanel_new(preSelectedSignal);
   const ListItem* sgn = (ListItem*)Action_pickFromVector(st, signalsPanel, 14, true);
   if (sgn && sgn->key != 0) {
      preSelectedSignal = sgn->key;
      Panel_setHeader((Panel*)st->mainPanel, "Sending...");
      Panel_draw((Panel*)st->mainPanel, false, true, true, State_hideFunctionBar(st));
      refresh();
      bool ok = MainPanel_foreachRow(st->mainPanel, killFn, sgn->key, NULL);
      if (!ok) beep();
      napms(500);
   }
   Panel_delete(signalsPanel);
   return HTOP_REFRESH | HTOP_REDRAW_BAR | HTOP_UPDATE_PANELHDR;
}

