actions.command:
cd /workspace/src; cat > actions.c <<'EOF'
#include "app.h"
#include "crt.h"
#include <pwd.h>
#include <sched.h>
#include <signal.h>
#include <unistd.h>

typedef struct { int number; const char* name; } SignalItem;
static const SignalItem Platform_signals[] = {
   { 0, " 0 Cancel" }, { 1, " 1 SIGHUP" }, { 2, " 2 SIGINT" }, { 3, " 3 SIGQUIT" }, { 4, " 4 SIGILL" },
   { 5, " 5 SIGTRAP" }, { 6, " 6 SIGABRT" }, { 6, " 6 SIGIOT" }, { 7, " 7 SIGBUS" }, { 8, " 8 SIGFPE" },
   { 9, " 9 SIGKILL" }, { 10, "10 SIGUSR1" }, { 11, "11 SIGSEGV" }, { 12, "12 SIGUSR2" }, { 13, "13 SIGPIPE" },
   { 14, "14 SIGALRM" }, { 15, "15 SIGTERM" }, { 16, "16 SIGSTKFLT" }, { 17, "17 SIGCHLD" }, { 18, "18 SIGCONT" },
   { 19, "19 SIGSTOP" }, { 20, "20 SIGTSTP" }, { 21, "21 SIGTTIN" }, { 22, "22 SIGTTOU" }, { 23, "23 SIGURG" },
   { 24, "24 SIGXCPU" }, { 25, "25 SIGXFSZ" }, { 26, "26 SIGVTALRM" }, { 27, "27 SIGPROF" }, { 28, "28 SIGWINCH" },
   { 29, "29 SIGIO" }, { 29, "29 SIGPOLL" }, { 30, "30 SIGPWR" }, { 31, "31 SIGSYS" },
};

static Panel* SignalsPanel_new(int preSelectedSignal) {
   Panel* this = Panel_new(1, 1, 1, 1, true, FunctionBar_newEnterEsc("Send   ", "Cancel "));
   int defaultPosition = 15;
   int i;
   int n = ARRLEN(Platform_signals);
   for (i = 0; i < n; i++) {
      Panel_set(this, i, (Item*)ListItem_new(Platform_signals[i].name, Platform_signals[i].number));
      if (Platform_signals[i].number == preSelectedSignal) defaultPosition = i;
   }
   if (SIGRTMAX - SIGRTMIN <= 100) {
      char buf[16];
      for (int sig = SIGRTMIN; sig <= SIGRTMAX; i++, sig++) {
         int k = sig - SIGRTMIN;
         xsnprintf(buf, sizeof(buf), "%2d SIGRTMIN%-+3d", sig, k);
         if (k == 0) buf[11] = '\0';
         Panel_set(this, i, (Item*)ListItem_new(buf, sig));
      }
   }
   Panel_setHeader(this, "Send signal:");
   Panel_setSelected(this, defaultPosition);
   return this;
}

Htop_Reaction Action_setSortKey(Settings* settings, int sortKey) {
   ScreenSettings_setSortKey(settings->ss, sortKey);
   return HTOP_REFRESH | HTOP_SAVE_SETTINGS | HTOP_UPDATE_PANELHDR | HTOP_KEEP_FOLLOWING;
}

Item* Action_pickFromVector(State* st, Panel* list, int x, bool follow) {
   MainPanel* mainPanel = st->mainPanel;
   Header* header = st->header;
   Machine* host = st->host;
   int y = mainPanel->super.y;
   ScreenManager* scr = ScreenManager_new(header, host, st, false);
   scr->allowFocusChange = false;
   ScreenManager_add(scr, list, x);
   ScreenManager_add(scr, (Panel*)mainPanel, -1);
   Panel* panelFocus;
   int ch;
   bool unfollow = false;
   int row = follow ? MainPanel_selectedRow(mainPanel) : -1;
   if (follow && host->following == -1) {
      host->following = row;
      unfollow = true;
   }
   ScreenManager_run(scr, &panelFocus, &ch, NULL);
   if (unfollow) host->following = -1;
   ScreenManager_delete(scr);
   Panel_move((Panel*)mainPanel, 0, y);
   Panel_resize((Panel*)mainPanel, COLS, LINES - y - 1);
   if (panelFocus == list && ch == 13) {
      if (follow) {
         const Process* selected = (const Process*)Panel_getSelected((Panel*)mainPanel);
         if (selected && selected->pid == row) return Panel_getSelected(list);
         beep();
      } else {
         return Panel_getSelected(list);
      }
   }
   return NULL;
}

bool Action_setUserOnly(const char* userName, uid_t* userId) {
   const struct passwd* user = getpwnam(userName);
   if (user) { *userId = user->pw_uid; return true; }
   *userId = (uid_t)-1;
   return false;
}

static bool changePriorityFn(Process* p, int delta) { return Process_changePriorityBy(p, delta); }

static bool changePriority(MainPanel* panel, int delta) {
   bool anyTagged;
   bool ok = MainPanel_foreachRow(panel, changePriorityFn, delta, &anyTagged);
   if (!ok) beep();
   return anyTagged;
}

static bool changeAutogroupFn(Process* p, int delta) {
   if (Settings_readonly) return false;
   char path[64];
   snprintf(path, sizeof(path), "/proc/%d/autogroup", p->pid);
   FILE* f = fopen(path, "r");
   if (!f) return false;
   long id; int nice;
   int r = fscanf(f, "/autogroup-%ld nice %d", &id, &nice);
   fclose(f);
   if (r != 2) return false;
   f = fopen(path, "w");
   if (!f) return false;
   int ok = fprintf(f, "%d", nice + delta) > 0;
   if (fclose(f) != 0) ok = 0;
   return ok;
}

static void tagAllChildren(Panel* panel, Process* parent) {
   parent->tag = true;
   int pid = parent->pid;
   for (int i = 0; i < Panel_size(panel); i++) {
      Process* p = (Process*)Panel_get(panel, i);
      if (!p->tag && Process_getGroupOrParent(p) == pid) tagAllChildren(panel, p);
   }
}

static bool expandCollapse(Panel* panel) {
   Process* p = (Process*)Panel_getSelected(panel);
   if (!p) return false;
   p->showChildren = !p->showChildren;
   return true;
}

static bool collapseIntoParent(Panel* panel) {
   const Process* r = (Process*)Panel_getSelected(panel);
   if (!r) return false;
   int parent_id = Process_getGroupOrParent(r);
   for (int i = 0; i < Panel_size(panel); i++) {
      Process* p = (Process*)Panel_get(panel, i);
      if (p->pid == parent_id) {
         p->showChildren = false;
         Panel_setSelected(panel, i);
         return true;
      }
   }
   return false;
}

static Htop_Reaction actionSetSortColumn(State* st) {
   Htop_Reaction reaction = HTOP_OK;
   Panel* sortPanel = Panel_new(0, 0, 0, 0, true, FunctionBar_newEnterEsc("Sort   ", "Cancel "));
   Panel_setHeader(sortPanel, "Sort by");
   Machine* host = st->host;
   Settings* settings = host->settings;
   const int* fields = settings->ss->fields;
   for (int i = 0; fields[i]; i++) {
      char* name = str_trim(Fields[fields[i]].name);
      Panel_add(sortPanel, (Item*)ListItem_new(name, fields[i]));
      if (fields[i] == ScreenSettings_getActiveSortKey(settings->ss)) Panel_setSelected(sortPanel, i);
      free(name);
   }
   const ListItem* field = (const ListItem*)Action_pickFromVector(st, sortPanel, 14, false);
   if (field) reaction |= Action_setSortKey(settings, field->key);
   Panel_delete(sortPanel);
   host->needsSort = true;
   return reaction | HTOP_REFRESH | HTOP_REDRAW_BAR | HTOP_UPDATE_PANELHDR;
}

static Htop_Reaction actionSortByPID(State* st) { return Action_setSortKey(st->host->settings, PID); }
static Htop_Reaction actionSortByMemory(State* st) { return Action_setSortKey(st->host->settings, PERCENT_MEM); }
static Htop_Reaction actionSortByCPU(State* st) { return Action_setSortKey(st->host->settings, PERCENT_CPU); }
static Htop_Reaction actionSortByTime(State* st) { return Action_setSortKey(st->host->settings, TIME); }

static Htop_Reaction actionToggleKernelThreads(State* st) {
   Settings* s = st->host->settings;
   s->hideKernelThreads = !s->hideKernelThreads;
   s->lastUpdate++;
   Machine_scanProcesses(st->host);
   return HTOP_RECALCULATE | HTOP_SAVE_SETTINGS | HTOP_KEEP_FOLLOWING;
}
static Htop_Reaction actionToggleUserlandThreads(State* st) {
   Settings* s = st->host->settings;
   s->hideUserlandThreads = !s->hideUserlandThreads;
   s->lastUpdate++;
   Machine_scanProcesses(st->host);
   return HTOP_RECALCULATE | HTOP_SAVE_SETTINGS | HTOP_KEEP_FOLLOWING;
}
static Htop_Reaction actionToggleRunningInContainer(State* st) {
   Settings* s = st->host->settings;
   s->hideRunningInContainer = !s->hideRunningInContainer;
   s->lastUpdate++;
   return HTOP_RECALCULATE | HTOP_SAVE_SETTINGS | HTOP_KEEP_FOLLOWING;
}
static Htop_Reaction actionToggleProgramPath(State* st) {
   Settings* s = st->host->settings;
   s->showProgramPath = !s->showProgramPath;
   s->lastUpdate++;
   return HTOP_REFRESH | HTOP_SAVE_SETTINGS;
}
static Htop_Reaction actionToggleMergedCommand(State* st) {
   Settings* s = st->host->settings;
   s->showMergedCommand = !s->showMergedCommand;
   s->lastUpdate++;
   return HTOP_REFRESH | HTOP_SAVE_SETTINGS | HTOP_UPDATE_PANELHDR;
}
static Htop_Reaction actionToggleTreeView(State* st) {
   ScreenSettings* ss = st->host->settings->ss;
   ss->treeView = !ss->treeView;
   if (!ss->allBranchesCollapsed) Machine_expandTree(st->host);
   st->host->needsSort = true;
   return HTOP_REFRESH | HTOP_SAVE_SETTINGS | HTOP_KEEP_FOLLOWING | HTOP_REDRAW_BAR | HTOP_UPDATE_PANELHDR;
}
static Htop_Reaction actionToggleHideMeters(State* st) {
   st->hideMeters = !st->hideMeters;
   return HTOP_RESIZE | HTOP_KEEP_FOLLOWING;
}
static Htop_Reaction actionExpandOrCollapseAllBranches(State* st) {
   ScreenSettings* ss = st->host->settings->ss;
   if (!ss->treeView) return HTOP_OK;
   ss->allBranchesCollapsed = !ss->allBranchesCollapsed;
   if (ss->allBranchesCollapsed) Machine_collapseAllBranches(st->host);
   else Machine_expandTree(st->host);
   return HTOP_REFRESH | HTOP_SAVE_SETTINGS;
}
static Htop_Reaction actionIncFilter(State* st) {
   MainPanel* mp = st->mainPanel;
   IncSet* inc = mp->inc;
   IncSet_activate(inc, INC_FILTER, (Panel*)mp);
   free(st->host->incFilter);
   const char* f = IncSet_filter(inc);
   st->host->incFilter = f ? xstrdup(f) : NULL;
   return HTOP_REFRESH | HTOP_KEEP_FOLLOWING;
}
static Htop_Reaction actionIncSearch(State* st) {
   IncSet_reset(st->mainPanel->inc, INC_SEARCH);
   IncSet_activate(st->mainPanel->inc, INC_SEARCH, (Panel*)st->mainPanel);
   return HTOP_REFRESH | HTOP_KEEP_FOLLOWING;
}
static Htop_Reaction actionHigherPriority(State* st) {
   if (Settings_readonly) return HTOP_OK;
   bool changed = changePriority(st->mainPanel, -1);
   return changed ? HTOP_REFRESH : HTOP_OK;
}
static Htop_Reaction actionLowerPriority(State* st) {
   if (Settings_readonly) return HTOP_OK;
   bool changed = changePriority(st->mainPanel, 1);
   return changed ? HTOP_REFRESH : HTOP_OK;
}
static Htop_Reaction actionHigherAutogroupPriority(State* st) {
   if (Settings_readonly) return HTOP_OK;
   bool anyTagged;
   bool ok = MainPanel_foreachRow(st->mainPanel, changeAutogroupFn, -1, &anyTagged);
   if (!ok) beep();
   return anyTagged ? HTOP_REFRESH : HTOP_OK;
}
static Htop_Reaction actionLowerAutogroupPriority(State* st) {
   if (Settings_readonly) return HTOP_OK;
   bool anyTagged;
   bool ok = MainPanel_foreachRow(st->mainPanel, changeAutogroupFn, 1, &anyTagged);
   if (!ok) beep();
   return anyTagged ? HTOP_REFRESH : HTOP_OK;
}
static Htop_Reaction actionInvertSortOrder(State* st) {
   ScreenSettings_invertSortOrder(st->host->settings->ss);
   st->host->needsSort = true;
   return HTOP_REFRESH | HTOP_SAVE_SETTINGS | HTOP_KEEP_FOLLOWING | HTOP_UPDATE_PANELHDR;
}
static Htop_Reaction actionExpandOrCollapse(State* st) {
   if (!st->host->settings->ss->treeView) return HTOP_OK;
   bool changed = expandCollapse((Panel*)st->mainPanel);
   return changed ? HTOP_RECALCULATE : HTOP_OK;
}
static Htop_Reaction actionCollapseIntoParent(State* st) {
   if (!st->host->settings->ss->treeView) return HTOP_OK;
   bool changed = collapseIntoParent((Panel*)st->mainPanel);
   return changed ? HTOP_RECALCULATE : HTOP_OK;
}
static Htop_Reaction actionExpandCollapseOrSortColumn(State* st) {
   return st->host->settings->ss->treeView ? actionExpandOrCollapse(st) : actionSetSortColumn(st);
}

static void setActiveScreen(Settings* settings, State* st, int idx) {
   settings->ss = settings->screens[idx];
   st->host->needsSort = true;
   (void)st;
}
static Htop_Reaction actionNextScreen(State* st) {
   Settings* s = st->host->settings;
   s->ssIndex++;
   if (s->ssIndex == s->nScreens) s->ssIndex = 0;
   setActiveScreen(s, st, s->ssIndex);
   return HTOP_UPDATE_PANELHDR | HTOP_REFRESH | HTOP_REDRAW_BAR;
}
static Htop_Reaction actionPrevScreen(State* st) {
   Settings* s = st->host->settings;
   if (s->ssIndex == 0) s->ssIndex = s->nScreens - 1;
   else s->ssIndex--;
   setActiveScreen(s, st, s->ssIndex);
   return HTOP_UPDATE_PANELHDR | HTOP_REFRESH | HTOP_REDRAW_BAR;
}
static Htop_Reaction actionQuit(State* st) { (void)st; return HTOP_QUIT; }

/* ---- affinity ---- */
typedef struct { Item super; char* text; int value; int cpu; } MaskItem;
static void MaskItem_display(const Item* cast, RStr* out) {
   const MaskItem* this = (const MaskItem*)cast;
   rs_append(out, CRT_colors[CHECK_BOX], "[");
   if (this->value == 2) rs_append(out, CRT_colors[CHECK_MARK], "x");
   else if (this->value == 1) rs_append(out, CRT_colors[CHECK_MARK], "o");
   else rs_append(out, CRT_colors[CHECK_MARK], " ");
   rs_append(out, CRT_colors[CHECK_BOX], "]");
   rs_append(out, CRT_colors[CHECK_TEXT], " ");
   rs_append(out, CRT_colors[CHECK_TEXT], this->text);
}
static void MaskItem_destroy(Item* cast) { MaskItem* this = (MaskItem*)cast; free(this->text); free(this); }
static const ItemClass MaskItem_class = { MaskItem_display, MaskItem_destroy, NULL };

static HandlerResult AffinityPanel_eventHandler(Panel* super, int ch) {
   MaskItem* selected = (MaskItem*)Panel_getSelected(super);
   switch (ch) {
   case KEY_MOUSE:
   case KEY_RECLICK:
   case ' ':
      if (selected) {
         selected->value = selected->value ? 0 : 2;
      }
      return HANDLED;
   case 0x0a:
   case 0x0d:
   case KEY_ENTER:
      return BREAK_LOOP;
   }
   return IGNORED;
}

static Htop_Reaction actionSetAffinity(State* st) {
   if (Settings_readonly) return HTOP_OK;
   if (st->host->activeCPUs == 1) return HTOP_OK;
   Process* p = (Process*)Panel_getSelected((Panel*)st->mainPanel);
   if (!p) return HTOP_OK;
   cpu_set_t cpuset;
   CPU_ZERO(&cpuset);
   if (sched_getaffinity(p->pid, sizeof(cpu_set_t), &cpuset) != 0) return HTOP_OK;
   Panel* panel = Panel_new(1, 1, 1, 1, true, FunctionBar_newEnterEsc("Set    ", "Cancel "));
   panel->eventHandler = AffinityPanel_eventHandler;
   Panel_setHeader(panel, "Use CPUs:");
   for (unsigned int i = 0; i < st->host->existingCPUs; i++) {
      MaskItem* m = xcalloc(1, sizeof(MaskItem));
      m->super.cls = &MaskItem_class;
      m->text = xasprintf("CPU %d", Settings_cpuId(st->host->settings, i));
      m->value = CPU_ISSET(i, &cpuset) ? 2 : 0;
      m->cpu = i;
      Panel_add(panel, (Item*)m);
   }
   int width = 14;
   const void* set = Action_pickFromVector(st, panel, width, true);
   if (set) {
      cpu_set_t ns;
      CPU_ZERO(&ns);
      for (int i = 0; i < Panel_size(panel); i++) {
         MaskItem* m = (MaskItem*)Panel_get(panel, i);
         if (m->value) CPU_SET(m->cpu, &ns);
      }
      bool ok = true;
      Panel* mp = (Panel*)st->mainPanel;
      bool anyTagged = false;
      for (int i = 0; i < Panel_size(mp); i++) {
         Process* q = (Process*)Panel_get(mp, i);
         if (q->tag) { anyTagged = true; ok &= sched_setaffinity(q->pid, sizeof(cpu_set_t), &ns) == 0; }
      }
      if (!anyTagged) {
         Process* q = (Process*)Panel_getSelected(mp);
         if (q) ok &= sched_setaffinity(q->pid, sizeof(cpu_set_t), &ns) == 0;
      }
      if (!ok) beep();
   }
   Panel_delete(panel);
   return HTOP_REFRESH | HTOP_REDRAW_BAR | HTOP_UPDATE_PANELHDR;
}

/* ---- scheduling policy ---- */
static const struct { int id; const char* name; } policies[] = {
   { SCHED_OTHER, "Other" }, { SCHED_FIFO, "FiFo" }, { SCHED_RR, "RoundRobin" }, { SCHED_BATCH, "Batch" }, { SCHED_IDLE, "Idle" },
};
static bool policyResetOnFork = false;

static HandlerResult SchedulingPanel_eventHandler(Panel* super, int ch) {
   if (ch == ' ' || ch == KEY_RECLICK || ch == 13 || ch == KEY_ENTER) {
      if (Panel_getSelectedIndex(super) == 0) {
         policyResetOnFork = !policyResetOnFork;
         ListItem* li = (ListItem*)Panel_get(super, 0);
         free(li->value);
         li->value = xstrdup(policyResetOnFork ? "Reset on fork: on" : "Reset on fork: off");
         super->needsRedraw = true;
         return HANDLED;
      }
      if (ch == ' ') return HANDLED;
   }
   return IGNORED;
}

static bool setSchedFn(Process* p, int arg) {
   if (Settings_readonly) return false;
   int policy = arg & 0xffff;
   int prio = arg >> 16;
   struct sched_param param = { .sched_priority = prio };
   if (policyResetOnFork) policy |= SCHED_RESET_ON_FORK;
   return sched_setscheduler(p->pid, policy, &param) == 0;
}

static Htop_Reaction actionSetSchedPolicy(State* st) {
   if (Settings_readonly) return HTOP_OK;
   Process* p = (Process*)Panel_getSelected((Panel*)st->mainPanel);
   if (!p) return HTOP_OK;
   int cur = sched_getscheduler(p->pid);
   if (cur >= 0) { policyResetOnFork = (cur & SCHED_RESET_ON_FORK) != 0; cur &= ~SCHED_RESET_ON_FORK; }
   Panel* panel = Panel_new(1, 1, 1, 1, true, FunctionBar_newEnterEsc("Select ", "Cancel "));
   panel->eventHandler = SchedulingPanel_eventHandler;
   Panel_setHeader(panel, "New policy:");
   Panel_add(panel, (Item*)ListItem_new(policyResetOnFork ? "Reset on fork: on" : "Reset on fork: off", -1));
   int selection = 1;
   for (unsigned int i = 0; i < ARRLEN(policies); i++) {
      Panel_add(panel, (Item*)ListItem_new(policies[i].name, policies[i].id));
      if (policies[i].id == cur) selection = i + 1;
   }
   Panel_setSelected(panel, selection);
   const ListItem* policy = (const ListItem*)Action_pickFromVector(st, panel, 18, true);
   if (policy && policy->key >= 0) {
      int prio = 0;
      if (policy->key == SCHED_FIFO || policy->key == SCHED_RR) {
         Panel* pp = Panel_new(1, 1, 1, 1, true, FunctionBar_newEnterEsc("Select ", "Cancel "));
         Panel_setHeader(pp, "Priority:");
         int mn = sched_get_priority_min(policy->key), mx = sched_get_priority_max(policy->key);
         for (int i = mn; i <= mx; i++) {
            char buf[16]; xsnprintf(buf, sizeof(buf), "%d", i);
            Panel_add(pp, (Item*)ListItem_new(buf, i));
         }
         const ListItem* pr = (const ListItem*)Action_pickFromVector(st, pp, 14, true);
         if (pr) prio = pr->key;
         else { Panel_delete(pp); Panel_delete(panel); return HTOP_REFRESH | HTOP_REDRAW_BAR | HTOP_UPDATE_PANELHDR; }
         Panel_delete(pp);
      }
      bool ok = MainPanel_foreachRow(st->mainPanel, setSchedFn, policy->key | (prio << 16), NULL);
