}
static void LocksScreen_scan(InfoScreen* this) {
   Panel* panel = this->display;
   int idx = MAXI(Panel_getSelectedIndex(panel), 0);
   bool owns = panel->ownsItems; panel->ownsItems = false; Panel_prune(panel); panel->ownsItems = owns;
   int count = 0;
   FILE* f = fopen("/proc/locks", "r");
   if (f) {
      char line[1024];
      while (fgets(line, sizeof(line), f)) {
         int id; char locktype[32], exclusion[32], rw[32]; int pid; unsigned int maj, min; unsigned long long inode;
         char start[64], end[64];
         char* p = line;
         if (sscanf(p, "%d: %31s %31s %31s %d %x:%x:%llu %63s %63s", &id, locktype, exclusion, rw, &pid, &maj, &min, &inode, start, end) != 10) continue;
         if (pid != this->process->pid) continue;
         char entry[2048];
         snprintf(entry, sizeof(entry), "%5d %-10s %-10s %-10s %02x:%02x %10llu %19s %19s  %s", id, locktype, exclusion, rw, maj, min, inode, start, end, "<N/A>");
         InfoScreen_addLine(this, entry);
         count++;
      }
      fclose(f);
   }
   if (!count) InfoScreen_addLine(this, "No locks have been found for the selected process.");
   Panel_setSelected(panel, idx);
}
void InfoScreen_runLocks(State* st, Process* p) {
