static Settings* g_settings = NULL;

void App_onTerminate(int sgn) {
   CRT_done();
   if (!g_settings || !g_settings->changed) _exit(0);
   const char* signal_str = strsignal(sgn);
   if (!signal_str) signal_str = "unknown reason";
   char buf[512];
   int n = snprintf(buf, sizeof(buf), "A signal %d (%s) was received, exiting without persisting settings to htoprc.\n", sgn, signal_str);
   if (n > 0) { ssize_t r = write(STDERR_FILENO, buf, n); (void)r; }
   _exit(0);
