typedef struct {
   int delay;
   bool useColors;
   bool enableMouse;
   bool treeView;
   bool allowUnicode;
   bool highlightChanges;
   int highlightDelaySecs;
   int sortKey;
   char* commFilter;
   uid_t userId;
   int* pidList; int pidCount;
   int iterationsRemaining;
   bool hideMeters;
   bool hideFunctionBar;
   bool readonly;
} Flags;

static void printVersionFlag(const char* name) {
   (void)name;
   printf("htop " VERSION_STR "\n");
}

static void printHelpFlag(const char* name) {
   (void)name;
   printf("htop " VERSION_STR "\n"
          "(C) 2004-2019 Hisham Muhammad. (C) 2020-2026 htop dev team.\n"
          "Released under the GNU GPLv2+.\n\n"
          "-C --no-color                   Use a monochrome color scheme\n"
          "-d --delay=DELAY                Set the delay between updates, in tenths of seconds\n"
          "-F --filter=FILTER              Show only the commands matching the given filter\n"
          "   --no-function-bar             Hide the function bar\n"
          "-h --help                       Print this help screen\n"
          "-H --highlight-changes[=DELAY]  Highlight new and old processes\n"
          "-M --no-mouse                   Disable the mouse\n"
          "   --no-meters                  Hide meters\n"
          "-n --max-iterations=NUMBER      Exit htop after NUMBER iterations/frame updates\n"
          "-p --pid=PID[,PID,PID...]       Show only the given PIDs\n"
          "   --readonly                   Disable all system and process changing features\n"
          "-s --sort-key=COLUMN            Sort by COLUMN in list view (try --sort-key=help for a list)\n"
          "-t --tree                       Show the tree view (can be combined with -s)\n"
          "-u --user[=USERNAME]            Show only processes for a given user (or $USER)\n"
          "-U --no-unicode                 Do not use unicode but plain ASCII\n"
          "-V --version                    Print version info\n"
          "\n"
          "Press F1 inside htop for online help.\n"
          "See 'man htop' for more information.\n");
}

enum { ARG_OK = 0, ARG_ERROR_EXIT, ARG_OK_EXIT };

static int parseArguments(int argc, char** argv, Flags* flags) {
   *flags = (Flags) {
      .delay = -1, .useColors = true, .enableMouse = true, .treeView = false, .allowUnicode = true,
      .highlightChanges = false, .highlightDelaySecs = -1, .sortKey = 0, .commFilter = NULL,
      .userId = (uid_t)-1, .pidList = NULL, .pidCount = 0, .iterationsRemaining = -1,
      .hideMeters = false, .hideFunctionBar = false, .readonly = false,
   };
   static const struct option long_opts[] = {
      {"help",       no_argument,         0, 'h'},
      {"version",    no_argument,         0, 'V'},
      {"delay",      required_argument,   0, 'd'},
      {"sort-key",   required_argument,   0, 's'},
      {"tree",       no_argument,         0, 't'},
      {"user",       optional_argument,   0, 'u'},
      {"no-color",   no_argument,         0, 'C'},
      {"no-colour",  no_argument,         0, 'C'},
      {"no-mouse",   no_argument,         0, 'M'},
      {"no-unicode", no_argument,         0, 'U'},
      {"pid",        required_argument,   0, 'p'},
      {"filter",     required_argument,   0, 'F'},
      {"highlight-changes", optional_argument, 0, 'H'},
      {"max-iterations", required_argument, 0, 'n'},
      {"readonly",   no_argument,         0, 128},
      {"no-meters",  no_argument,         0, 129},
      {"no-functionbar", no_argument,     0, 130},
      {"no-function-bar", no_argument,    0, 130},
      {0, 0, 0, 0}
   };
   int opt, opti = 0;
   while ((opt = getopt_long(argc, argv, "hVMCs:td:n:u::Up:F:H::", long_opts, &opti))) {
      if (opt == EOF) break;
      switch (opt) {
      case 'h':
         printHelpFlag(argv[0]);
         return ARG_OK_EXIT;
      case 'V':
         printVersionFlag(argv[0]);
         return ARG_OK_EXIT;
      case 's':
         if (str_eq(optarg, "help")) {
            for (int j = 1; j < LAST_PROCESSFIELD; j++) {
               const char* name = Fields[j].name;
               const char* description = Fields[j].description;
               if (name) printf("%19s %s\n", name, description);
            }
            return ARG_OK_EXIT;
         }
         flags->sortKey = 0;
         for (int j = 1; j < LAST_PROCESSFIELD; j++) {
            if (Fields[j].name == NULL) continue;
            if (str_eq(optarg, Fields[j].name)) { flags->sortKey = j; break; }
         }
         if (flags->sortKey == 0) {
            fprintf(stderr, "Error: invalid column \"%s\".\n", optarg);
            return ARG_ERROR_EXIT;
         }
         break;
      case 'd':
         if (sscanf(optarg, "%16d", &flags->delay) == 1) {
            if (flags->delay < 1) flags->delay = 1;
            if (flags->delay > 100) flags->delay = 100;
         } else {
            fprintf(stderr, "Error: invalid delay value \"%s\".\n", optarg);
            return ARG_ERROR_EXIT;
         }
         break;
      case 'n':
         if (sscanf(optarg, "%d", &flags->iterationsRemaining) == 1) {
            if (flags->iterationsRemaining <= 0) {
               fprintf(stderr, "Error: maximum iteration count must be positive.\n");
               return ARG_ERROR_EXIT;
            }
         } else {
            fprintf(stderr, "Error: invalid maximum iteration count \"%s\".\n", optarg);
            return ARG_ERROR_EXIT;
         }
         break;
      case 'u': {
         const char* username = optarg;
         if (!username && optind < argc && argv[optind] != NULL && (argv[optind][0] != '\0' && argv[optind][0] != '-')) {
            username = argv[optind++];
         }
         if (!username) {
            flags->userId = geteuid();
         } else if (!Action_setUserOnly(username, &flags->userId)) {
            for (const char* itr = username; *itr; ++itr) {
               if (!isdigit((unsigned char)*itr)) {
                  fprintf(stderr, "Error: invalid user \"%s\".\n", username);
                  return ARG_ERROR_EXIT;
               }
            }
            flags->userId = atol(username);
         }
         break;
      }
      case 'C': flags->useColors = false; break;
      case 'M': flags->enableMouse = false; break;
      case 'U': flags->allowUnicode = false; break;
      case 't': flags->treeView = true; break;
      case 'p': {
         char* argCopy = xstrdup(optarg);
         char* saveptr;
         const char* pid = strtok_r(argCopy, ",", &saveptr);
         if (!flags->pidList) { flags->pidList = xcalloc(1, sizeof(int)); flags->pidCount = 0; }
         while (pid) {
            unsigned int num = atoi(pid);
            flags->pidList = xrealloc(flags->pidList, sizeof(int) * (flags->pidCount + 1));
            flags->pidList[flags->pidCount++] = num;
            pid = strtok_r(NULL, ",", &saveptr);
         }
         free(argCopy);
         break;
      }
      case 'F':
         free(flags->commFilter);
         flags->commFilter = xstrdup(optarg);
         break;
      case 'H': {
         const char* delay = optarg;
         if (!delay && optind < argc && argv[optind] != NULL && (argv[optind][0] != '\0' && argv[optind][0] != '-')) {
            delay = argv[optind++];
         }
         if (delay) {
            if (sscanf(delay, "%16d", &flags->highlightDelaySecs) == 1) {
               if (flags->highlightDelaySecs < 1) flags->highlightDelaySecs = 1;
            } else {
               fprintf(stderr, "Error: invalid highlight delay value \"%s\".\n", delay);
               return ARG_ERROR_EXIT;
            }
         }
         flags->highlightChanges = true;
         break;
      }
      case 128: flags->readonly = true; break;
      case 129: flags->hideMeters = true; break;
      case 130: flags->hideFunctionBar = true; break;
      default:
         return ARG_ERROR_EXIT;
      }
   }
   if (optind < argc) {
      fprintf(stderr, "Error: unsupported non-option ARGV-elements:");
      while (optind < argc) fprintf(stderr, " %s", argv[optind++]);
      fprintf(stderr, "\n");
      return ARG_ERROR_EXIT;
   }
   return ARG_OK;
}

static void delayMs(Machine* host, unsigned long ms) {
   struct timespec req = { .tv_sec = 0, .tv_nsec = ms * 1000000L };
   while (nanosleep(&req, &req) == -1) continue;
   realtimeNow(&host->realtime, &host->realtimeMs);
}

int main(int argc, char** argv) {
   const char* lc_ctype;
   if ((lc_ctype = getenv("LC_CTYPE")) || (lc_ctype = getenv("LC_ALL"))) setlocale(LC_CTYPE, lc_ctype);
   else setlocale(LC_CTYPE, "");

   Flags flags;
   int status = parseArguments(argc, argv, &flags);
   if (status != ARG_OK) return status == ARG_OK_EXIT ? 0 : 1;

   if (flags.readonly) Settings_readonly = true;

   Machine* host = Machine_new(flags.userId);
   if (flags.pidList) { host->pidMatchList = flags.pidList; host->pidMatchCount = flags.pidCount; }
   Settings* settings = Settings_new(host->activeCPUs);
   g_settings = settings;
   Machine_setSettings(host, settings);

   Header* header = Header_new(host, settings);
   Header_populateFromSettings(header);

   if (flags.delay != -1) settings->delay = flags.delay;
   if (!flags.useColors) settings->colorScheme = COLORSCHEME_MONOCHROME;
   if (!flags.enableMouse) settings->enableMouse = false;
   if (flags.treeView) settings->ss->treeView = true;
   if (flags.highlightChanges) settings->highlightChanges = true;
   if (flags.highlightDelaySecs != -1) settings->highlightDelaySecs = flags.highlightDelaySecs;
   if (flags.sortKey > 0) {
      if (!flags.treeView) settings->ss->treeView = false;
      ScreenSettings_setSortKey(settings->ss, flags.sortKey);
   }
   if (flags.hideFunctionBar) settings->hideFunctionBar = 2;

   host->iterationsRemaining = flags.iterationsRemaining;
   CRT_init(settings->delay, settings->colorScheme, settings->enableMouse, flags.iterationsRemaining != -1);

   MainPanel* panel = MainPanel_new();
   host->panel = (Panel*)panel;
   MainPanel_updateLabels(panel, settings->ss->treeView, flags.commFilter != NULL);

   State state = {
      .host = host, .mainPanel = panel, .header = header,
      .pauseUpdate = false, .hideSelection = false, .hideMeters = flags.hideMeters,
   };
   MainPanel_setState(panel, &state);
   if (flags.commFilter) {
      IncSet_setFilter(panel->inc, flags.commFilter);
      host->incFilter = xstrdup(flags.commFilter);
      free(flags.commFilter);
   }

   ScreenManager* scr = ScreenManager_new(header, host, &state, true);
   ScreenManager_add(scr, (Panel*)panel, -1);

   Machine_scan(host);
   Machine_scanProcesses(host);
   if (settings->ss->allBranchesCollapsed) Machine_collapseAllBranches(host);
   delayMs(host, 75);

   ScreenManager_run(scr, NULL, NULL, NULL);

   CRT_done();
   if (settings->changed) {
      int r = Settings_write(settings, false);
      if (r < 0) fprintf(stderr, "Can not save configuration to %s: %s\n", settings->filename, strerror(-r));
   }
   return 0;
}
