cat > infoscreen.c <<'EOF'
#include "app.h"
#include "crt.h"
#include <stdarg.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/wait.h>
#include <signal.h>
#include <errno.h>

typedef struct InfoScreen_ InfoScreen;
struct InfoScreen_ {
   const Process* process;
   Panel* display;
   IncSet* inc;
   Vec* lines;
   void (*scan)(InfoScreen*);
   void (*draw)(InfoScreen*);
   bool (*onKey)(InfoScreen*, int ch);
   void (*onErr)(InfoScreen*);
   void* data;
};

static const char* const InfoScreenFunctions[] = {"Search ", "Filter ", "Refresh", "Done   ", NULL};
static const char* const InfoScreenKeys[] = {"F3", "F4", "F5", "Esc"};
static const int InfoScreenEvents[] = {KEY_F(3), KEY_F(4), KEY_F(5), 27};

static void InfoScreen_init(InfoScreen* this, const Process* process, FunctionBar* bar, int height, const char* panelHeader) {
   this->process = process;
   if (!bar) bar = FunctionBar_new(InfoScreenFunctions, InfoScreenKeys, InfoScreenEvents);
   this->display = Panel_new(0, 1, COLS, height, false, bar);
   this->inc = IncSet_new(bar);
   this->lines = vec_new();
   Panel_setHeader(this->display, panelHeader);
}

static void InfoScreen_done(InfoScreen* this) {
   for (int i = 0; i < this->lines->size; i++) {
      Item* it = this->lines->items[i];
      it->cls->destroy(it);
   }
   vec_free(this->lines);
   IncSet_delete(this->inc);
   Panel_delete(this->display);
}

static void InfoScreen_drawTitled(InfoScreen* this, const char* fmt, ...) {
   va_list ap;
   va_start(ap, fmt);
   char* title = xmalloc(COLS + 1);
   int len = vsnprintf(title, COLS + 1, fmt, ap);
   va_end(ap);
   if (len > COLS) memset(&title[COLS - 3], '.', 3);
   attrset(CRT_colors[METER_TEXT]);
   mvhline(0, 0, ' ', COLS);
   mvaddstr(0, 0, title);
   attrset(CRT_colors[DEFAULT_COLOR]);
   free(title);
   Panel_draw(this->display, true, true, true, false);
   IncSet_drawBar(this->inc, CRT_colors[FUNCTION_BAR]);
}

static bool containsMulti(const char* hay, const char* needle) {
   if (!hay) hay = "";
   if (!strchr(needle, '|')) return strcasestr(hay, needle) != NULL;
   char* copy = xstrdup(needle);
   char* save = NULL;
   bool found = false;
   for (char* tok = strtok_r(copy, "|", &save); tok; tok = strtok_r(NULL, "|", &save)) {
      if (strcasestr(hay, tok)) { found = true; break; }
   }
   free(copy);
   return found;
}

static void InfoScreen_addLine(InfoScreen* this, const char* line) {
   vec_push(this->lines, ListItem_new(line, 0));
   const char* incFilter = IncSet_filter(this->inc);
   if (!incFilter || containsMulti(line, incFilter))
      Panel_add(this->display, this->lines->items[this->lines->size - 1]);
}

static void InfoScreen_appendLine(InfoScreen* this, const char* line) {
   ListItem* last = this->lines->items[this->lines->size - 1];
   ListItem_append(last, line);
   const char* incFilter = IncSet_filter(this->inc);
   if (incFilter && Panel_get(this->display, Panel_size(this->display) - 1) != (Item*)last && containsMulti(line, incFilter))
      Panel_add(this->display, (Item*)last);
}

static void pruneLines(InfoScreen* this) {
   bool owns = this->display->ownsItems;
   this->display->ownsItems = false;
   Panel_prune(this->display);
   this->display->ownsItems = owns;
   for (int i = 0; i < this->lines->size; i++) {
      Item* it = this->lines->items[i];
      it->cls->destroy(it);
   }
   vec_clear(this->lines);
}

static void InfoScreen_run(InfoScreen* this) {
   Panel* panel = this->display;
   if (this->scan) this->scan(this);
   this->draw(this);
   bool looping = true;
   while (looping) {
      Panel_draw(panel, false, true, true, false);
      IncSet_drawBar(this->inc, CRT_colors[FUNCTION_BAR]);
      if (panel->cursorOn) move(LINES - 1, CRT_cursorX);
      set_escdelay(25);
      int ch = getch();
      if (ch == ERR) {
         if (this->onErr) { this->onErr(this); continue; }
      }
      if (ch == KEY_MOUSE) {
         MEVENT mevent;
         int ok = getmouse(&mevent);
         if (ok == OK) {
            if (mevent.bstate & BUTTON1_RELEASED) {
               if (mevent.y >= panel->y && mevent.y < LINES - 1) {
                  Panel_setSelected(panel, mevent.y - panel->y + panel->scrollV - 1);
                  ch = 0;
               } else if (mevent.y == LINES - 1) {
                  ch = IncSet_synthesizeEvent(this->inc, mevent.x);
               }
            } else if (mevent.bstate & BUTTON4_PRESSED) {
               ch = KEY_WHEELUP;
            } else if (mevent.bstate & BUTTON5_PRESSED) {
               ch = KEY_WHEELDOWN;
            }
         }
      }
      if (this->inc->active) {
         IncSet_handleKey(this->inc, ch, panel, IncSet_getListItemValue, this->lines);
         continue;
      }
      switch (ch) {
      case ERR:
         continue;
      case KEY_F(3):
      case '/':
         IncSet_activate(this->inc, INC_SEARCH, panel);
         break;
      case KEY_F(4):
      case '\\':
         IncSet_activate(this->inc, INC_FILTER, panel);
         break;
      case KEY_F(5):
         clear();
         if (this->scan) { pruneLines(this); this->scan(this); }
         this->draw(this);
         break;
      case '\014':
         clear();
         this->draw(this);
         break;
      case 27:
      case 'q':
      case KEY_F(10):
         looping = false;
         break;
      case KEY_RESIZE:
         Panel_resize(panel, COLS, LINES - 2);
         if (this->scan) { pruneLines(this); this->scan(this); }
         this->draw(this);
         break;
      default:
         if (this->onKey && this->onKey(this, ch)) continue;
         Panel_onKey(panel, ch);
      }
   }
}

/* ---------- env ---------- */
static void EnvScreen_draw(InfoScreen* this) {
   InfoScreen_drawTitled(this, "Environment of process %d - %s", this->process->pid, Process_getCommand(this->process));
}
static void EnvScreen_scan(InfoScreen* this) {
   Panel* panel = this->display;
   int idx = MAXI(Panel_getSelectedIndex(panel), 0);
   bool owns = panel->ownsItems; panel->ownsItems = false; Panel_prune(panel); panel->ownsItems = owns;
   char path[64];
   snprintf(path, sizeof(path), "/proc/%d/environ", this->process->pid);
   int fd = open(path, O_RDONLY);
   char* env = NULL;
   size_t size = 0;
   if (fd >= 0) {
      size_t cap = 4096;
      env = xmalloc(cap + 2);
      for (;;) {
         if (size + 1 >= cap) { cap *= 2; env = xrealloc(env, cap + 2); }
         ssize_t r = read(fd, env + size, cap - size);
         if (r < 0) { if (errno == EINTR) continue; free(env); env = NULL; break; }
         if (r == 0) break;
         size += r;
      }
      close(fd);
      if (env) {
         if (size < 2 || env[size - 1] || env[size - 2]) {
            if (size + 2 < cap) size += 2; else { env = xrealloc(env, size + 2); size += 2; }
            env[size - 2] = 0; env[size - 1] = 0;
         }
         if (size <= 2) { free(env); env = NULL; }
      }
   }
   if (env) {
      for (const char* p = env; *p; p = strrchr(p, 0) + 1) InfoScreen_addLine(this, p);
      free(env);
   } else {
      InfoScreen_addLine(this, "Could not read process environment.");
   }
   vec_isort(this->lines, ListItem_compare);
   vec_isort(panel->items, ListItem_compare);
   Panel_setSelected(panel, idx);
}
void InfoScreen_runEnv(State* st, Process* p) {
   (void)st;
   InfoScreen s = { 0 };
   InfoScreen_init(&s, p, NULL, LINES - 2, " ");
   s.scan = EnvScreen_scan;
   s.draw = EnvScreen_draw;
   InfoScreen_run(&s);
   InfoScreen_done(&s);
}

/* ---------- command ---------- */
static void CommandScreen_scan(InfoScreen* this) {
   Panel* panel = this->display;
   int idx = MAXI(Panel_getSelectedIndex(panel), 0);
   bool owns = panel->ownsItems; panel->ownsItems = false; Panel_prune(panel); panel->ownsItems = owns;
   const char* p = Process_getCommand(this->process);
   if (!p) p = "";
   char* line = xmalloc(COLS + 2);
   int line_offset = 0, last_spc = -1, len;
   for (; *p != '\0'; p++, line_offset++) {
      line[line_offset] = *p;
      if (*p == ' ') last_spc = line_offset;
      if (line_offset == COLS) {
         len = (last_spc == -1) ? line_offset : last_spc;
         line[len] = '\0';
         InfoScreen_addLine(this, line);
         line_offset -= len;
         last_spc = -1;
         memcpy(line, p - line_offset, line_offset + 1);
      }
   }
   if (line_offset > 0) {
      line[line_offset] = '\0';
      InfoScreen_addLine(this, line);
   }
   free(line);
   Panel_setSelected(panel, idx);
}
static void CommandScreen_draw(InfoScreen* this) {
