/* ---------- lsof ---------- */
typedef struct FileData { char data[8][256]; bool has[8]; struct FileData* next; } FileData;

static void OpenFilesScreen_draw(InfoScreen* this) {
   InfoScreen_drawTitled(this, "Snapshot of files open in process %d - %s", this->process->pid, Process_getCommand(this->process));
}

static void OpenFilesScreen_scan(InfoScreen* this) {
   Panel* panel = this->display;
   int idx = MAXI(Panel_getSelectedIndex(panel), 0);
   bool owns = panel->ownsItems; panel->ownsItems = false; Panel_prune(panel); panel->ownsItems = owns;
   int fdpair[2] = {0, 0};
   bool error = false;
   int errorCode = 0;
   char** lines = NULL; int nlines = 0;
   if (pipe(fdpair) == -1) {
      error = true;
   } else {
      pid_t child = fork();
      if (child == -1) {
         close(fdpair[1]); close(fdpair[0]);
         error = true;
      } else if (child == 0) {
         close(fdpair[0]);
         dup2(fdpair[1], STDOUT_FILENO);
         close(fdpair[1]);
         int fdnull = open("/dev/null", O_WRONLY);
         if (fdnull < 0) exit(1);
         dup2(fdnull, STDERR_FILENO);
         close(fdnull);
         char buffer[32];
         snprintf(buffer, sizeof(buffer), "%d", this->process->pid);
         execlp("lsof", "lsof", "-P", "-o", "-p", buffer, "-F", NULL);
         exit(127);
      } else {
         close(fdpair[1]);
         FILE* fp = fdopen(fdpair[0], "r");
         char buf[4096];
         while (fp && fgets(buf, sizeof(buf), fp)) {
            size_t l = strlen(buf);
            if (l && buf[l-1] == '\n') buf[l-1] = 0;
            lines = xrealloc(lines, sizeof(char*) * (nlines + 1));
            lines[nlines++] = xstrdup(buf);
         }
         if (fp) fclose(fp);
         int wstatus;
         while (waitpid(child, &wstatus, 0) == -1) if (errno != EINTR) { error = true; break; }
         if (!error) {
            if (!WIFEXITED(wstatus)) error = true;
            else errorCode = WEXITSTATUS(wstatus);
         }
      }
   }
   if (error || errorCode == 127) {
      InfoScreen_addLine(this, "Could not execute 'lsof'. Please make sure it is available in your $PATH.");
   } else if (errorCode == 1 && nlines == 0) {
      InfoScreen_addLine(this, "Failed listing open files.");
   } else {
      /* parse lsof -F output */
      char fd[64] = "", type[64] = "", mode[64] = "", device[64] = "", size[64] = "", offset[64] = "", node[64] = "", name[4096] = "";
      bool haveFile = false;
      for (int i = 0; i <= nlines; i++) {
         const char* l = i < nlines ? lines[i] : "f";
         char cmd = l[0];
         const char* v = l + 1;
         if (cmd == 'f' || cmd == 'p') {
            if (haveFile) {
               char entry[8192];
               snprintf(entry, sizeof(entry), "%5.5s %-7.7s %-4.4s %-10.10s %10.10s %10.10s %10.10s  %s",
                        fd, type, mode, device, size, offset, node, name);
               InfoScreen_addLine(this, entry);
            }
            haveFile = cmd == 'f';
            fd[0] = type[0] = mode[0] = device[0] = size[0] = offset[0] = node[0] = name[0] = 0;
            if (cmd == 'f') snprintf(fd, sizeof(fd), "%s", v);
            continue;
         }
         switch (cmd) {
         case 't': snprintf(type, sizeof(type), "%s", v); break;
         case 'a': snprintf(mode, sizeof(mode), "%s", v); break;
         case 'D': snprintf(device, sizeof(device), "%s", v); break;
         case 's': snprintf(size, sizeof(size), "%s", v); break;
         case 'o': snprintf(offset, sizeof(offset), "%s", v); break;
         case 'i': snprintf(node, sizeof(node), "%s", v); break;
         case 'n': snprintf(name, sizeof(name), "%s", v); break;
         }
      }
   }
   for (int i = 0; i < nlines; i++) free(lines[i]);
   free(lines);
   Panel_setSelected(panel, idx);
}

void InfoScreen_runLsof(State* st, Process* p) {
   (void)st;
   InfoScreen s = { 0 };
   InfoScreen_init(&s, p, NULL, LINES - 2, "   FD TYPE    MODE DEVICE           SIZE     OFFSET       NODE  NAME");
   s.scan = OpenFilesScreen_scan;
   s.draw = OpenFilesScreen_draw;
   InfoScreen_run(&s);
   InfoScreen_done(&s);
}

/* ---------- locks ---------- */
static void LocksScreen_draw(InfoScreen* this) {
   InfoScreen_drawTitled(this, "Snapshot of file locks of process %d - %s", this->process->pid, Process_getCommand(this->process));
}
static void LocksScreen_scan(InfoScreen* this) {
   Panel* panel = this->display;
   int idx = MAXI(Panel_getSelectedIndex(panel), 0);
   bool owns = panel->ownsItems; panel->ownsItems = false; Panel_prune(panel); panel->ownsItems = owns;
   int count = 0;
   FILE* f = fopen("/proc/locks", "r");
   if (f) {
      char line[1024];
      while (fgets(line, sizeof(line), f)) {
         int id; char locktype[32], exclusion[32], rw[32]; int pid; unsigned int maj, min; unsigned long long inode;
         char start[64], end[64];
         char* p = line;
         if (sscanf(p, "%d: %31s %31s %31s %d %x:%x:%llu %63s %63s", &id, locktype, exclusion, rw, &pid, &maj, &min, &inode, start, end) != 10) continue;
         if (pid != this->process->pid) continue;
         char entry[2048];
         snprintf(entry, sizeof(entry), "%5d %-10s %-10s %-10s %02x:%02x %10llu %19s %19s  %s", id, locktype, exclusion, rw, maj, min, inode, start, end, "<N/A>");
         InfoScreen_addLine(this, entry);
         count++;
      }
      fclose(f);
   }
   if (!count) InfoScreen_addLine(this, "No locks have been found for the selected process.");
   Panel_setSelected(panel, idx);
}
void InfoScreen_runLocks(State* st, Process* p) {
   (void)st;
   InfoScreen s = { 0 };
   InfoScreen_init(&s, p, NULL, LINES - 2, "   FD TYPE       EXCLUSION  READ/WRITE DEVICE       NODE               START                 END  FILENAME");
   s.scan = LocksScreen_scan;
   s.draw = LocksScreen_draw;
   InfoScreen_run(&s);
   InfoScreen_done(&s);
}

/* ---------- strace ---------- */
static const char* const TraceScreenFunctions[] = {"Search ", "Filter ", "AutoScroll ", "Stop Tracing   ", "Done   ", NULL};
static const char* const TraceScreenKeys[] = {"F3", "F4", "F8", "F9", "Esc"};
static const int TraceScreenEvents[] = {KEY_F(3), KEY_F(4), KEY_F(8), KEY_F(9), 27};

typedef struct { bool tracing; int fdpair[2]; pid_t child; FILE* strace; bool contLine; bool follow; bool started; } TraceData;

static void TraceScreen_draw(InfoScreen* this) {
   InfoScreen_drawTitled(this, "Trace of process %d - %s", this->process->pid, Process_getCommand(this->process));
}

static bool TraceScreen_forkTracer(InfoScreen* this) {
   TraceData* d = this->data;
   if (pipe(d->fdpair) == -1) return false;
   if (fcntl(d->fdpair[0], F_SETFL, O_NONBLOCK) < 0) goto err;
   d->child = fork();
   if (d->child == -1) goto err;
   if (d->child == 0) {
      close(d->fdpair[0]);
      dup2(d->fdpair[1], STDOUT_FILENO);
      dup2(d->fdpair[1], STDERR_FILENO);
      close(d->fdpair[1]);
      char buffer[32];
      snprintf(buffer, sizeof(buffer), "%d", this->process->pid);
      execlp("strace", "strace", "-T", "-tt", "-s", "512", "-p", buffer, NULL);
      const char* message = "Could not execute 'strace'. Please make sure it is available in your $PATH.";
      ssize_t r = write(STDERR_FILENO, message, strlen(message)); (void)r;
      exit(127);
   }
   close(d->fdpair[1]);
   d->strace = fdopen(d->fdpair[0], "r");
   if (!d->strace) goto err;
   return true;
err:
   close(d->fdpair[1]); close(d->fdpair[0]);
   return false;
}

static void TraceScreen_updateTrace(InfoScreen* this) {
   TraceData* d = this->data;
   if (!d->strace) return;
   int fd_strace = fileno(d->strace);
   fd_set fds;
   FD_ZERO(&fds);
   FD_SET(fd_strace, &fds);
   struct timeval tv = { .tv_sec = 0, .tv_usec = 500 };
   int ready = select(fd_strace + 1, &fds, NULL, NULL, &tv);
   size_t nread = 0;
   char buffer[1025];
   if (ready > 0 && FD_ISSET(fd_strace, &fds)) nread = fread(buffer, 1, sizeof(buffer) - 1, d->strace);
   if (nread && d->tracing) {
      const char* line = buffer;
      buffer[nread] = '\0';
      for (size_t i = 0; i < nread; i++) {
         if (buffer[i] == '\n') {
            buffer[i] = '\0';
            if (d->contLine) { InfoScreen_appendLine(this, line); d->contLine = false; }
            else InfoScreen_addLine(this, line);
            line = buffer + i + 1;
         }
      }
      if (line < buffer + nread) {
         InfoScreen_addLine(this, line);
         buffer[nread] = '\0';
         d->contLine = true;
      }
      if (d->follow) Panel_setSelected(this->display, Panel_size(this->display) - 1);
   }
}

static bool TraceScreen_onKey(InfoScreen* this, int ch) {
   TraceData* d = this->data;
   switch (ch) {
   case 'f':
   case KEY_F(8):
      d->follow = !d->follow;
      if (d->follow) Panel_setSelected(this->display, Panel_size(this->display) - 1);
      return true;
   case 't':
   case KEY_F(9):
      d->tracing = !d->tracing;
      FunctionBar_setLabel(this->display->defaultBar, KEY_F(9), d->tracing ? "Stop Tracing   " : "Resume Tracing ");
      this->draw(this);
      return true;
   }
   d->follow = false;
   return false;
}

void InfoScreen_runStrace(State* st, Process* p) {
   (void)st;
   InfoScreen s = { 0 };
   TraceData d = { .tracing = true, .follow = false, .contLine = false, .strace = NULL };
   s.data = &d;
   FunctionBar* fuBar = FunctionBar_new(TraceScreenFunctions, TraceScreenKeys, TraceScreenEvents);
   InfoScreen_init(&s, p, fuBar, LINES - 2, " ");
   s.draw = TraceScreen_draw;
   s.onErr = TraceScreen_updateTrace;
   s.onKey = TraceScreen_onKey;
   if (TraceScreen_forkTracer(&s)) {
      InfoScreen_run(&s);
   }
   if (d.child > 0) {
      kill(d.child, SIGTERM);
      while (waitpid(d.child, NULL, 0) == -1) if (errno != EINTR) break;
   }
   if (d.strace) fclose(d.strace);
   InfoScreen_done(&s);
}
