/* ======================= Option items ======================= */
typedef enum { OPT_TEXT, OPT_CHECK, OPT_NUMBER } OptKind;
typedef struct {
   Item super;
   OptKind kind;
   char* text;
   bool* bref;
   int* iref;
   int scale, min, max;
} OptionItem;

static void OptionItem_display(const Item* cast, RStr* out) {
   const OptionItem* this = (const OptionItem*)cast;
   switch (this->kind) {
   case OPT_TEXT:
      rs_append(out, CRT_colors[HELP_BOLD], this->text);
      break;
   case OPT_CHECK:
      rs_append(out, CRT_colors[CHECK_BOX], "[");
      rs_append(out, CRT_colors[CHECK_MARK], *this->bref ? "x" : " ");
      rs_append(out, CRT_colors[CHECK_BOX], "]    ");
      rs_append(out, CRT_colors[CHECK_TEXT], this->text);
      break;
   case OPT_NUMBER: {
      char buffer[32];
      rs_append(out, CRT_colors[CHECK_BOX], "[");
      int written;
      int v = *this->iref;
      if (this->scale < 0) written = xsnprintf(buffer, sizeof(buffer), "%.*f", -this->scale, pow(10, this->scale) * v);
      else if (this->scale > 0) written = xsnprintf(buffer, sizeof(buffer), "%d", (int)(pow(10, this->scale) * v));
      else written = xsnprintf(buffer, sizeof(buffer), "%d", v);
      rs_appendn(out, CRT_colors[CHECK_MARK], buffer, written);
      rs_append(out, CRT_colors[CHECK_BOX], "]");
      for (int i = written; i < 5; i++) rs_append(out, CRT_colors[CHECK_BOX], " ");
      rs_append(out, CRT_colors[CHECK_TEXT], this->text);
      break;
   }
   }
}
static void OptionItem_destroy(Item* cast) { OptionItem* this = (OptionItem*)cast; free(this->text); free(this); }
static const ItemClass OptionItem_class = { OptionItem_display, OptionItem_destroy, NULL };

static OptionItem* TextItem_new(const char* text) {
