/* ======================= Display options ======================= */
static const char* const DecIncFunctions[] = {"      ", "      ", "      ", "      ", "      ", "      ", "Dec   ", "Inc   ", "      ", "Done  ", NULL};

typedef struct { FunctionBar* decIncBar; } DisplayOptionsData;

static HandlerResult DisplayOptionsPanel_eventHandler(Panel* super, int ch) {
   DisplayOptionsData* data = super->data;
   HandlerResult result = IGNORED;
   OptionItem* selected = (OptionItem*)Panel_getSelected(super);
   switch (ch) {
   case EVENT_SET_SELECTED:
      break;
   case '\n':
   case '\r':
   case KEY_ENTER:
   case KEY_MOUSE:
   case KEY_RECLICK:
   case ' ':
      if (!selected) break;
      switch (selected->kind) {
      case OPT_TEXT: break;
      case OPT_CHECK: *selected->bref = !*selected->bref; result = HANDLED; break;
      case OPT_NUMBER:
         if (*selected->iref >= selected->max) *selected->iref = selected->min;
         else *selected->iref += 1;
         result = HANDLED;
         break;
      }
      break;
   case '-':
   case KEY_F(7):
      if (selected && selected->kind == OPT_NUMBER) {
         *selected->iref = CLAMPI(*selected->iref - 1, selected->min, selected->max);
         result = HANDLED;
      }
      break;
   case '+':
   case KEY_F(8):
      if (selected && selected->kind == OPT_NUMBER) {
         *selected->iref = CLAMPI(*selected->iref + 1, selected->min, selected->max);
         result = HANDLED;
      }
      break;
   case KEY_UP:
   case KEY_DOWN:
   case KEY_NPAGE:
   case KEY_PPAGE:
   case KEY_HOME:
   case KEY_END: {
      OptionItem* previous = selected;
      Panel_onKey(super, ch);
      selected = (OptionItem*)Panel_getSelected(super);
      if (previous != selected) result = HANDLED;
      break;
   }
   }
   selected = (OptionItem*)Panel_getSelected(super);
   if (selected && selected->kind == OPT_NUMBER) super->currentBar = data->decIncBar;
   else super->currentBar = super->defaultBar;

   if (result == HANDLED) {
      Settings* settings = g_ctx.settings;
      settings->changed = true;
      settings->lastUpdate++;
      CRT_updateDelay(settings->delay);
      Header* header = g_ctx.header;
      Header_calculateHeight(header);
      Header_reinit(header);
      Header_updateData(header);
      Header_draw(header);
      ScreenManager_resize(g_ctx.scr);
   }
   return result;
}

static void DisplayOptionsPanel_destroy(Panel* this) {
