   Panel_add(super, (Item*)OCheckItem_new("Hide kernel threads", &settings->hideKernelThreads));
   Panel_add(super, (Item*)OCheckItem_new("Hide userland process threads", &settings->hideUserlandThreads));
   Panel_add(super, (Item*)OCheckItem_new("Hide processes running in containers", &settings->hideRunningInContainer));
