   Panel_add(super, (Item*)OCheckItem_new("Show custom thread names", &settings->showThreadNames));
   Panel_add(super, (Item*)OCheckItem_new("Show program path", &settings->showProgramPath));
   Panel_add(super, (Item*)OCheckItem_new("Highlight program \"basename\"", &settings->highlightBaseName));
   Panel_add(super, (Item*)OCheckItem_new("Highlight out-dated/removed programs (red) / libraries (yellow)", &settings->highlightDeletedExe));
   Panel_add(super, (Item*)OCheckItem_new("Shadow distribution path prefixes", &settings->shadowDistPathPrefix));
   Panel_add(super, (Item*)OCheckItem_new("Merge exe, comm and cmdline in Command", &settings->showMergedCommand));
   Panel_add(super, (Item*)OCheckItem_new("- Try to find comm in cmdline (when Command is merged)", &settings->findCommInCmdline));
