   Panel_add(super, (Item*)OCheckItem_new("Count CPUs from 1 instead of 0", &settings->countCPUsFromOne));
   Panel_add(super, (Item*)OCheckItem_new("Update process names on every refresh", &settings->updateProcessNames));
