   Panel_add(super, (Item*)OCheckItem_new("Enable the mouse", &settings->enableMouse));
   Panel_add(super, (Item*)NumberItem_new("Update interval (in seconds)", &settings->delay, -1, 1, 255));
   Panel_add(super, (Item*)OCheckItem_new("Highlight new and old processes", &settings->highlightChanges));
   Panel_add(super, (Item*)NumberItem_new("- Highlight time (in seconds)", &settings->highlightDelaySecs, 0, 1, 24 * 60 * 60));
   Panel_add(super, (Item*)NumberItem_new("Hide main function bar (0 - off, 1 - on ESC until next input, 2 - permanently)", &settings->hideFunctionBar, 0, 0, 2));
   return super;
}

/* ======================= Header layout ======================= */
static HandlerResult HeaderOptionsPanel_eventHandler(Panel* super, int ch) {
   HandlerResult result = IGNORED;
   int mark;
   switch (ch) {
   case 0x0a:
   case 0x0d:
   case KEY_ENTER:
   case KEY_MOUSE:
   case KEY_RECLICK:
   case ' ':
      mark = Panel_getSelectedIndex(super);
      for (int i = 0; i < LAST_HEADER_LAYOUT; i++) CheckItem_set((CheckItem*)Panel_get(super, i), false);
      CheckItem_set((CheckItem*)Panel_get(super, mark), true);
      Header_setLayout(g_ctx.header, mark);
      Settings_setHeaderLayout(g_ctx.settings, mark);
      Header_writeBackToSettings(g_ctx.header);
      g_ctx.settings->changed = true;
      g_ctx.settings->lastUpdate++;
      ScreenManager_resize(g_ctx.scr);
      result = HANDLED;
   }
   return result;
}

static Panel* HeaderOptionsPanel_new(void) {
