}

/* ======================= Colors ======================= */
static HandlerResult ColorsPanel_eventHandler(Panel* super, int ch) {
   HandlerResult result = IGNORED;
   int mark;
   switch (ch) {
   case 0x0a:
   case 0x0d:
   case KEY_ENTER:
   case KEY_MOUSE:
   case KEY_RECLICK:
   case ' ':
      mark = Panel_getSelectedIndex(super);
      for (int i = 0; colorSchemeNames[i] != NULL; i++) CheckItem_set((CheckItem*)Panel_get(super, i), false);
      CheckItem_set((CheckItem*)Panel_get(super, mark), true);
      g_ctx.settings->colorScheme = mark;
      g_ctx.settings->changed = true;
      g_ctx.settings->lastUpdate++;
      CRT_setColors(mark);
      clear();
      result = HANDLED | REDRAW;
   }
   return result;
}

static Panel* ColorsPanel_new(void) {
   Panel* super = Panel_new(1, 1, 1, 1, true, FunctionBar_new(EmptyDoneFunctions, NULL, NULL));
   super->eventHandler = ColorsPanel_eventHandler;
   Panel_setHeader(super, "Colors");
   for (int i = 0; colorSchemeNames[i] != NULL; i++)
      Panel_add(super, (Item*)CheckItem_newByVal(colorSchemeNames[i], false));
   CheckItem_set((CheckItem*)Panel_get(super, g_ctx.settings->colorScheme), true);
   return super;
}

/* ======================= Meters ======================= */
static const char* const MetersFunctions[] = {"Style ", "Move  ", "                                       ", "Delete", "Done  ", NULL};
static const char* const MetersKeys[] = {"Space", "Enter", "", "Del", "F10"};
static const int MetersEvents[] = {' ', 13, ERR, KEY_DC, KEY_F(10)};
static const char* const MetersMovingFunctions[] = {"Style ", "Lock  ", "Up    ", "Down  ", "Left  ", "Right ", "       ", "Delete", "Done  ", NULL};
static const char* const MetersMovingKeys[] = {"Space", "Enter", "Up", "Dn", "<-", "->", "  ", "Del", "F10"};
static const int MetersMovingEvents[] = {' ', 13, KEY_UP, KEY_DOWN, KEY_LEFT, KEY_RIGHT, ERR, KEY_DC, KEY_F(10)};
static FunctionBar* Meters_movingBar = NULL;

typedef struct MetersPanelData {
   Vec* meters;
   bool moving;
   Panel* leftNeighbor;
   Panel* rightNeighbor;
} MetersPanelData;

static ListItem* Meter_toListItem(const Meter* m, bool moving) {
   char mode[32];
   if (m->mode > 0) xsnprintf(mode, sizeof(mode), " [%s]", Meter_modeNames[m->mode]);
   else mode[0] = 0;
   char name[64];
   Meter_getUiName(m, name, sizeof(name));
   char buffer[100];
   xsnprintf(buffer, sizeof(buffer), "%s%s", name, mode);
   ListItem* li = ListItem_new(buffer, 0);
   li->moving = moving;
   return li;
}

static void MetersPanel_setMoving(Panel* super, bool moving) {
   MetersPanelData* d = super->data;
   d->moving = moving;
   ListItem* selected = (ListItem*)Panel_getSelected(super);
   if (selected) selected->moving = moving;
   if (!moving) {
      Panel_setSelectionColor(super, PANEL_SELECTION_FOCUS);
      super->currentBar = super->defaultBar;
   } else {
      Panel_setSelectionColor(super, PANEL_SELECTION_FOLLOW);
      super->currentBar = Meters_movingBar;
   }
}

static bool moveToNeighbor(Panel* super, Panel* neighbor, int selected) {
   MetersPanelData* d = super->data;
   if (d->moving && neighbor) {
      if (selected < d->meters->size) {
         MetersPanel_setMoving(super, false);
         Meter* meter = vec_remove(d->meters, selected);
         Panel_remove(super, selected);
         MetersPanelData* nd = neighbor->data;
         vec_insert(nd->meters, selected, meter);
         Panel_insert(neighbor, selected, (Item*)Meter_toListItem(meter, false));
         Panel_setSelected(neighbor, selected);
         MetersPanel_setMoving(neighbor, true);
         return true;
      }
   }
   return false;
}

static HandlerResult MetersPanel_eventHandler(Panel* super, int ch) {
   MetersPanelData* d = super->data;
   int selected = Panel_getSelectedIndex(super);
   HandlerResult result = IGNORED;
   bool sideMove = false;
   switch (ch) {
   case 0x0a:
   case 0x0d:
   case KEY_ENTER:
      if (!d->meters->size) break;
      MetersPanel_setMoving(super, !d->moving);
      result = HANDLED;
      break;
   case ' ':
   case KEY_F(4):
   case 't': {
      if (!d->meters->size) break;
      Meter* meter = d->meters->items[selected];
      int mode = Meter_nextSupportedMode(meter);
      Meter_setMode(meter, mode);
      Panel_set(super, selected, (Item*)Meter_toListItem(meter, d->moving));
      result = HANDLED;
      break;
   }
   case KEY_UP:
      if (!d->moving) break;
      /* fallthrough */
   case KEY_F(7):
   case '[':
   case '-':
      if (selected > 0 && selected < d->meters->size) vec_swap(d->meters, selected, selected - 1);
      Panel_moveSelectedUp(super);
      result = HANDLED;
      break;
   case KEY_DOWN:
      if (!d->moving) break;
      /* fallthrough */
   case KEY_F(8):
   case ']':
   case '+':
      if (selected + 1 < d->meters->size) vec_swap(d->meters, selected, selected + 1);
      Panel_moveSelectedDown(super);
      result = HANDLED;
      break;
   case KEY_RIGHT:
      sideMove = moveToNeighbor(super, d->rightNeighbor, selected);
      if (d->moving && !sideMove) result = HANDLED;
      break;
   case KEY_LEFT:
      sideMove = moveToNeighbor(super, d->leftNeighbor, selected);
      if (d->moving && !sideMove) result = HANDLED;
      break;
   case KEY_F(9):
   case KEY_DC:
      if (!d->meters->size) break;
      if (selected < d->meters->size) {
         Meter* m = vec_remove(d->meters, selected);
         Meter_delete(m);
         Panel_remove(super, selected);
      }
      MetersPanel_setMoving(super, false);
      result = HANDLED;
      break;
   }
   if (result == HANDLED || sideMove) {
      g_ctx.settings->changed = true;
      g_ctx.settings->lastUpdate++;
      Header_calculateHeight(g_ctx.header);
      ScreenManager_resize(g_ctx.scr);
   }
   return result;
}

static void MetersPanel_destroy(Panel* this) {
   free(this->data);
   Panel_done(this);
   free(this);
}

static Panel* MetersPanel_new(const char* header, Vec* meters) {
   Panel* super = Panel_new(1, 1, 1, 1, true, FunctionBar_new(MetersFunctions, MetersKeys, MetersEvents));
   if (!Meters_movingBar) Meters_movingBar = FunctionBar_new(MetersMovingFunctions, MetersMovingKeys, MetersMovingEvents);
   MetersPanelData* d = xcalloc(1, sizeof(MetersPanelData));
   d->meters = meters;
   super->data = d;
   super->eventHandler = MetersPanel_eventHandler;
   super->destroy = MetersPanel_destroy;
   Panel_setHeader(super, header);
   for (int i = 0; i < meters->size; i++) Panel_add(super, (Item*)Meter_toListItem(meters->items[i], false));
   return super;
}

static const char* const AvailableMetersFunctions[] = {"Add   ", "Done  ", NULL};
static const char* const AvailableMetersKeys[] = {"Enter", "Esc"};
static const int AvailableMetersEvents[] = {13, 27};

typedef struct { Panel** meterPanels; int columns; } AvailableMetersData;

static HandlerResult AvailableMetersPanel_eventHandler(Panel* super, int ch) {
   AvailableMetersData* d = super->data;
   const ListItem* selected = (ListItem*)Panel_getSelected(super);
   if (!selected) return IGNORED;
   unsigned int param = selected->key & 0xffff;
   int type = selected->key >> 16;
   HandlerResult result = IGNORED;
   bool update = false;
   switch (ch) {
   case KEY_F(5):
   case 'l':
   case 'L':
   case KEY_ENTER:
   case 13: {
      int col = d->columns - 1;
      Panel* mp = d->meterPanels[col];
      Meter* meter = Header_addMeterByClass(g_ctx.header, Platform_meterTypes[type], param, col);
      (void)meter;
      MetersPanelData* md = mp->data;
      (void)md;
      Panel_add(mp, (Item*)Meter_toListItem(meter, false));
      Panel_setSelected(mp, Panel_size(mp) - 1);
      MetersPanel_setMoving(mp, true);
      result = (KEY_LEFT << 16) | SYNTH_KEY;
      update = true;
      break;
   }
   default:
      if (0 < ch && ch < 255 && isgraph((unsigned char)ch)) result = Panel_selectByTyping(super, ch);
      break;
   }
   if (update) {
      g_ctx.settings->changed = true;
      g_ctx.settings->lastUpdate++;
      Header_calculateHeight(g_ctx.header);
      Header_updateData(g_ctx.header);
      Header_draw(g_ctx.header);
      ScreenManager_resize(g_ctx.scr);
   }
   return result;
}

static void AvailableMetersPanel_destroy(Panel* this) {
   AvailableMetersData* d = this->data;
   free(d->meterPanels);
   free(d);
   Panel_done(this);
   free(this);
}

static Panel* AvailableMetersPanel_new(Panel** meterPanels, int columns) {
   Panel* super = Panel_new(1, 1, 1, 1, true, FunctionBar_new(AvailableMetersFunctions, AvailableMetersKeys, AvailableMetersEvents));
   AvailableMetersData* d = xcalloc(1, sizeof(AvailableMetersData));
   d->meterPanels = meterPanels;
   d->columns = columns;
   super->data = d;
   super->eventHandler = AvailableMetersPanel_eventHandler;
   super->destroy = AvailableMetersPanel_destroy;
   Panel_setHeader(super, "Available meters");
   for (int i = 1; Platform_meterTypes[i]; i++) {
      const MeterClass* type = Platform_meterTypes[i];
      const char* label = type->description ? type->description : type->uiName;
      Panel_add(super, (Item*)ListItem_new(label, i << 16));
   }
   Machine* host = g_ctx.host;
   if (host->existingCPUs > 1) {
      Panel_add(super, (Item*)ListItem_new("CPU average", 0));
      for (unsigned int i = 1; i <= host->existingCPUs; i++) {
         char buffer[50];
         xsnprintf(buffer, sizeof(buffer), "%s %d", CPUMeter_class.uiName, Settings_cpuId(host->settings, i - 1));
         Panel_add(super, (Item*)ListItem_new(buffer, i));
      }
   } else {
      Panel_add(super, (Item*)ListItem_new(CPUMeter_class.uiName, 1));
   }
   return super;
}

/* ======================= Screens / Columns ======================= */
typedef struct {
   ListItem super;
   ScreenSettings* ss;
} ScreenListItem;

static void ScreenListItem_destroy(Item* cast) { ListItem* this = (ListItem*)cast; free(this->value); free(this); }
static ItemClass ScreenListItem_class;

static ScreenListItem* ScreenListItem_new(const char* value, ScreenSettings* ss) {
   ScreenListItem* this = xcalloc(1, sizeof(ScreenListItem));
   ScreenListItem_class = ListItem_class;
   ScreenListItem_class.destroy = ScreenListItem_destroy;
   this->super.super.cls = &ScreenListItem_class;
   this->super.value = xstrdup(value);
   this->ss = ss;
   return this;
}

static const char* const ColumnsFunctions[] = {"      ", "      ", "      ", "      ", "      ", "      ", "MoveUp", "MoveDn", "Remove", "Done  ", NULL};

typedef struct { ScreenSettings* ss; bool moving; } ColumnsData;

static void ColumnsPanel_update(Panel* super) {
   ColumnsData* d = super->data;
   int size = Panel_size(super);
   g_ctx.settings->changed = true;
   int* fields = xcalloc(size + 1, sizeof(int));
   for (int i = 0; i < size; i++) fields[i] = ((ListItem*)Panel_get(super, i))->key;
   ScreenSettings_setFields(d->ss, fields, size);
   free(fields);
}

static HandlerResult ColumnsPanel_eventHandler(Panel* super, int ch) {
   ColumnsData* d = super->data;
   int selected = Panel_getSelectedIndex(super);
   HandlerResult result = IGNORED;
   int size = Panel_size(super);
   switch (ch) {
   case 0x0a:
   case 0x0d:
   case KEY_ENTER:
   case KEY_MOUSE:
   case KEY_RECLICK:
      if (selected < size - 1) {
         d->moving = !d->moving;
         Panel_setSelectionColor(super, d->moving ? PANEL_SELECTION_FOLLOW : PANEL_SELECTION_FOCUS);
         ListItem* li = (ListItem*)Panel_getSelected(super);
         if (li) li->moving = d->moving;
         result = HANDLED;
      }
      break;
   case KEY_UP:
      if (!d->moving) break;
      /* fallthrough */
   case KEY_F(7):
   case '[':
   case '-':
      if (selected < size - 1) Panel_moveSelectedUp(super);
      result = HANDLED;
      break;
   case KEY_DOWN:
      if (!d->moving) break;
      /* fallthrough */
   case KEY_F(8):
   case ']':
   case '+':
      if (selected < size - 2) Panel_moveSelectedDown(super);
      result = HANDLED;
      break;
   case KEY_F(9):
   case KEY_DC:
      if (size > 1 && selected < size - 1) Panel_remove(super, selected);
      result = HANDLED;
      break;
   default:
      if (0 < ch && ch < 255 && isgraph((unsigned char)ch)) result = Panel_selectByTyping(super, ch);
      if (result == BREAK_LOOP) result = IGNORED;
      break;
   }
   if (result == HANDLED) ColumnsPanel_update(super);
   return result;
}

static void ColumnsPanel_fill(Panel* super, ScreenSettings* ss) {
   ColumnsData* d = super->data;
   Panel_prune(super);
   for (int i = 0; ss->fields[i]; i++) {
      int f = ss->fields[i];
      Panel_add(super, (Item*)ListItem_new(Fields[f].name ? Fields[f].name : "-", f));
   }
   d->ss = ss;
}

static void ColumnsPanel_destroy(Panel* this) { free(this->data); Panel_done(this); free(this); }

static Panel* ColumnsPanel_new(ScreenSettings* ss) {
   Panel* super = Panel_new(1, 1, 1, 1, true, FunctionBar_new(ColumnsFunctions, NULL, NULL));
   ColumnsData* d = xcalloc(1, sizeof(ColumnsData));
   super->data = d;
   super->eventHandler = ColumnsPanel_eventHandler;
   super->destroy = ColumnsPanel_destroy;
   Panel_setHeader(super, "Active Columns");
   ColumnsPanel_fill(super, ss);
   return super;
}

static const char* const AvailableColumnsFunctions[] = {"      ", "      ", "      ", "      ", "Add   ", "      ", "      ", "      ", "      ", "Done  ", NULL};

static HandlerResult AvailableColumnsPanel_eventHandler(Panel* super, int ch) {
   Panel* columns = super->data;
   HandlerResult result = IGNORED;
   switch (ch) {
   case 13:
   case KEY_ENTER:
   case KEY_F(5): {
      const ListItem* selected = (ListItem*)Panel_getSelected(super);
      if (!selected) break;
      int key = selected->key;
      int at = Panel_getSelectedIndex(columns);
      Panel_insert(columns, at, (Item*)ListItem_new(Fields[key].name, key));
      Panel_setSelected(columns, at + 1);
      ColumnsPanel_update(columns);
      result = HANDLED;
      break;
   }
   default:
      if (0 < ch && ch < 255 && isgraph((unsigned char)ch)) result = Panel_selectByTyping(super, ch);
      break;
   }
   return result;
}

static Panel* AvailableColumnsPanel_new(Panel* columns) {
   Panel* super = Panel_new(1, 1, 1, 1, true, FunctionBar_new(AvailableColumnsFunctions, NULL, NULL));
   super->data = columns;
   super->eventHandler = AvailableColumnsPanel_eventHandler;
   Panel_setHeader(super, "Available Columns");
   for (int i = 1; i < LAST_PROCESSFIELD; i++) {
      if (Fields[i].description) {
         char description[512];
         xsnprintf(description, sizeof(description), "%s - %s", Fields[i].name, Fields[i].description);
         Panel_add(super, (Item*)ListItem_new(description, i));
      }
   }
   return super;
}

static const char* const ScreensFunctions[] = {"      ", "Rename", "      ", "      ", "New   ", "      ", "MoveUp", "MoveDn", "Remove", "Done  ", NULL};
#define SCREEN_NAME_LEN 20

typedef struct {
   Panel* columns;
   bool moving;
   bool renaming;
   char buffer[SCREEN_NAME_LEN + 1];
   char* saved;
   int cursor;
   ListItem* renamingItem;
} ScreensData;

static void Panel_setCursorToSelection(Panel* this) {
   this->cursorY = this->y + this->selected - this->scrollV + 1;
   this->cursorX = this->x + this->selectedLen - this->scrollH;
}

static void ScreensPanel_update(Panel* super) {
   Settings* settings = g_ctx.settings;
   settings->changed = true;
   settings->lastUpdate++;
   int size = Panel_size(super);
   for (int i = 0; i < size; i++) {
      ScreenListItem* item = (ScreenListItem*)Panel_get(super, i);
      ScreenSettings* ss = item->ss;
      if (strcmp(ss->heading, item->super.value) != 0) {
         free(ss->heading);
         ss->heading = xstrdup(item->super.value);
      }
   }
}

static void rebuildSettingsArray(Panel* super, int selected) {
   Settings* settings = g_ctx.settings;
   int n = Panel_size(super);
   free(settings->screens);
   settings->screens = xcalloc(n + 1, sizeof(ScreenSettings*));
   for (int i = 0; i < n; i++) settings->screens[i] = ((ScreenListItem*)Panel_get(super, i))->ss;
   settings->nScreens = n;
   if (selected > n - 1) selected = n - 1;
   else if (selected < 0) selected = 0;
   settings->ssIndex = selected;
   settings->ss = settings->screens[selected];
}

static void startRenaming(Panel* super) {
   ScreensData* d = super->data;
   ListItem* item = (ListItem*)Panel_getSelected(super);
   if (!item) return;
   d->renaming = true;
   super->cursorOn = true;
   char* name = item->value;
   d->saved = name;
   strncpy(d->buffer, name, SCREEN_NAME_LEN);
   d->buffer[SCREEN_NAME_LEN] = '\0';
   d->cursor = strlen(d->buffer);
   item->value = d->buffer;
   d->renamingItem = item;
   Panel_setSelectionColor(super, PANEL_EDIT);
   super->selectedLen = strlen(d->buffer);
   Panel_setCursorToSelection(super);
}

static HandlerResult ScreensPanel_eventHandlerRenaming(Panel* super, int ch) {
   ScreensData* d = super->data;
   if (0 < ch && ch < 255 && isprint(ch)) {
      if (d->cursor < SCREEN_NAME_LEN - 1) {
         d->buffer[d->cursor] = (char)ch;
         d->cursor++;
         d->buffer[d->cursor] = 0;
         super->selectedLen = strlen(d->buffer);
         Panel_setCursorToSelection(super);
      }
   } else {
      switch (ch) {
      case 127:
      case KEY_BACKSPACE:
         if (d->cursor > 0) {
            d->cursor--;
            d->buffer[d->cursor] = '\0';
            super->selectedLen = strlen(d->buffer);
            Panel_setCursorToSelection(super);
         }
         break;
      case 0x0a:
      case 0x0d:
      case KEY_ENTER: {
         ListItem* item = (ListItem*)Panel_getSelected(super);
         if (!item) break;
         free(d->saved);
         item->value = xstrdup(d->buffer);
         d->renaming = false;
         super->cursorOn = false;
         Panel_setSelectionColor(super, PANEL_SELECTION_FOCUS);
         ScreensPanel_update(super);
         break;
      }
      case 27: {
         ListItem* item = (ListItem*)Panel_getSelected(super);
         if (!item) break;
         item->value = d->saved;
         d->renaming = false;
         super->cursorOn = false;
         Panel_setSelectionColor(super, PANEL_SELECTION_FOCUS);
         break;
      }
      }
   }
   return HANDLED;
}

static void addNewScreen(Panel* super) {
   const char* name = "New";
   ScreenSettings* ss = Settings_newScreen(g_ctx.settings, name, "PID Command", "PID");
   /* Settings_newScreen appended to settings array; rebuild handles ordering */
   ScreenListItem* item = ScreenListItem_new(name, ss);
   int idx = Panel_getSelectedIndex(super);
   Panel_insert(super, idx + 1, (Item*)item);
   Panel_setSelected(super, idx + 1);
}

static HandlerResult ScreensPanel_eventHandlerNormal(Panel* super, int ch) {
   ScreensData* d = super->data;
   int selected = Panel_getSelectedIndex(super);
   ScreenListItem* oldFocus = (ScreenListItem*)Panel_getSelected(super);
   bool shouldRebuildArray = false;
   HandlerResult result = IGNORED;
   switch (ch) {
   case 0x0a:
   case 0x0d:
   case KEY_ENTER:
   case KEY_MOUSE:
   case KEY_RECLICK: {
      d->moving = !d->moving;
      Panel_setSelectionColor(super, d->moving ? PANEL_SELECTION_FOLLOW : PANEL_SELECTION_FOCUS);
      ListItem* item = (ListItem*)Panel_getSelected(super);
      if (item) item->moving = d->moving;
      result = HANDLED;
      break;
   }
   case EVENT_SET_SELECTED:
      result = HANDLED;
      break;
   case KEY_NPAGE:
   case KEY_PPAGE:
   case KEY_HOME:
   case KEY_END:
      Panel_onKey(super, ch);
      break;
   case KEY_F(2):
   case KEY_CTRL('R'):
      startRenaming(super);
      result = HANDLED;
      break;
   case KEY_F(5):
   case KEY_CTRL('N'):
      addNewScreen(super);
      startRenaming(super);
      shouldRebuildArray = true;
      result = HANDLED;
      break;
   case KEY_UP:
      if (!d->moving) { Panel_onKey(super, ch); break; }
      /* fallthrough */
   case KEY_F(7):
   case '[':
   case '-':
      Panel_moveSelectedUp(super);
      shouldRebuildArray = true;
      result = HANDLED;
      break;
   case KEY_DOWN:
      if (!d->moving) { Panel_onKey(super, ch); break; }
      /* fallthrough */
   case KEY_F(8):
   case ']':
   case '+':
      Panel_moveSelectedDown(super);
      shouldRebuildArray = true;
      result = HANDLED;
      break;
   case KEY_F(9):
      if (Panel_size(super) > 1) Panel_remove(super, selected);
      shouldRebuildArray = true;
      result = HANDLED;
      break;
   default:
      if (ch < 255 && ch > 0 && isalpha(ch)) result = Panel_selectByTyping(super, ch);
      if (result == BREAK_LOOP) result = IGNORED;
      break;
   }
   ScreenListItem* newFocus = (ScreenListItem*)Panel_getSelected(super);
   if (newFocus && oldFocus != newFocus) {
      ColumnsPanel_fill(d->columns, newFocus->ss);
      result = HANDLED;
   }
   if (shouldRebuildArray) rebuildSettingsArray(super, Panel_getSelectedIndex(super));
   if (result == HANDLED) ScreensPanel_update(super);
   return result;
}

static HandlerResult ScreensPanel_eventHandler(Panel* super, int ch) {
   ScreensData* d = super->data;
   if (d->renaming) return ScreensPanel_eventHandlerRenaming(super, ch);
   return ScreensPanel_eventHandlerNormal(super, ch);
}

static void ScreensPanel_destroy(Panel* this) {
   ScreensData* d = this->data;
   if (d->renaming) {
      ListItem* item = d->renamingItem;
      if (item) item->value = d->saved ? d->saved : xstrdup("");
   }
   free(d);
   Panel_done(this);
   free(this);
}

static Panel* ScreensPanel_new(Settings* settings, Panel** columnsOut) {
   Panel* super = Panel_new(1, 1, 1, 1, true, FunctionBar_new(ScreensFunctions, NULL, NULL));
   ScreensData* d = xcalloc(1, sizeof(ScreensData));
   super->data = d;
   super->eventHandler = ScreensPanel_eventHandler;
   super->destroy = ScreensPanel_destroy;
   d->columns = ColumnsPanel_new(settings->screens[0]);
   super->cursorOn = false;
   Panel_setHeader(super, "Screens");
   for (int i = 0; i < settings->nScreens; i++) {
      ScreenSettings* ss = settings->screens[i];
      Panel_add(super, (Item*)ScreenListItem_new(ss->heading, ss));
   }
   *columnsOut = d->columns;
   return super;
}

/* ======================= Categories ======================= */
static void makeDisplayOptionsPage(void) {
   ScreenManager_add(g_ctx.scr, DisplayOptionsPanel_new(g_ctx.settings), -1);
}
static void makeHeaderOptionsPage(void) {
   ScreenManager_add(g_ctx.scr, HeaderOptionsPanel_new(), -1);
}
static void makeMetersPage(void) {
   int columns = HeaderLayouts[g_ctx.header->headerLayout].columns;
   Panel** meterPanels = xcalloc(columns, sizeof(Panel*));
   for (int i = 0; i < columns; i++) {
      char title[32];
      xsnprintf(title, sizeof(title), "Column %d", i + 1);
      meterPanels[i] = MetersPanel_new(title, g_ctx.header->columns[i]);
      if (i != 0) {
         ((MetersPanelData*)meterPanels[i]->data)->leftNeighbor = meterPanels[i - 1];
         ((MetersPanelData*)meterPanels[i - 1]->data)->rightNeighbor = meterPanels[i];
      }
      ScreenManager_add(g_ctx.scr, meterPanels[i], 20);
   }
   Panel* available = AvailableMetersPanel_new(meterPanels, columns);
   ScreenManager_add(g_ctx.scr, available, -1);
}
static void makeScreensPage(void) {
   Panel* columns;
   Panel* screens = ScreensPanel_new(g_ctx.settings, &columns);
   Panel* availableColumns = AvailableColumnsPanel_new(columns);
   ScreenManager_add(g_ctx.scr, screens, 20);
   ScreenManager_insert(g_ctx.scr, columns, 20, 2);
   ScreenManager_insert(g_ctx.scr, availableColumns, -1, 3);
}
static void makeColorsPage(void) {
   ScreenManager_add(g_ctx.scr, ColorsPanel_new(), -1);
}

typedef struct { const char* name; void (*ctor)(void); } CategoryPage;
static const CategoryPage categoriesPages[] = {
   { "Display options", makeDisplayOptionsPage },
   { "Header layout", makeHeaderOptionsPage },
   { "Meters", makeMetersPage },
   { "Screens", makeScreensPage },
   { "Colors", makeColorsPage },
};

static HandlerResult CategoriesPanel_eventHandler(Panel* super, int ch) {
   HandlerResult result = IGNORED;
   int selected = Panel_getSelectedIndex(super);
   switch (ch) {
   case EVENT_SET_SELECTED:
      result = HANDLED;
      break;
   case KEY_UP:
   case KEY_CTRL('P'):
   case KEY_DOWN:
   case KEY_CTRL('N'):
   case KEY_NPAGE:
   case KEY_PPAGE:
   case KEY_HOME:
   case KEY_END: {
      int previous = selected;
      Panel_onKey(super, ch);
      selected = Panel_getSelectedIndex(super);
      if (previous != selected) result = HANDLED;
      break;
   }
   default:
      if (0 < ch && ch < 255 && isgraph((unsigned char)ch)) result = Panel_selectByTyping(super, ch);
      if (result == BREAK_LOOP) result = IGNORED;
      break;
   }
   if (result == HANDLED) {
      destroyPanelRange(g_ctx.scr, 1);
      selected = Panel_getSelectedIndex(super);
      if (selected >= 0 && selected < (int)ARRLEN(categoriesPages)) categoriesPages[selected].ctor();
   }
   return result;
}

void Setup_run(State* st) {
   Settings* settings = st->host->settings;
   ScreenManager* scr = ScreenManager_new(st->header, st->host, st, true);
   g_ctx.st = st;
   g_ctx.scr = scr;
   g_ctx.header = st->header;
   g_ctx.host = st->host;
   g_ctx.settings = settings;
   Panel* cat = Panel_new(1, 1, 1, 1, true, FunctionBar_new(EmptyDoneFunctions, NULL, NULL));
   cat->eventHandler = CategoriesPanel_eventHandler;
   Panel_setHeader(cat, "Categories");
   for (size_t i = 0; i < ARRLEN(categoriesPages); i++) Panel_add(cat, (Item*)ListItem_new(categoriesPages[i].name, 0));
   ScreenManager_add(scr, cat, 16);
   categoriesPages[0].ctor();
   ScreenManager_run(scr, NULL, NULL, "Setup");
   destroyPanelRange(scr, 0);
   ScreenManager_delete(scr);
   if (settings->changed) {
      CRT_setMouse(settings->enableMouse);
      Header_writeBackToSettings(st->header);
   }
}
