static bool readDiskStats(unsigned long long* rd, unsigned long long* wr, unsigned long long* ms, unsigned long long* num) {
   FILE* fp = fopen("/proc/diskstats", "r");
   if (!fp) return false;
   char last[32] = "";
   unsigned long long rs = 0, ws = 0, ts = 0, n = 0;
   char line[512];
   while (fgets(line, sizeof(line), fp)) {
      char name[32];
      unsigned long long r, w, t;
      if (sscanf(line, "%*d %*d %31s %*u %*u %llu %*u %*u %*u %llu %*u %*u %llu", name, &r, &w, &t) == 4) {
