         snprintf(last, sizeof(last), "%s", name);
         rs += r; ws += w; ts += t; n++;
      }
   }
   fclose(fp);
   *rd = 512 * rs; *wr = 512 * ws; *ms = ts; *num = n;
   return true;
}

static void updateDisk(Machine* host) {
