/* ---- Network IO ---- */
static int netStatus = RATESTATUS_INIT;
static uint64_t netLastUpdate;
static unsigned long long netRxBTotal, netTxBTotal, netRxPTotal, netTxPTotal;
static double netRx, netTx; /* KiB/s */
static unsigned int netRxP, netTxP;
static void updateNet(Machine* host) {
   uint64_t passed = host->realtimeMs - netLastUpdate;
   if (passed <= 500) return;
   FILE* f = fopen("/proc/net/dev", "r");
   bool has = f != NULL;
   unsigned long long rxB = 0, txB = 0, rxP = 0, txP = 0;
   if (f) {
      char line[512];
      while (fgets(line, sizeof(line), f)) {
         char* colon = strchr(line, ':');
         if (!colon) continue;
         char name[64];
         char* p = line; while (*p == ' ') p++;
         size_t l = colon - p; if (l >= sizeof(name)) l = sizeof(name) - 1;
         memcpy(name, p, l); name[l] = 0;
         if (str_eq(name, "lo")) continue;
         unsigned long long rb, rp, tb, tp;
         if (sscanf(colon + 1, "%llu %llu %*u %*u %*u %*u %*u %*u %llu %llu", &rb, &rp, &tb, &tp) == 4) {
            rxB += rb; rxP += rp; txB += tb; txP += tp;
         }
      }
      fclose(f);
   }
   if (!has) netStatus = RATESTATUS_NODATA;
   else if (netLastUpdate == 0) netStatus = RATESTATUS_INIT;
   else if (passed > 30000) netStatus = RATESTATUS_STALE;
   else netStatus = RATESTATUS_DATA;
   netLastUpdate = host->realtimeMs;
   if (has) {
      unsigned long long d;
      d = rxB > netRxBTotal ? rxB - netRxBTotal : 0; netRx = (double)(d / 1024) / passed * 1000.0; netRxBTotal = rxB;
      d = txB > netTxBTotal ? txB - netTxBTotal : 0; netTx = (double)(d / 1024) / passed * 1000.0; netTxBTotal = txB;
      d = rxP > netRxPTotal ? rxP - netRxPTotal : 0; netRxP = (unsigned int)(d * 1000 / passed); netRxPTotal = rxP;
      d = txP > netTxPTotal ? txP - netTxPTotal : 0; netTxP = (unsigned int)(d * 1000 / passed); netTxPTotal = txP;
   }
}
static const int NetworkIOMeter_attributes[] = { METER_VALUE_IOREAD, METER_VALUE_IOWRITE };
static void NetworkIOMeter_updateValues(Meter* this) {
   updateNet(this->host);
   if (rateStatusText(netStatus, this->txtBuffer, sizeof(this->txtBuffer))) return;
   this->values[0] = netRx;
   this->values[1] = netTx;
   if (netRx + netTx > this->total) this->total = netRx + netTx;
   char r[32], t[32];
   Meter_humanUnit(r, netRx, sizeof(r));
   Meter_humanUnit(t, netTx, sizeof(t));
   xsnprintf(this->txtBuffer, sizeof(this->txtBuffer), "rx:%siB/s tx:%siB/s (%u/%upps)", r, t, netRxP, netTxP);
}
static void NetworkIOMeter_display(const Meter* this, RStr* out) {
   (void)this;
   if (rateStatusDisplay(netStatus, out)) return;
   char buf[64];
   rs_append(out, CRT_colors[METER_TEXT], "rx: ");
   Meter_humanUnit(buf, netRx, sizeof(buf));
   rs_append(out, CRT_colors[METER_VALUE_IOREAD], buf);
   rs_append(out, CRT_colors[METER_VALUE_IOREAD], "iB/s");
   rs_append(out, CRT_colors[METER_TEXT], " tx: ");
   Meter_humanUnit(buf, netTx, sizeof(buf));
   rs_append(out, CRT_colors[METER_VALUE_IOWRITE], buf);
   rs_append(out, CRT_colors[METER_VALUE_IOWRITE], "iB/s");
   int len = xsnprintf(buf, sizeof(buf), " (%u/%u pps)", netRxP, netTxP);
   rs_appendn(out, CRT_colors[METER_TEXT], buf, len);
}
static const MeterClass NetworkIOMeter_class = {
   .name = "NetworkIO", .uiName = "Network IO", .caption = "Network: ", .description = "Network bytes & packets received/sent per second", .defaultMode = TEXT_METERMODE,
   .maxItems = 2, .total = 100.0, .attributes = NetworkIOMeter_attributes, .dynamicGraphScale = true,
   .updateValues = NetworkIOMeter_updateValues, .display = NetworkIOMeter_display,
};

