   [SCHED_OTHER] = { "Other", SCHED_OTHER, false },
   [SCHED_FIFO] = { "FiFo", SCHED_FIFO, true },
   [SCHED_RR] = { "RoundRobin", SCHED_RR, true },
   [SCHED_BATCH] = { "Batch", SCHED_BATCH, false },
   [4] = { NULL, 4, false },
   [SCHED_IDLE] = { "Idle", SCHED_IDLE, false },
};
static bool policyResetOnFork = false;

static Panel* newPolicyPanel(int preSelectedPolicy) {
   Panel* this = Panel_new(1, 1, 1, 1, true, FunctionBar_newEnterEsc("Select ", "Cancel "));
   Panel_setHeader(this, "New policy:");
   Panel_add(this, (Item*)ListItem_new(policyResetOnFork ? "Reset on fork: on" : "Reset on fork: off", -1));
   for (unsigned int i = 0; i < ARRLEN(policies); i++) {
      if (!policies[i].name) continue;
      Panel_add(this, (Item*)ListItem_new(policies[i].name, policies[i].id));
      if (policies[i].id == preSelectedPolicy) Panel_setSelected(this, i);
   }
   return this;
}

static Panel* newPriorityPanel(int policy, int preSelectedPriority) {
   if (policy < 0 || (unsigned)policy >= ARRLEN(policies) || !policies[policy].name) return NULL;
   if (!policies[policy].prio) return NULL;
   int mn = sched_get_priority_min(policy);
   if (mn < 0) return NULL;
   int mx = sched_get_priority_max(policy);
   if (mx < 0) return NULL;
   Panel* this = Panel_new(1, 1, 1, 1, true, FunctionBar_newEnterEsc("Select ", "Cancel "));
   Panel_setHeader(this, "Priority:");
   for (int i = mn; i <= mx; i++) {
      char buf[16];
      xsnprintf(buf, sizeof(buf), "%d", i);
      Panel_add(this, (Item*)ListItem_new(buf, i));
      if (i == preSelectedPriority) Panel_setSelected(this, i);
   }
   return this;
}

static bool setSchedFn(Process* p, int arg) {
   if (Settings_readonly) return false;
   int policy = arg & 0xffff;
   int prio = arg >> 16;
   struct sched_param param = { .sched_priority = prio };
   if (policyResetOnFork) policy |= SCHED_RESET_ON_FORK;
   return sched_setscheduler(p->pid, policy, &param) == 0;
}

static Htop_Reaction actionSetSchedPolicy(State* st) {
   if (Settings_readonly) return HTOP_KEEP_FOLLOWING;
   Process* p = (Process*)Panel_getSelected((Panel*)st->mainPanel);
   if (!p) return HTOP_KEEP_FOLLOWING;
   static int preSelectedPolicy = SCHED_OTHER;
   static int preSelectedPriority = 50;
   Panel* schedPanel = newPolicyPanel(preSelectedPolicy);
   const ListItem* policy;
   for (;;) {
      policy = (const ListItem*)Action_pickFromVector(st, schedPanel, 18, true);
      if (!policy || policy->key != -1) break;
      policyResetOnFork = !policyResetOnFork;
      ListItem* item = (ListItem*)Panel_get(schedPanel, 0);
      free(item->value);
      item->value = xstrdup(policyResetOnFork ? "Reset on fork: on" : "Reset on fork: off");
   }
   if (policy) {
      preSelectedPolicy = policy->key;
      Panel* prioPanel = newPriorityPanel(policy->key, preSelectedPriority);
      if (prioPanel) {
         const ListItem* prio = (const ListItem*)Action_pickFromVector(st, prioPanel, 14, true);
         if (prio) preSelectedPriority = prio->key;
         Panel_delete(prioPanel);
      }
      int prio = policies[preSelectedPolicy].prio ? preSelectedPriority : 0;
      bool ok = MainPanel_foreachRow(st->mainPanel, setSchedFn, preSelectedPolicy | (prio << 16), NULL);
      if (!ok) beep();
   }
   Panel_delete(schedPanel);
   return HTOP_REFRESH | HTOP_REDRAW_BAR | HTOP_UPDATE_PANELHDR;
}

